    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 60.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits after this placement -> strong reward
            score -= 45.0;
            // Extra reward proportional to how well next item fills the remaining space
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= next_fill * 25.0;
        } else {
            // Next item won't fit -> penalize, scaled by how close the miss is
            let gap = (next_item_size - post_residual) as f64;
            let gap_frac = gap / bin_capacity as f64;
            score += gap_frac * 40.0;
            // If post_residual is small dead space anyway, slightly forgive
            if post_residual < 10 {
                score -= 10.0;
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize creating tiny unusable slivers (<10) unless it's the last fitting bin
    if post_residual > 0 && post_residual < 10 && fitting_bins_count > 1 {
        score += 30.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 80.0;
    }

    // New-bin candidate handling: discourage opening a new bin when good fits exist,
    // but allow it when open bins are nearly full and the item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open_fill = bin_capacity as f64 - mean_residual;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Open a new bin if existing bins are congested or item is large
        if avg_open_fill > 0.6 * bin_capacity as f64 || item_frac > 0.7 {
            score -= 20.0 + 30.0 * progress;
        } else {
            score += 40.0;
        }
        // Lookahead: a fresh bin can always host the next item too
        if next_item_size > 0 {
            score -= 15.0;
        }
    }

    // Mild pressure to consolidate as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Anything below the minimum item size (1) is impossible, but gaps in
    // the low range (1..=10) are effectively dead space for most streams.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity (small post_residual
    // relative to capacity already handled by base term, add coupling).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score += tightness * 8.0;

    // Open-bin pressure: discourage spreading across many bins when a
    // compact packing is possible; mild penalty grows with open_bins_count.
    score += (open_bins_count as f64).powf(1.3) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item would fit exactly into the post_residual,
    // reward this placement; if next item is larger than post_residual
    // but small enough to matter, penalize blocking it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += (next_item_size - post_residual).min(20) as f64 * 0.8;
        }
    }

    // New-bin candidate handling: an empty bin has zero dead-space risk;
    // make it moderately attractive only when current bin would leave
    // a very poor (tiny) residual, otherwise prefer filling open bins.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
        score = (bin_capacity as f64) * 0.9 + poor_fit * 30.0 - (open_bins_count as f64) * 0.5;
        // If no other bin fits, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Slight progression bias: later in the stream, consolidation matters
    // more; nudge toward bins with below-average residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // realistic future item (items >= 1, but small gaps < ~15 are wasteful)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 * (15.0 - post_residual as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.5 * next_item_size as f64;
        } else {
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Pressure from number of open bins: when many bins are open, prefer
    // filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    // so large gaps stay available for large future items.
    score += 0.4 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: only attractive when no open bin fits well or the
    // item is large relative to the mean residual of open bins.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > mean_residual;
        let no_fitters = fitting_bins_count == 0;
        if poor_fit || no_fitters {
            score -= 25.0 + 0.2 * item_size as f64;
        } else {
            score += 50.0 + 0.5 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than large leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Large leftover space is still somewhat usable; mild reward.
        score -= (post_residual as f64) * 0.15;
    }

    // Tight fit reward relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    score += open_bins_count as f64 * 1.5;

    // If this bin's residual is near the mean residual, it's a "typical" bin;
    // slightly prefer compacting bins with low residual.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        // Next item cannot use this tiny gap anyway; soften the dead-space penalty.
        score -= 15.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by its large flexibility.
        score = 55.0 - (post_residual as f64) * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on a
    // "reusable" residue class (large, item-compatible space) are rewarded.
    let pr = post_residual;
    let residue_class = pr % 10;
    // Dead-space penalty: leftover below the smallest plausible item (<=10)
    // is nearly useless -> strong penalty.
    if pr < 10 {
        score += 60.0;
    } else if pr < 20 {
        score += 15.0;
    }

    // Reward leftovers that can host a wide range of future items.
    // Harmonic tiering via integer division thresholds.
    let tier = pr / 25; // 0..4 tiers
    score -= tier as f64 * 8.0;

    // Lookahead coupling: if the next item fits exactly in the post-residual
    // (perfect chaining), strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after chaining matters
            let chained = pr - next_item_size;
            if chained < 10 {
                score += 10.0; // would create fresh dead space
            } else {
                score -= 12.0;
            }
        } else {
            // next item cannot use this bin's leftover; leftover value drops
            score += 5.0;
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Perfect fit bonus (harmonic alignment with capacity fractions).
    if pr == 0 {
        score -= 50.0;
    } else if bin_capacity % pr == 0 {
        score -= 6.0; // leftover divides capacity evenly -> reusable class
    }

    // Penalize residue classes known to be awkward (odd small remainders).
    if pr >= 10 && residue_class != 0 && residue_class < 5 {
        score += 4.0;
    }

    // Mild pressure toward consolidation when many bins are open.
    score += open_bins_count as f64 * 0.15;

    // Slight preference to fill bins tightly relative to mean residual state.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (post_residual as f64 / cap) * (1.0 - progress) * 5.0;

    // New-bin candidate: neutral baseline with mild conservatism so it is
    // chosen only when open bins score poorly (large/dead leftovers).
    if bin_residual == bin_capacity {
        score = 35.0 + item_size as f64 * 0.2;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 - item_size.min(bin_capacity as u32) {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "usable" residue classes (multiples of common small item sizes).
    let pr = post_residual;
    if pr > 0 {
        // Modulo classes: residuals divisible by 10 are highly reusable.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Integer-division thresholds: tiny dead space is nearly useless.
        let dead = pr < 10;
        if dead {
            score += 12.0;
        }
        // Half-capacity band is prime real estate.
        let half = bin_capacity / 2;
        if pr >= half / 2 && pr <= half {
            score -= 4.0;
        }
    } else {
        // Perfect closure: bin exactly filled.
        score -= 10.0;
    }

    // Coupling with lookahead item: if next item fits post_residual exactly
    // or cleanly (modulo class match), strongly reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 5.0;
        if pr % next_item_size == 0 {
            score -= 4.0;
        }
        if pr - next_item_size < 10 && pr != next_item_size {
            // next item would leave dead space
            score += 3.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item can't use this bin's residue; residue class mismatch penalty
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing bins are crowded and mean residual is small.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64;
        // base cost of a fresh bin, discounted when open bins are tight
        let base = 55.0 - 0.5 * crowd - mean_residual * 0.6;
        score = base + item_size as f64 * 0.3 + progress * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // pairing potential in fresh bin
            score -= (cap - item_size as f64 - next_item_size as f64).max(0.0) * 0.2;
        }
    }

    // Fractional capacity coupling: reward filling bins past 70% of capacity.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac >= 0.7 {
        score -= (fill_frac - 0.7) * 20.0;
    }

    score
}

