    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive if no good fit exists; make the
    // empty bin mildly unattractive so existing bins are preferred.
    if bin_residual == bin_capacity {
        score += 60.0;
