    score -= 8.0 * tightness;

    // Open-bins pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when the
    // fit here is bad (large post residual) or no real pressure exists.
    if bin_residual == bin_capacity {
        score = pr + 5.0 + 1.5 * open_bins_count as f64 - 4.0 * tightness;
        if fitting_bins_count <= 1 {
            score += 40.0; // don't open new bin when an open bin is the last chance
        }
    }

    // Lookahead: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item can't use the gap -> dead space likely
        score += 6.0;
    }

    // Late in stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Slight preference for bins below mean residual (balance load).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            // Perfect two-item pairing: heavily reward.
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits with leftover gap; penalize by the gap size.
            let gap = post_residual - next_item_size;
            score -= 20.0 - gap as f64 * 0.5;
        } else {
            // Next item does NOT fit: dead space risk, penalize.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Normalize lookahead strength by stream progress (stronger early).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score *= 1.0 + 0.3 * (1.0 - progress);
    } else {
        // Last item: just minimize post_residual, slight bonus for exact fill.
        if post_residual == 0 {
            score -= 10.0;
        }
    }

    // Penalize bins whose residual is already far below mean (hoarding space).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.2;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or fit elsewhere would leave big waste.
    if bin_residual == bin_capacity {
        let waste_elsewhere = if next_item_size > 0 && next_item_size > post_residual {
            (next_item_size - post_residual) as f64
        } else {
            0.0
        };
        let penalty = item_size as f64 * 0.5 + waste_elsewhere * 0.4;
        score += penalty;
        // Early in stream, opening bins is cheap; later it is costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if n <= pr {
            let slack_after_next = pr - n;
            score -= 20.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item won't chain here; penalize leaving awkward gaps.
            score += 8.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.25 * item_size as f64;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize consuming scarce residual capacity); later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 12.0 * (bin_residual as f64 / bin_capacity as f64);

    // Global state coupling: if mean residual is high, prefer bins that
    // reduce dispersion (bring residual toward the mean).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Many open bins: encourage filling existing ones rather than opening more.
    score += 0.5 * open_bins_count as f64 * (1.0 - tight);

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 30.0 * large_item;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;

    // Core: squared post-residual (dead space penalized super-linearly)
    let mut score = post * post / cap;

    // Smooth progress coupling: later in the stream, dead space matters more
    score += post * (0.5 + progress) * 0.6;

    // Non-linear fit quality term: reward tight fits smoothly
    score -= (1.0 - (fit - 1.0) * (fit - 1.0)) * 10.0;

    // Interaction: post-residual vs. next item size (smooth lookahead coupling)
    let nxt = next_item_size as f64 / cap;
    if nxt > 0.0 {
        let gap = (post - nxt) / cap;
        score += 8.0 * gap * gap; // post-residual close to next item size is good
        score -= 4.0 * (-gap.abs()) * -1.0; // mild bonus when gap small
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Crowd penalty: many open bins with high mean residual -> prefer consolidation
    let mean_norm = mean_residual / cap;
    score += (open_bins_count as f64).ln() * 2.0 * mean_norm;

    // Smooth new-bin handling: empty candidate gets baseline cost that decays with progress
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - 0.5 * progress) + 5.0 * mean_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction bands. Small leftovers (<= 1/4 of capacity) are
    // "dead space" -> penalize; large leftovers are reusable -> reward.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual <= eighth {
        // Nearly dead space: penalize proportionally to how unusable it is.
        score += (eighth - post_residual) as f64 * 1.5;
    } else if post_residual <= quarter {
        // Small but potentially usable leftover: mild penalty.
        score += 4.0;
    } else {
        // Large leftover: reward keeping the bin flexible.
        score -= (post_residual - quarter) as f64 * 0.4;
    }

    // Modulo-class coupling between post_residual and next_item_size:
    // if the next item exactly (or near-exactly) divides the leftover,
    // this placement sets up a future perfect fit.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0; // chains into a perfect fit next step
        } else if gap <= eighth {
            score -= 8.0;
        } else if gap % 10 == 0 {
            // leftover aligns to a coarse harmonic of the item grid
            score -= 5.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this bin's leftover; leftover likely stranded
        score += 6.0;
    }

    // Integer-division threshold on item size class (harmonic thirds).
    let third = bin_capacity / 3;
    if item_size > 2 * third {
        // Big item: prefer placing it in a tight bin to avoid wasting a
        // large-residual bin on it.
        score += (post_residual as f64) * 0.3;
    } else if item_size <= third {
        // Small item: fine almost anywhere; slight preference for leftover-heavy bins.
        score -= 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current item is large and no good residual exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual >= quarter && fitting_bins_count > 0 {
            // An open bin can take it: discourage new bin.
            score += 20.0;
        } else if item_size > 2 * third {
            score -= 5.0; // big item: fresh bin is reasonable
        }
        // Late in the stream, slightly prefer consolidating into open bins.
        score += progress * 5.0;
    }

    // Mild pressure toward bins below mean residual (balance residual mass).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0; // heavy penalty for unusable slivers
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit: strongly reward
    }

    // Penalize post_residual that cannot fit the next item (lookahead k=2):
    // creates dead space unless a later small item fills it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0; // next item fits here: reward keeping this bin attractive
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferating bins; encourage filling
    // existing ones when many are open.
    let openness = open_bins_count as f64;
    score += openness * 0.8 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than average (better consolidation).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make empty bins mildly unattractive unless the fit
    // here would be terrible (large dead space in an existing bin).
    if bin_residual == bin_capacity {
        score += 15.0 + (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    // Late in the stream, prioritize closing out bins tightly.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step chain: next item exactly fills the remainder.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Partial lookahead reward, decaying with the leftover gap.
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item cannot use the remainder at all: penalize dead space.
            score += 15.0;
        }
    }

    // Reward bins whose residual deviates favorably from the mean (tighter than average).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.15;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist, especially early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * (1.0 - progress) + (open_bins_count as f64) * 2.0;
        // But if no open bin fits well (post_residual would be tiny), allow new bin.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Small penalty for leaving awkward dead space (too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post-residual strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: small unusable post-residuals (below min item size)
    // are pure waste unless zero.
    if post_residual > 0 {
        score += 4.0;
        if post_residual < 10 {
            score += 10.0 * (1.0 - post_residual as f64 / 10.0);
        }
    } else {
        score -= 6.0; // perfect fill
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it mildly unattractive unless the item fits
    // terribly everywhere; empty-bin baseline gets a fixed handicap.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 14.0;
        } else if (post_residual as u32) >= next_item_size {
            score -= 3.0;
        } else {
            // Next item won't fit here: slight penalty proportional to waste.
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Global state coupling: many open bins with high mean residual ->
    // prefer consolidating into bins with residual near mean residual.
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * drift;

    // Time horizon: early in the stream, keep bins open (favor filling
    // existing bins); late in the stream, allow more aggressive new bins
    // since closure effects dominate less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: normalized wasted space, with a non-linear (quadratic) penalty that
    // grows as the stream progresses (dead space matters more later on).
    let x = post / cap;
    let mut score = x + 1.8 * progress * x * x + 0.6 * (1.0 - progress) * x * x * x;

    // Coupling with mean residual across open bins: penalize making this bin's
    // residual deviate far below the mean (fragmentation signal).
    let dev = (mean_residual - post) / cap;
    score += 0.4 * dev * dev * dev.abs().min(2.0);

    // Lookahead: reward residual that can still host the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let snug = (post - nxt) / cap;
            score -= 0.5 * (1.0 - snug) * (1.0 - snug);
        } else {
            // Residual too small for the next item: penalize dead space.
            score += 0.7 * (1.0 - post / nxt.max(1.0)).max(0.0) * (0.5 + progress);
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5 + 2.0 * progress;
    }

    // New-bin candidate: only attractive when nothing fits well; scale with
    // open bins count to discourage unnecessary bin proliferation early.
    if bin_residual == bin_capacity {
        score += 1.2 + 0.15 * open_bins_count as f64 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score += 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual by capacity fraction.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit gets massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize leftovers that fall into "awkward" harmonic classes.
        // Classes based on integer division of capacity: dead space thresholds.
        let class = post_residual / (bin_capacity / 10); // 0..10 coarse class
        match class {
            0 => score -= 40.0,          // tiny leftover: nearly perfect
            1 => score += 10.0,          // 10-19: awkward for small items
            2 => score -= 5.0,           // 20-29: fits mid items
            3 => score += 3.0,
            4 => score -= 8.0,           // 40-49: fits half-capacity items
            5 => score -= 12.0,          // ~half: very reusable
            6 => score += 2.0,
            7 => score -= 4.0,
            8 => score -= 6.0,
            9 => score += 6.0,           // nearly full but not: worst dead space
            _ => {}
        }

        // Modulo arithmetic on post_residual: leftovers divisible by common
        // item sizes (10,20,25,50) are more reusable.
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 5.0; }

        // Lookahead: does post_residual exactly fit the next item? Big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 60.0;
            } else if next_item_size < post_residual {
                // next item fits; reward proportional to how well it fills
                let fill = next_item_size as f64 / pr;
                score -= 15.0 * fill;
            } else {
                // next item cannot fit here: penalize, worse if this was the
                // only fitting bin (chain break).
                score += 8.0;
                if fitting_bins_count == 1 { score += 15.0; }
            }
        }
    }

    // Last-chance bin bonus: if this is the only bin that fits, prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate logic: empty bin should only win when no open bin
    // is attractive. Penalize fresh bins mildly, more when many open bins
    // have slack (mean_residual high).
    if bin_residual == bin_capacity {
        let slack_pressure = (mean_residual / cap).clamp(0.0, 1.0);
        score += 30.0 + 25.0 * slack_pressure + (open_bins_count as f64).sqrt() * 3.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // opening new bin pairs badly if next item is large too
            score += 10.0;
        }
    }

    // Mild preference for tighter bins as stream progresses (first-fit decay).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (bin_residual as f64 / cap);

    // Tie-break toward bins with residual far from mean (keep balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but harshly penalize
    // unusable small gaps (dead space below the minimum item size of 1..10 band).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space: residual too small for any realistic item
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill is ideal
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones.
    // Applied as a penalty on the new-bin candidate only (residual == capacity).
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        // If the next item would fit in the leftover of this new bin, that's fine,
        // but if next item is large and leftover would be small, penalize.
        if next_item_size > post_residual && next_item_size > 0 {
            score += 10.0;
        }
    } else {
        // Reward placing into existing bins, more so as bins accumulate.
        score -= 1.5 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly reward this placement (chained fit).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 30.0;
        } else if diff < 5 {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size as u32 && post_residual < 10 {
            score += 20.0; // would strand dead space before next item
        }
    }

    // Slight preference to keep mean residual balanced: avoid bins far from mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in the stream, be more conservative: avoid creating new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is extremely attractive
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // tighter match to next item => better
            score -= 150.0 / (1.0 + slack / 10.0);
        } else {
            // next item cannot follow into this bin: penalize leftover
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Penalize unusable dead space (residuals too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Compare residual against mean residual of open bins
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer keeping a diverse spread of residuals early; late in stream, close bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    // Mild preference to reuse existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that can never be used by the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * post_residual as f64;
    }
    // Reward leaving exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discourage fragmenting bins with large residuals when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * (bin_residual as f64 - mean_residual) * (1.0 - progress);

    // New-bin candidate handling: neutral baseline, prefer reusing open bins
    // unless the item fits very poorly everywhere.
    if bin_residual == bin_capacity {
        let waste_penalty = 40.0 * (1.0 - fit_ratio).powi(2);
        // Early in the stream, opening new bins is cheap; later it is costly.
        score = bin_capacity as f64 - waste_penalty + 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // Open a new bin if the next item is large and residuals are small.
        if next_item_size > 60 && mean_residual < 25.0 {
            score -= 20.0;
        }
    }

    // Mild preference for bins whose residual is close to the item (perfect nesting).
    let snug = (bin_residual as f64 - item_size as f64).abs();
    score -= 8.0 * (1.0 - snug / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping in normalized progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let poly = 0.6 + 0.5 * p2 - 0.3 * p3;

    let mut score = pr * poly;

    // Reward tight fits: quadratic bonus for small post_residual, stronger late in stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (30.0 + 60.0 * progress);

    // Penalize dead space that is too small for typical items (non-linear trough)
    let dead = if norm_pr > 0.0 && norm_pr < 0.1 { (0.1 - norm_pr) * 200.0 } else { 0.0 };
    score += dead * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 40.0 + 80.0 * progress;
    }

    // Lookahead coupling: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        let fit_next = ((ni <= pr) as i32 as f64);
        score -= fit_next * (ni * 0.5) * (1.0 - norm_pr * 2.0).max(0.0);
        score += gap * 0.15 * progress;
    } else {
        // Last item: prefer fullest packing
        score -= (cap - pr) * 0.5;
    }

    // Mild dispersion pressure: prefer bins deviating from mean residual (consolidation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05 * (1.0 - progress);

    // Slight penalty for proliferating bins late in stream
    score += open_bins_count as f64 * 0.01 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: post_residual mod 10 defines a "waste class".
    // Residues that are small-but-nonzero (1..9 mod 10) are the hardest to reuse later;
    // residues that are 0 mod 10 are "harmonic" and highly reusable.
    let residue_class = post_residual % 10;
    if post_residual > 0 {
        match residue_class {
            0 => score -= 6.0,                    // perfectly harmonic leftover
            1 | 2 | 3 => score += 5.0,            // dead-space risk: too small for anything
            4 | 5 | 6 => score += 2.0,            // moderate risk
            _ => score -= 1.0,                    // 7..9: still fits small items (10..80 range)
        }
    } else {
        score -= 12.0; // perfect fill: zero residual is ideal
    }

    // Integer-division threshold: does the leftover still hold a "half bin" (50) or "third bin" (33)?
    if post_residual >= 50 {
        score -= 4.0;
    } else if post_residual >= 33 {
        score -= 2.0;
    }

    // Lookahead coupling: reward if next item's harmonic class matches the leftover class.
    if next_item_size > 0 && post_residual >= next_item_size {
        // next item fits too: excellent chain placement
        score -= 8.0;
        // bonus if both are harmonic (multiples of 10)
        if item_size % 10 == 0 && next_item_size % 10 == 0 {
            score -= 3.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover is stranded relative to the next item
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // mild penalty proportional to congestion, encouraging consolidation
        score += open_bins_count as f64 * 0.05;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // penalize opening a new bin unless current placement is very poor
        score += 10.0;
        if post_residual > 40 || (fitting_bins_count == 0) {
            score -= 20.0; // then a fresh bin is genuinely better
        }
    }

    // Progress-based drift: late in the stream, tighten up (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.1;

    // Mean-residual anchor: prefer bins below mean residual (tighter than average).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are tiny (unusable for typical items) are costly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        // mid-range gap: mildly penalize unless it fits the lookahead item
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        score += 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins with residual below mean (consolidate small gaps).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual, the better.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Aggressive 2-step lookahead: if the next item fits into post_residual,
    // strongly reward this bin (perfect chain placement).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_waste = post_residual - next_item_size;
        score -= 25.0 + chain_waste as f64 * 0.3;
    } else if next_item_size > 0 {
        // Next item does NOT fit in the leftover: penalize dead space.
        score += (next_item_size as f64) * 0.25;
    }

    // Compare post_residual against mean residual: leaving above-average
    // leftover is wasteful; below-average leftover is efficient.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize the brand-new bin candidate so we prefer reusing open bins
    // when the fit is decent; only allow new bin when open bins are bad.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if the next item is huge and current fit is bad, a fresh bin
        // may be attractive: soften the penalty a bit.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 20 {
            score -= 30.0;
        }
    }

    // Slight late-stream conservatism: as the stream progresses, avoid
    // fragmenting residuals (favor bins whose post_residual is very small).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * progress * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residual too small for any plausible future item.
    if post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Coupling: exact lookahead match is extra attractive.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer filling existing ones over spreading.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    score -= pressure * 3.0;

    // Global residual balance: prefer bins below mean residual (fill emptier-trending bins less).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Time horizon: early in stream, be conservative about creating dead space;
    // late in stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (30.0 - post_residual as f64).max(0.0) * 0.5;

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and item is large (better to start fresh for big items).
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // Base new-bin cost.
        score += 15.0;
        // If item is large and would leave a big hole in existing bins, new bin is OK.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        if fit_quality < 0.2 {
            score -= 10.0;
        }
        // Late in stream, opening new bins is wasteful.
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 0.8 * progress) - 0.5 * x * x + 0.3 * x * x * x * (1.0 - progress);

    // Reward tight fits (small post residual) more strongly late in the stream
    score -= 0.6 * (1.0 - x) * (1.0 - x) * (0.5 + progress);

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 0.4 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 0.3 * (next_item_size as f64 / cap);
    }

    // Penalize creating dead space relative to mean residual
    if pr > 0 {
        score += 0.2 * (pr as f64 - mean_residual).abs() / cap;
    } else {
        score -= 1.0; // perfect fit
    }

    // Last-chance bin: strong reward to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 0.8;
    }

    // Mild preference toward consolidating into fewer bins
    score += 0.05 * (open_bins_count as f64) * x;

    // New-bin candidate: bias against opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 1.2 - 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 0.5 * frac * bin_capacity as f64;

    // Harmonic class: bucket post_residual into capacity-fraction classes.
    // Class 0: post_residual <= 10 (perfect seal), Class 1: <= 25, Class 2: <= 50, else large gap.
    let class = if post_residual == 0 { 0 } else if post_residual <= 10 { 1 } else if post_residual <= 25 { 2 } else if post_residual <= 50 { 3 } else { 4 };
    score += class as f64 * 4.0;

    // Lookahead harmony: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect complementary fit
        } else if next_item_size <= post_residual {
            // modulo-based harmony: how well next item divides the leftover
            let rem = post_residual % next_item_size.max(1);
            let quot = post_residual / next_item_size.max(1);
            score -= 6.0 * (1.0 - rem as f64 / post_residual.max(1) as f64);
            if quot >= 2 { score -= 3.0; }
        } else {
            // next item cannot use the leftover: dead space penalty grows with gap
            score += 2.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Integer-division threshold on post_residual: leftover usable by smallest items (<=10)?
    if post_residual >= 10 {
        score -= 1.5; // leftover can still hold a small item later
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only open a new bin when it creates a full
    // fresh capacity and existing fits are poor (large class) or many bins open.
    if bin_residual == bin_capacity {
        // opening cost, discounted when stream is early or many open bins already congested
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 30.0 + 20.0 * progress;
        if open_bins_count > 8 { open_cost -= 10.0; }
        // if the current item is large, a fresh bin is natural
        if item_size >= 60 { open_cost -= 8.0; }
        score += open_cost;
    }

    // Mild preference to balance residuals against mean (avoid extreme skew).
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    // Tie-break: prefer earlier-opened (denser) bins slightly via residual distance from capacity.
    score += 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps of 1..=10 are almost unusable
    // (min item size historically ~10). Penalize them hard, superlinearly.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 + (10 - post_residual as i32).max(0) as f64 * 3.0;
    }
    // Mid-range awkward gaps (11..=19) are mildly wasteful.
    if post_residual > 10 && post_residual < 20 {
        score += (19 - post_residual as i32).max(0) as f64 * 0.8;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward filling a large fraction of the bin's current space.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 10.0;

    // Open-bin pressure: discourage spreading across many bins when
    // residual capacity is still plentiful on average.
    let avg_usable = mean_residual / open_bins_count.max(1) as f64;
    score += open_bins_count as f64 * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should only win when the fit into existing bins is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progress
        // (later in the stream, wasted capacity matters relatively more).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + progress * 10.0;
        // If lookahead item can combine with this item in a fresh bin,
        // slightly favor opening one.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0;
        }
        // If many bins already fit the item, opening a new one is bad.
        if fitting_bins_count > 1 {
            score += 15.0;
        }
    } else {
        // Placing into an existing bin is rewarded when it leaves a gap
        // the lookahead item could still use.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        // Penalize leaving a gap just below the next item's size
        // (dead space for the known future item).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Slight preference for tighter existing bins over emptier ones.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already favored by the base term.

    // 2-step lookahead: strongly reward bins whose post_residual exactly (or nearly)
    // matches the next item size, so the next item fills this bin perfectly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 25.0; // perfect two-item packing bonus
        }
    } else if next_item_size > 0 {
        // Post-residual too small for next item: penalize dead space that
        // cannot be used by the immediately following item.
        score += 12.0;
    }

    // Penalize creating very small unusable slivers (dead space) that nothing
    // in the typical size range can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below the mean
    // (tighter bins) to keep looser bins available for future items.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // if the item is large relative to capacity (few future reuse chances)
    // or very early in the stream. Otherwise penalize it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_ratio = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 20.0 * size_ratio - 10.0 * (1.0 - progress);
        // If no open bin fits and item is large, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual quadratically.
    score -= 2.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Penalize dead space: post_residual that no future item (10..80) can use.
    if post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual > 80 {
        // large leftover is fine, still reusable
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits the post_residual exactly-ish, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 30.0; // chain fit
        } else {
            score -= 10.0 / (1.0 + slack);
        }
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // next item won't fit here; penalize small-but-wasted leftovers
        if post_residual < next_item_size && post_residual >= 10 {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // unless the fit is terrible (big dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 10 {
            score += 15.0; // but not if it creates a dead sliver
        }
    }

    // New-bin candidate handling: opening a new bin is attractive early in the stream
    // or when many open bins exist (fragmentation risk), unattractive when few bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // late in stream: consolidate, avoid opening bins
        score += 40.0 * progress;
        // many open bins: prefer reusing
        score += 2.0 * open_bins_count as f64;
        // if no existing bin could fit well, allow new bin: handled by other bins' scores
        // small items into fresh bin waste capacity
        score += (100 - item_size.min(100)) as f64 * 0.1;
        // if lookahead is large, a fresh bin is useful
        if next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Global pressure: high mean residual means bins are empty-ish; prefer filling them
    score += 0.3 * (mean_residual - post_residual as f64);

    // Mild diversity term to break ties deterministically
    score += 0.01 * (bin_residual as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let mean_r = mean_residual / cap;

    // Base: prefer tight fits (low post_residual), smoothed by a quadratic term
    let mut score = pr * (1.0 + 0.35 * fit_ratio);

    // Non-linear coupling: post_residual penalized more as stream progresses
    score += 0.8 * (pr * pr) / cap * (0.4 + 0.6 * progress * progress);

    // Interaction of post_residual with mean residual: avoid stranding space when bins are slack
    score += 0.5 * pr * mean_r * (1.0 - progress);

    // Cubic coupling term: smooth penalty for mid-range dead space
    score += 0.15 * (pr / cap).powi(3) * cap * (1.0 + progress);

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 0.6 * nxt * (1.0 - (pr - nxt) / cap);
        } else {
            score += 0.4 * (nxt - pr);
        }
    }

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (0.5 + progress);
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: dead space classes are bad.
    // Class A: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        // Unusable dead space (items >= 10 can never fill it): heavy penalty.
        score += 25.0 + 3.0 * (10 - post_residual) as f64;
    } else if post_residual <= 20 {
        // Only tiny items (10..20) can use it: moderate penalty.
        score += 6.0;
    } else if post_residual <= 34 {
        score += 2.0;
    }

    // Harmonic class via integer division: residual / 10 band.
    let band = post_residual / 10;
    score += (band % 3) as f64 * 0.75;

    // Lookahead: reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_post = post_residual - next_item_size;
        score -= 8.0 - (next_post as f64) * 0.15;
        if next_post == 0 {
            score -= 12.0; // chain of perfect fits
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item can't use this residual: mild penalty, worse in late stream.
        score += 1.5 + 2.0 * progress;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize opening a new bin, unless open bins
    // are nearly full (low mean_residual) or many bins already fit the item.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
        if mean_residual > 0.0 {
            // If mean residual across open bins is small, opening fresh is fine.
            if mean_residual < item_size as f64 {
                score -= 12.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Slight tie-break: prefer fuller bins early (larger item_size fraction used).
    score -= (item_size as f64 / bin_capacity as f64) * 1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < item_size.max(next_item_size) {
        score += 15.0; // residual below next usable size
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: keep room for the next item if it would otherwise not fit anywhere.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
    }

    // Last-chance bin before opening a new one: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: only attractive when current bin leaves terrible dead space.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
        score = 80.0 + bad_fit * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // Perfect fit: dominant reward, always take it.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching against next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Next item exactly seals this bin -> near-perfect 2-item packing.
            score -= 600.0;
        } else if next_item_size as u32 <= post_residual {
            // Next item still fits in the leftover: reward snugness.
            score -= 0.6 * nxt;
        } else {
            // Next item cannot use the leftover: dead-space penalty,
            // extra harsh for tiny unusable slivers.
            score += 0.4 * (nxt - post);
            if post_residual < 8 {
                score += 60.0;
            }
        }
    }

    // Relative-to-mean coupling: compact tighter-than-average bins,
    // keep looser-than-average bins flexible (also penalizes the empty bin).
    score += 0.08 * (bin_residual as f64 - mean_residual);

    // Last-chance open bin: strongly prefer using it over opening a new bin,
    // unless the resulting fit is poor.
    if fitting_bins_count == 1 && !is_new_bin {
        let good_fit = post_residual == 0
            || (next_item_size > 0 && post_residual >= next_item_size)
            || post_residual >= 25;
        if good_fit {
            score -= 400.0;
        } else {
            // Mild nudge only; still allow opening a fresh bin on bad fits.
            score -= 80.0;
        }
    }

    // New-bin candidate: discourage opening bins when existing ones fit well.
    // Penalty grows with stream progress and with the number of open bins,
    // and with the mean residual (plenty of usable space already available).
    if is_new_bin {
        score += 25.0
            + 30.0 * progress
            + 0.3 * open_bins_count as f64
            + 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild nonlinearity
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize small unusable dead space (< 10 is wasted for any item)
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit
    }

    // Lookahead: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.25 * (next_item_size as f64);
        } else {
            // post_residual can't serve next item: dead space penalty scaled by gap
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score += 0.35 * gap;
        }
    }

    // Last chance: strongly prefer using the only bin that fits before opening new
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when current fits are poor
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else {
            (item_size as f64 / bin_capacity as f64) * 0.5
        };
        // Early in stream: open bins cheaply; late: consolidate
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 100.0 - 60.0 * pressure - 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin can chain the next big item too
        }
    }

    // Global state coupling: many open bins with high mean residual -> favor consolidation
    let mean_excess = (mean_residual - post_residual as f64).abs();
    score += 0.15 * mean_excess * (open_bins_count as f64).sqrt();

    // Late-stream tightening: push toward filling residual space fully
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), non-linearly
    let mut score = post * (1.0 + 0.8 * pr * pr);

    // Smooth polynomial coupling of tightness with stream progress:
    // later in the stream, dead space matters more
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward near-perfect fits smoothly (quadratic falloff around zero residual)
    let tightness = (1.0 - pr).clamp(0.0, 1.0);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize large wasted residual super-linearly (dead space)
    score += 0.35 * pr * pr * cap;

    // Last chance bin: strong smooth reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_gap = (post - next_item_size as f64) / cap;
        score -= 5.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty proportional to wasted opportunity
        score += 1.5 * (1.0 - (next_item_size as f64 / cap));
    }

    // Prefer bins below mean residual slightly (balance load smoothly)
    score += 0.5 * (post - mean_residual) / cap;

    // Slight preference to keep open bin count low
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into capacity-fraction classes.
    // Class boundaries at 1/4, 1/3, 1/2 of capacity — dead space below these
    // thresholds is progressively more wasteful.
    let quarter = bin_capacity / 4;
    let third = bin_capacity / 3;
    let half = bin_capacity / 2;

    if post_residual == 0 {
        score -= 50.0; // perfect closure — best possible outcome
    } else if post_residual < quarter {
        score += 40.0; // tiny unusable sliver — heavy penalty
    } else if post_residual < third {
        score += 15.0;
    } else if post_residual > half {
        score -= 10.0; // large residual remains useful
    }

    // Integer-division harmonic class of post_residual: reward residuals that
    // are "friendly" sizes (divisible by common small item sizes 10/20/25).
    if post_residual % 10 == 0 {
        score -= 6.0;
        if post_residual % 20 == 0 { score -= 4.0; }
    }
    if post_residual % 25 == 0 { score -= 5.0; }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap < quarter {
                score += gap as f64 * 0.5; // next item would leave a sliver
            } else {
                score -= 8.0; // next item leaves a healthy residual
            }
        } else {
            // next item won't fit here; residual must stand alone
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless residual would be a tiny sliver.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < quarter { score += 15.0; } // but not if it makes a sliver
    }

    // New-bin candidate handling: neutral-ish baseline so it's chosen only when
    // all open bins score poorly (e.g. all would leave slivers).
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64 * 0.1;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // slightly favor new bin if next item is large (future-proofing)
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= progress * 5.0;
        }
    }

    // Late in the stream, consolidate: penalize spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 2.0 * progress;
    }

    // Mild tie-break: prefer bins whose residual is close to the mean
    // (keeps residual distribution balanced).
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit gets a big reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness reward: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would leave a dead gap here, penalize slightly.
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 10 {
        score += 8.0;
    }

    // New-bin candidate: neutral baseline, slightly above decent fits,
    // but attractive when existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.85 + open_bins_count as f64 * 0.5;
        if mean_residual < 15.0 {
            score -= 10.0; // fragmentation high: opening fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize dead space that likely cannot be filled by typical items
    // (items 1..100, so residuals < 1 are impossible; small residuals are fine,
    // mid-size dead space is bad).
    if post_residual > 0 && post_residual < item_size {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Post residual too small for next item: mild penalty unless it's near zero.
            if post_residual > 0 {
                score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive for large items or when open bins
        // would be left with awkward residuals, but generally prefer filling
        // existing bins unless the fit is poor.
        let best_possible = if item_size <= bin_capacity { 0u32 } else { 0 };
        let waste_here = post_residual; // = capacity - item_size for empty bin
        // Penalize new bin mildly so only genuinely bad fits in open bins trigger it.
        score += 6.0;
        // But if the item is large, a fresh bin wastes less relative space.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        // If open bins are already crowded (low mean residual), a new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 5.0;
        }
        let _ = best_possible;
        let _ = waste_here;
    }

    // Time-horizon modulation: early in the stream, be more conservative with
    // new bins (plenty of items left to fill them); late, prefer tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress); // cheaper to open bins early
    } else {
        score -= 3.0 * progress * tightness; // pack tightly later
    }

    // Global state: many open bins with high mean residual -> discourage
    // spreading waste; prefer bins below mean residual (consolidation).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev; // bins with less residual than mean are favored
        if open_bins_count > 8 && mean_residual > 30.0 {
            score -= 2.0 * tightness;
        }
    }

    // Small stabilizing tie-breaker based on residual magnitude.
    score += 0.01 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit_norm = item_size as f64 / cap;

    // Base: penalize wasted space, quadratically for large dead space
    let mut score = norm_pr + 0.6 * norm_pr * norm_pr;

    // Smooth non-linear coupling: tight fits (small post_residual) are rewarded
    // more strongly as the stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 0.9 * progress * tightness * tightness;

    // Reward filling bins deeply, scaled by remaining stream length
    let remaining = 1.0 - progress;
    score -= 0.4 * fit_norm * (1.0 + remaining);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.5 * (0.5 + 0.5 * progress);
    }

    // Penalty for opening new bins when many bins are already open relative
    // to stream progress (smooth saturation term)
    let density = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 0.3 * density * (1.0 - progress);

    // Lookahead: if the next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 0.7 * fit_quality * fit_quality;
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot
            score += 0.2 * ((nxt - pr) / cap);
        }
    }

    // Mean residual coupling: prefer bins below mean residual (consolidate waste)
    let dev = (mean_residual - pr) / cap;
    score += 0.15 * dev * dev.abs();

    // New-bin candidate: neutral-ish baseline, slightly penalized so it only
    // wins when all open bins score poorly
    if bin_residual == bin_capacity {
        score += 0.5 + 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits, with harmonic emphasis on small dead space.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    score += (post_residual as f64).powi(2) / cap_f * 0.5;

    // Harmonic class of post_residual: residuals that are "useful" multiples
    // of common item-size classes (mod 10 bands) are less penalized.
    let class = post_residual % 10;
    let class_bonus = match class {
        0 => 6.0,                      // perfectly reusable round residual
        1..=3 => 3.0,                  // near-round, still very usable
        8..=9 => -4.0,                 // awkward sliver-like class
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division threshold: residual usable by "medium" items (>=10).
    let usable_slots = post_residual / 10;
    score -= usable_slots as f64 * 1.5;

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward; if next item cannot fit, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should win only when the fit
    // here is terrible (large post_residual, i.e., bad packing).
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; slightly prefer it early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = pr * 0.9 + 5.0 + progress * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Slight penalty for spreading across many open bins when mean residual is high.
    if mean_residual > cap_f * 0.5 && bin_residual < bin_capacity {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (cannot hold even the smallest plausible item) are heavily penalized.
    let min_useful = 10.0_f64.min(bin_capacity as f64);
    if (post_residual as f64) < min_useful && post_residual > 0 {
        score += 40.0 + (min_useful - post_residual as f64) * 4.0;
    }

    // Non-linear penalty on small-but-possibly-usable gaps: quadratic dead-space cost.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let util = 1.0 - pr / bin_capacity as f64;
        score -= 20.0 * util * util; // reward high fill ratio super-linearly
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual is too small for the next item: penalize creating stranded space.
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferating bins when many are already open,
    // unless the fit is excellent.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * (3.0 + 5.0 * progress);

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., tighter bins) to consolidate space.
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // New-bin candidate: an empty bin should only win when the fit into open bins
    // would be poor (large post residual) or no real alternative exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins already fit the item.
        score = (bin_capacity as f64) * 0.5
            + (fitting_bins_count as f64) * 10.0
            + (open_bins_count as f64) * 0.5;
        // If the item is large relative to capacity, opening fresh is more attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
        // Late in the stream, avoid opening bins for marginal gains.
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.19;
    score
