pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * tightness * (item_size as f64);

    // Penalize dead space: residual too small to ever fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: bin remains useful for the next item.
            score -= 0.5 * next_item_size as f64;
        } else {
            // Bad: creates dead space relative to lookahead.
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the fullest (smallest residual already via base).
        score += 0.1 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced when many items remain or
        // when existing bins would leave very awkward residuals.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 15.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            // A fresh bin is flexible for the upcoming item too.
            new_bin_penalty -= 5.0;
        }
        if item_size > 60 {
            // Large items: opening fresh space is often fine.
            new_bin_penalty -= 5.0;
        }
        score += new_bin_penalty;
    }

    // Global state: if mean residual is high, prefer reusing bins (penalize new bins implicitly).
    if mean_residual > (bin_capacity as f64) * 0.5 {
        score += 0.0; // handled via new-bin penalty above
    } else {
        // Low mean residual across bins: scarcity of space, reward compact placements harder.
        score -= 0.2 * tightness;
    }

    // Slight preference to consolidate into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, avoid creating tiny unusable residuals even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 20 {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer small post-residual, with quadratic smoothing over progress.
    let mut score = post * (1.0 + 0.8 * progress) + 12.0 * post_norm * post_norm * (1.0 + progress);

    // Penalize residual that is too small to ever hold a plausible future item
    // (smooth dead-space penalty peaking when post_residual ~ 1..10).
    let dead = ((post - 8.0) / 8.0).powi(2);
    score += 6.0 * (-dead).exp() * (1.0 - post_norm);

    // Last-chance bonus: strongly reward using a bin when it is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Tight-fit reward: interaction between item size and residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: reward leaving room for the next item.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 5.0 * (1.0 - (gap / cap)) * (0.5 + 0.5 * progress);
        } else {
            score += 3.0 * ((-gap) / cap);
        }
    }

    // Mean-residual coupling: prefer bins close to the mean (balance residuals),
    // smoothly scaled by number of open bins.
    let dev = (post - mean_residual) / cap;
    score += (2.0 + 0.3 * open_bins_count as f64) * dev * dev;

    // New-bin candidate: empty bin must lose unless fit is bad everywhere.
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - fit_ratio) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: classify post_residual into
    // capacity-fraction bands. Residuals in low bands (tight fits) are good;
    // residuals that are "dead" (too small for typical items) are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement
    let frac = pr / cap;

    // Dead-space penalty: residual that likely cannot host a future item.
    // Typical items are >= ~10, so residual < 10 is pure waste.
    if post_residual == 0 {
        score -= 40.0; // perfect fit, strongly reward
    } else if post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if frac < 0.25 {
        score -= 12.0; // quarter-or-less residual: very tight, good
    } else if frac < 0.5 {
        score -= 4.0;  // decent
    } else if frac < 0.75 {
        score += 2.0;
    } else {
        score += 6.0;  // mostly empty bin used for a small item: wasteful
    }

    // Harmonic / modulo structure on post_residual: residual classes that
    // align with common item sizes (multiples of 5 and 10) remain reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    } else {
        score += 1.5; // awkward residual unlikely to be exactly reused
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0; // chain placement possible: great
            // Extra reward if next item exactly consumes the residual
            if next_item_size == post_residual {
                score -= 8.0;
            }
        } else if next_item_size <= bin_residual {
            // next item fits this bin only if we place current item elsewhere
            score += 3.0;
        }
    }

    // Last-chance logic: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large or no open bin offers a reasonable fit.
    if bin_residual == bin_capacity {
        // New empty bin: post_residual == capacity - item_size.
        // Prefer new bin for large items (they leave flexible residuals),
        // penalize new bins for small items when open bins exist.
        let large = item_size as f64 / cap;
        if large > 0.5 {
            score -= 8.0 * (large - 0.5) * 2.0;
        } else {
            score += 15.0 * (1.0 - large * 2.0);
        }
        // Early in the stream, opening bins is cheap; later, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If many bins are open, discourage sprawl.
        score += (open_bins_count as f64).sqrt() * 1.5;
    }

    // Slight preference to balance residuals toward the mean: bins far below
    // mean residual are already tight; bins far above mean are wasteful to tap.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild consolidation pressure: fewer open bins is better, so favor bins
    // that keep the count stable (any existing bin over a new one).
    if open_bins_count > 0 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=100
    // interface, but conservatively treat < 10 as dead) are pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect packing (tight fit bonus).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= (20.0 - slack.min(20) as f64) * 0.8;
    } else if next_item_size > 0 {
        // Next item cannot follow here; mildly penalize.
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into more bins
    // unless the fit is tight; with few bins, be more permissive.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += pressure;

    // Prefer bins whose residual is already below average (consolidating waste).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate (empty bin): should only win when all fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 + 30.0 * (1.0 - progress);
        // If nothing fits well elsewhere, new bin becomes attractive.
        if post_residual == bin_capacity - item_size && item_size >= 50 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits exactly into post_residual (near-perfect match) -> reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item does NOT fit here: penalize dead space, worse if residual is tiny.
        let dead = post_residual as f64;
        score += dead * (dead / bin_capacity as f64) * 1.5;
    }

    // Favor bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit well (unless very early).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        score += 10.0 + waste * 0.3 - 15.0 * progress;
    }

    // Prefer consolidating: fewer open bins is better, small effect.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize tiny dead space
    // (< ~10) that is nearly unusable, since item sizes can be as small as 1.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 30.0; // post-residual exactly fits next item: chain fit
        } else if gap > 0 && gap < 10 {
            score += 6.0; // would leave another tiny dead space after next item
        } else if gap < 0 {
            // next item won't fit here anyway; slight penalty scaled by shortfall
            score += ((-gap).min(40) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer fuller bins relative to current mean residual (pack tightly first).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, reward late consolidation.
        score += 15.0 * (1.0 - progress) - 10.0 * progress;
        // If no open bin fits well, opening is natural; if many bins fit, discourage.
        if fitting_bins_count > 2 {
            score += 8.0;
        }
        // A new bin is attractive if the item is large relative to capacity
        // and would leave open bins fragmented.
        score += (item_size as f64 / bin_capacity as f64) * 5.0;
    } else {
        // Late in stream: extra reward for using existing bins.
        score -= 8.0 * progress;
        // Many open bins: encourage consolidation into existing bins.
        score -= (open_bins_count.min(20) as f64) * 0.4;
    }

    // Mild preference for bins whose residual is close to the item (best fit).
    let slack = (bin_residual as i64 - item_size as i64).max(0) as f64;
    score += 0.1 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: penalize post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * x * x);

    // Smooth interaction: small post-residuals are more valuable late in the stream
    let tightness = (1.0 - x).clamp(0.0, 1.0);
    score -= 6.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Cubic dead-space penalty: residuals too small to ever be useful
    score += 8.0 * (x - 0.2) * (x - 0.2) * (x - 0.2) * (x - 0.2) * cap * 0.1 * (1.0 - progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        let nx = next_item_size as f64 / cap;
        score -= 5.0 * (1.0 - nx) * (1.0 + progress);
    } else if next_item_size > 0 {
        // penalize leaving residual that almost but not quite fits next item
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64 / cap;
        score += 4.0 * (1.0 - gap) * (1.0 - gap);
    }

    // Prefer bins tighter than the mean residual (smooth exponential coupling)
    score += 0.15 * (pr - mean_residual).max(-cap) * (0.5 + progress);

    // Mild penalty for spreading across many open bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make empty bins mildly unattractive unless residuals are poor
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress * (1.0 - x);
        // open a new bin when existing residuals are highly fragmented
        score -= 8.0 * (mean_residual / cap - 0.5).clamp(0.0, 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: small leftovers are "dead space".
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual == 0 -> perfect fill, reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Class B: post_residual in a "harmonically usable" range (divisible-friendly small sizes)
    else if post_residual <= 10 {
        score -= 200.0; // near-perfect: leaves a slot for smallest items
    } else if post_residual <= 20 {
        score -= 80.0;
    } else if post_residual <= 30 {
        score -= 30.0;
    } else {
        // Large leftover is fine (bin stays flexible); mild reward scaled by size
        score -= (post_residual as f64) * 0.15;
    }

    // Modulo arithmetic on post_residual: residues that match common item sizes (multiples of 5, 10)
    // are more likely to be filled later.
    let residue_class = post_residual % 10;
    if residue_class == 0 {
        score -= 25.0; // multiple of 10 -> many item sizes can pair with it
    } else if residue_class == 5 {
        score -= 10.0;
    } else {
        score += 8.0; // awkward residue
    }

    // Integer-division threshold: how many "median items" (~30) still fit
    let slots = post_residual / 30;
    score -= slots as f64 * 12.0;

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.5;
        } else {
            // next item won't fit here -> slight penalty if this bin would be left awkward
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current fit is terrible and stream is early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Opening a new bin: penalize as stream progresses and when many bins open.
        score += 60.0 + 120.0 * progress + 3.0 * open_bins_count as f64;
        // But if the item is huge relative to mean residual space, opening is sane
        if (item_size as f64) > mean_residual {
            score -= 90.0;
        }
    }

    // Mild tiebreak: prefer fuller bins (smaller residual) overall.
    score += (bin_residual as f64) * 0.05;

    // Progress-based tightening: late in the stream, waste matters more.
    score += pr * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that likely cannot host future items
    // (small residuals) are heavily penalized, larger residuals are fine.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 3.0 * (dead_threshold - post_residual as f64);
    }

    // Reward very tight fits (post_residual near zero is ideal, but avoid
    // the unusable-gap trap by only rewarding when the gap is truly tiny).
    if post_residual == 0 {
        score -= 15.0;
    } else if (post_residual as f64) < 5.0 {
        score -= 5.0;
    }

    // Penalize creating gaps that can't fit the lookahead item if this bin
    // would otherwise be its only home.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 4.0;
    }
    // Reward leaving exactly enough room for the next item (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a good
    // fit exists; mild penalty proportional to bin count.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when the current fit is bad
    // (large post_residual means this bin was a poor match anyway).
    if bin_residual == bin_capacity {
        // Neutral base; slight bonus if the item is large relative to bin
        // and current fit would leave a big gap.
        if post_residual as f64 > 40.0 {
            score -= 6.0;
        } else {
            score += 8.0;
        }
    }

    // Mild drift: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near-matches of lookahead item (small leftover after next placement)
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + gap);
    }

    // Penalize dead space that no typical item (>=10) can ever use
    if post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to mean residual
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tightness) * 10.0;

    // Compare post_residual against mean residual: leaving less than average is good
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Make the empty new-bin candidate moderately unattractive unless it's a perfect lookahead fit
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize small unusable dead space (hard to fill later).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: penalize if next item cannot fit in post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins with below-mean residual (save roomy bins for big items).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Prefer filling bins when many bins are open (bin consolidation pressure).
    score -= (open_bins_count as f64).sqrt() * (bin_capacity - bin_residual) as f64 * 0.02;

    // Time horizon: early in stream, be more willing to open new bins
    // (keep flexibility); late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early (avoid opening bins prematurely),
        // but late in the stream opening a fresh bin is fine for exact fits.
        score += 40.0 * (1.0 - progress);
        if post_residual == 0 {
            score -= 20.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress (smooth, in [0,1])
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional occupancy of this bin after placement
    let post_frac = post_residual as f64 / cap;
    let item_frac = item_size as f64 / cap;

    // Non-linear polynomial coupling: reward tight fits more aggressively
    // as the stream progresses (quadratic + cubic terms in post_frac).
    let tight = (1.0 - post_frac).powi(2) - (1.0 - post_frac).powi(3);
    score -= 60.0 * (0.3 + 0.7 * progress) * tight * item_frac;

    // Penalize unusable dead space: post_residual too small for the smallest
    // conceivable item (1..=100 range -> threshold ~10 via smooth term).
    let dead = (post_residual as f64 - 1.0).max(0.0);
    let dead_frac = dead / cap;
    score += 25.0 * (1.0 - dead_frac).powi(2) * (1.0 - progress);

    // Lookahead coupling: if the next item fits the post-residual, reward;
    // smooth quadratic interaction between slack and next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post_residual as f64 - nxt).max(0.0);
        let coupling = (post_residual as f64 / (nxt + 1.0)).powi(2);
        if fits_next > 0.0 && post_residual as f64 >= nxt {
            score -= 20.0 * (1.0 - fits_next / cap) * coupling.min(4.0);
        } else {
            score += 15.0 * (nxt / cap) * (1.0 - post_frac);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smoothly damped by progress).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 * (1.0 - 0.3 * progress);
    }

    // New-bin candidate: penalize opening a new bin mildly, more so early on
    // and when many open bins still have room (mean_residual high).
    if bin_residual == bin_capacity {
        let openness = mean_residual / cap;
        score += 45.0 + 30.0 * (1.0 - progress) + 20.0 * openness * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild dispersion penalty: prefer bins whose residual deviates favorably
    // from the mean (below-mean residual = tighter bin = better).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 10.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit: ideal closure of a bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic classes of dead space: residues 1..=9 are nearly unusable
    // (items are >= 1, but tiny residues waste capacity). Penalize by class.
    if post_residual > 0 && post_residual <= 9 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual <= 19 {
        // class [10,19]: moderately awkward
        score += 6.0;
    } else if post_residual <= 49 {
        // class [20,49]: half-capacity zone, still useful
        score += 2.0;
    }

    // Lookahead synergy: if the next item fits exactly into post_residual,
    // strongly reward; if it merely fits, mildly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual - next_item_size <= 9 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    }

    // Lookahead conflict: next item would not fit -> this placement strands it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the item is large (few future
    // fits anywhere) or many bins exist and this fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual < 25;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        } else if poor_fit && open_bins_count > 2 {
            score -= 10.0 * (progress + 0.5);
        } else {
            score += 12.0; // prefer packing into open bins
        }
    }

    // Mild pressure toward bins below mean residual (consolidate slack).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Late in the stream, tighter packing matters more.
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are nearly unusable -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small gap: likely dead space, but slightly usable.
        score += 25.0 - (post_residual as f64);
    } else if post_residual <= 35 {
        score += 8.0;
    } else {
        // Large post_residual means item was small relative to bin; mild
        // penalty proportional to leftover to encourage tighter fits.
        score += 0.15 * (post_residual as f64 - 35.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item can fit exactly into the
    // post_residual, strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - 0.2 * slack;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual can't host the lookahead item -> dead space risk.
        score += 10.0;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when the current bin
    // would leave a bad fit. An empty bin gets a baseline cost equal to
    // the mean residual of open bins (preserving existing structure).
    if bin_residual == bin_capacity {
        score = 50.0 + mean_residual * 0.5 + 1.5 * open_bins_count as f64;
        // Late in the stream, opening new bins is fine (no need to keep
        // many bins open); early on, prefer reusing.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 10.0;
        }
        return score;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 70.0;
    } else if post_residual < 10 {
        score -= 35.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post residual matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual as u32 >= next_item_size {
            // Next item fits perfectly after this placement: big reward.
            score -= (25.0 - gap as f64).max(0.0);
        } else {
            // Next item would not fit: penalize wasted potential.
            score += gap as f64 * 0.35;
        }
    }

    // Compare post residual against mean residual: avoid leaving much more
    // space than average (dead space), but reward below-mean tightness.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.25;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Early in stream, slightly prefer tighter packing to build dense bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.35 };
        score += 12.0 * dead * (post_residual as f64 / bin_capacity as f64);
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Lookahead: reward if next item fits into post-residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This bin blocks the next item; slight penalty.
            score += 4.0;
        }
    }

    // Time horizon: early in the stream, prefer opening new bins to keep
    // residuals flexible; late in the stream, consolidate into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, expensive late.
        score -= 20.0 * (1.0 - progress);
        score += 15.0 * progress;
        // Penalize new bin if many open bins already exist with slack.
        if mean_residual > item_size as f64 {
            score += 6.0;
        }
    } else {
        // Existing bin: slightly favored late in the stream.
        score -= 5.0 * progress;
    }

    // Prefer bins with residuals close to item size (minimize fragmentation).
    let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 10.0 * tightness * tightness;

    // Mild penalty for accumulating too many open bins.
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_n = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr - 2.0 * pr_n * (1.0 - pr_n) * (0.5 + progress);

    // Tight fits rewarded, scaled by progress
    let tightness = 1.0 - pr_n;
    score -= 12.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space that can't fit the next item (smooth quadratic)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).max(0.0) / cap;
        score += 8.0 * gap * gap;
        // Bonus if post residual exactly accommodates next item
        let fit_next = (nxt - pr).abs() / cap;
        score -= 6.0 * (1.0 - fit_next).min(1.0) * tightness;
    }

    // Last-chance bin bonus (smooth in fitting_bins_count)
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 10.0 * scarcity * (0.5 + progress);
    }

    // Mild pressure from mean residual and open bin count
    score += 0.05 * (mean_residual - pr) * (1.0 - progress);
    score += 0.3 * open_bins_count as f64 * pr_n * (1.0 - progress);

    // New-bin candidate: discourage unless residual is large and fits are scarce
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 5.0 * progress * (fitting_bins_count as f64).min(3.0) / 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: group residuals by capacity fraction bands.
    // Residual classes (relative to capacity 100): tiny (<10), small (10..25), medium (25..50), large (>=50).
    let class = if post_residual == 0 { 0 }
        else if post_residual < 10 { 1 }
        else if post_residual < 25 { 2 }
        else if post_residual < 50 { 3 }
        else { 4 };

    // Penalize tiny residuals strongly: dead space, essentially wasted capacity.
    if class == 1 { score += 25.0; }
    if class == 0 { score -= 10.0; } // perfect fit is great

    // Reward keeping residual in a "usable" harmonic class for the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: big reward, scaled by tightness of the two-item fit
            let combined = (item_size + next_item_size) as f64;
            score -= 18.0 * (combined / bin_capacity as f64);
        } else {
            // next item cannot use this bin: penalize proportionally to leftover dead space
            score += 6.0 + 0.15 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Modulo-style arithmetic on post_residual: residuals divisible by common size blocks
    // (10, 20, 25, 50) are more likely reusable by future items.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0;
    } else if post_residual > 0 {
        score += 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // base penalty so a decent existing fit beats opening a new bin
        score += 30.0;
        // but if many open bins are fragmented (high mean residual spread) and few fit,
        // opening fresh is attractive: reduce penalty
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        if mean_residual < 20.0 {
            score -= 8.0;
        }
    }

    // Tight fit reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Slight preference for denser packing late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * fill_ratio;

    // Mild pressure toward fewer open bins when mean residual is low.
    score += 0.05 * (open_bins_count as f64) * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit is excellent
    }

    // Reward bins whose residual after placement can still host mid-size items.
    if post_residual >= 30 {
        score -= 8.0;
    } else if post_residual >= 10 {
        score -= 3.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize if post-residual is a dead gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / 20.0;
    score += pressure * (1.0 + progress);

    // Mean residual coupling: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when open bins would leave terrible gaps
    // or when few bins exist. Make the empty bin moderately costly by default.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        if item_size >= 50 {
            score -= 20.0; // large items may justify a fresh bin
        }
        if progress > 0.8 {
            score -= 10.0; // late stream: consolidation matters less
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> chain two items perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in the post-residual: good lookahead chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward proportional to how snugly the next item fits.
        let slack_after_next = post_residual - next_item_size;
        score -= 25.0 - (slack_after_next as f64).min(25.0);
    }
    // Dead space: next item cannot fit in what remains.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Prefer tight fits relative to mean residual across open bins.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize moderately so it only wins when open bins are hopeless,
    // but make it attractive when many items remain (future flexibility) and mean residual is low.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 70.0 + 30.0 * progress - 0.4 * mean_residual.min(60.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit bonus: strongly reward small post residual (best-fit core).
    let fit_ratio = post_residual as f64 / cap;
    score += 6.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that cannot fit typical future items.
    if post_residual > 0 {
        let dead = if next_item_size > 0 {
            (post_residual < next_item_size) as i32 as f64
        } else { 0.0 };
        score += 8.0 * dead * (1.0 - fit_ratio);
    }

    // Lookahead synergy: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = next_item_size as f64 / cap;
        score -= 5.0 * chain;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: slight penalty to avoid wasting the tightest bin carelessly? keep neutral
        score += 0.5 * (fitting_bins_count.min(10) as f64);
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current bins are fragmented (poor mean residual usage).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        let large_item = item_size as f64 / cap;
        let base_penalty = 18.0;
        let relief = 20.0 * large_item * fragmentation;
        score += (base_penalty - relief).max(2.0);
    } else {
        // Reward using already-open bins, scaled by how full they already are.
        let used = (bin_capacity - bin_residual) as f64 / cap;
        score -= 4.0 * used;
    }

    // Time-horizon modulation: early in the stream, be conservative (favor reuse);
    // late in the stream, tight packing matters most.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (1.0 - fit_ratio);

    // Global balance: nudge toward bins whose residual is near the mean (avoid
    // leaving many half-empty bins while draining one).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: prefer tight fits (low post_residual), with smooth polynomial shaping.
    let norm_pr = pr / cap;
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Stream-progress coupling: early on, tolerate slack; late, squeeze bins.
    score += 12.0 * progress * norm_pr;

    // Dead-space penalty: residuals too small for any plausible item are wasted.
    let dead = ((18.0 - pr) / 18.0).max(0.0);
    score += 20.0 * dead * dead;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening bins, but relax the penalty when
    // existing fits are poor (large post_residual) or late in the stream.
    if is_new_bin {
        let relax = (norm_pr * 1.2).min(1.0);
        score += 30.0 * (1.0 - relax) + 10.0 * (1.0 - progress);
    } else {
        // Mild reward for keeping mean residual balanced (spread usage evenly).
        let dev = (mean_residual - pr) / cap;
        score += 3.0 * dev * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Harmonic class of post_residual: residues divisible by common item sizes
    // (10/20/25/50) are more likely reusable -> reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 20 == 0 { score -= 2.0; }
        if pr % 25 == 0 || pr % 50 == 0 { score -= 2.0; }
        // Dead space: post_residual too small for the smallest plausible item (1..100)
        if pr < 10 { score += 6.0; }
        else if pr < 20 { score += 2.0; }
    } else {
        // Perfect closure is ideal.
        score -= 15.0;
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward when next item fits snugly too.
            score -= 5.0 * (1.0 - slack / (bin_capacity as f64));
            if post_residual == next_item_size { score -= 6.0; }
        } else {
            // Next item won't fit here; penalize leaving awkward gap.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when all open bins fit poorly (high mean residual dispersion) or none fit well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 18.0;
        // If item nearly fills a fresh bin, opening is great.
        new_bin_penalty -= 0.25 * item_size as f64;
        // If the next item is large and would fit in a fresh bin alongside this one,
        // opening a new bin is more attractive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            new_bin_penalty -= 6.0;
        }
        // Late in the stream, avoid spreading across many bins.
        new_bin_penalty += 8.0 * progress;
        // Many open bins with slack: prefer filling existing ones.
        new_bin_penalty += 0.5 * open_bins_count as f64;
        score += new_bin_penalty.max(0.0);
    }

    // Slight preference for bins below mean residual (consolidating emptier bins).
    score += 0.05 * ((bin_residual as f64) - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Dead space penalty: small unusable gaps are the worst outcome ---
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual <= 10 {
            // tiny gap: almost certainly dead space forever
            score += (11.0 - pr) * 18.0;
        } else if post_residual <= 25 {
            score += (25.0 - pr) * 3.0;
        }
        // Perfect fit: strong reward
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // --- Reward filling a bin deeply (high fill ratio) ---
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * fill * 15.0;

    // --- Lookahead: if next item fits the post-residual, reward this placement ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item exactly matches post-residual, bonus
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if next item is large and this bin would be left nearly empty
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // --- Open bins pressure: discourage opening new bins when many are open ---
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin candidate: its post_residual = capacity - item_size.
        // Penalize so we prefer existing bins unless they leave bad dead space.
        score += 55.0 + open_bins_count as f64 * 2.0;
        // But if no existing bin fits well (many fitting bins means alternatives exist)
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere: must open new bin
        } else if fitting_bins_count == 1 {
            // last chance: prefer using the single fitting bin
            score += 20.0;
        }
        // Late in the stream, closing out bins tightly matters less; still prefer reuse
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    } else if fitting_bins_count == 1 {
        // This is the only bin that fits: strong preference to use it
        score -= 30.0;
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter bins) ---
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual with next item is gold.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual == next_item_size {
            score -= 200.0; // perfect two-item pairing
        } else if (post_residual as u32) >= next_item_size {
            // next item still fits here: reward tightness of the pair
            score -= 40.0 - 0.5 * diff;
        } else {
            // next item won't fit: penalize small dead space more than large
            let dead = post_residual as f64;
            score += (60.0 - dead.min(60.0)) * 0.8;
        }
    }

    // Reward tight fits relative to current item (low post_residual is good, unless wasted).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness;

    // Penalize bins far above/below mean residual (avoid fragmenting the bin pool).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64;
        // new bin starts at a mid-range score; beat it only if best open fit is poor
        score = base * 0.55;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can serve the next item too
        }
        if open_bins_count == 0 {
            score -= 500.0; // must open first bin
        }
    }

    // Slight late-stream consolidation pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty makes near-exact fills dominate.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect or near-perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 100.0 - (post_residual as f64) * 5.0;
    }

    // Lookahead coupling: penalize leaving a residual that is awkward for the
    // next item; reward leaving a residual the next item can nearly consume.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let res = post_residual as f64;
        if res >= nxt {
            let gap = res - nxt;
            // Next item fits: reward closeness of that follow-up fit.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 200.0; // chained perfect fill
            }
        } else {
            // Next item cannot use the residual: penalize proportional dead space.
            score += 20.0 * (res / nxt);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // Large items justify fresh bins; small items should use leftovers.
        let size_frac = item_size as f64 / bin_capacity as f64;
        score -= 140.0 * size_frac * size_frac;
        // Early in the stream, fresh bins are cheaper (more future to use them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 80.0 * progress;
        // Many open bins with slack: discourage adding another.
        score += 5.0 * (open_bins_count as f64).sqrt();
    }

    // Global slack context: if mean residual is high, prefer bins below the mean
    // (drain the emptiest-feeling bins first) to consolidate waste.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.5 * diff;
    }

    // Mild penalty for very small items into large-residual bins (waste of big space).
    if item_size <= 20 && post_residual > 60 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post residual with a non-linear (convex) coupling
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in the stream, tighten residual tolerance
    let progress_gain = 0.5 + 2.0 * progress * progress;
    score += norm_pr * progress_gain * cap * 0.25;

    // Reward tight fits: smooth sigmoid-like term on normalized fit ratio
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let tightness = fit_ratio * fit_ratio * (2.0 - fit_ratio).max(0.0);
    score -= tightness * cap * 0.5;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= cap * 0.75;
    } else {
        // Mild penalty when many bins compete (prefer spreading)
        score += (fitting_bins_count as f64).ln() * 3.0;
    }

    // Lookahead coupling: reward leaving room for the next item smoothly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let room = (pr - ni).max(0.0) / cap;
        score -= room * room * cap * 0.6;
        // Penalize if this placement blocks the next item while other bins could take it
        if ni > pr {
            score += ni * 0.15;
        }
    }

    // Mean residual interaction: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.3;

    // Open-bin count pressure: when many bins are open, discourage new-bin-like residuals
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += norm_pr * pressure * 2.0;

    // New-bin candidate: make it moderately attractive only when residuals are scarce
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score = cap * (0.9 - 0.5 * scarcity * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Harmonic classes of post_residual (modulo arithmetic on capacity fractions)
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else if pr % 10 == 0 {
        score -= 8.0; // reusable round residual
    } else if pr < 10 {
        score += 25.0; // tiny dead space, unusable
    } else if pr % 5 == 0 {
        score -= 3.0; // semi-harmonic class
    }

    // Lookahead: does next item fit into resulting gap?
    if next_item_size > 0 {
        if (next_item_size as u32) <= pr {
            score -= 0.35 * next_item_size as f64; // chainable placement
        } else {
            score += 6.0; // next item would need another bin
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: attractive for large items (big item leaves structured gap)
    if bin_residual == bin_capacity {
        score -= 4.0 + 0.08 * item_size as f64;
        if next_item_size > 0 && (next_item_size as u32) <= pr {
            score -= 4.0;
        }
    }

    // Prefer bins whose residual deviates from the mean (consolidate tight bins)
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Mild pressure to reuse open bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.02 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

