    // If next item almost fits, slight penalty (near-miss creates temptation).
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 4.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins would leave bad dead space.
    if bin_residual == bin_capacity {
        // Mild cost for opening a new bin, but the default score (post_residual
        // = capacity - item) already reflects the fresh large residual.
        score += 8.0;
        // If current item is small, opening a new bin wastes capacity.
        if item_size <= 30 {
            score += 15.0;
        }
        // If no existing bin fits well (large dead space elsewhere), ease opening.
