pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - (post / cap);
    score -= 0.6 * tightness * (item_size as f64);

    // Penalize dead space that cannot fit the next item (wasted capacity).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.5 * (1.0 - (post_residual as f64) / (next_item_size as f64)) * 10.0;
    }
    // Reward bins whose leftover fits the next item exactly-ish (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.25 * (post_residual as f64 - next_item_size as f64).abs().min(10.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
