    } else if fitting_bins_count > 1 {
        // Slight penalty when many bins fit, to encourage spreading load
        score += 0.3 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin gets a baseline near cap,
    // discounted when open bins are crowded or item is large.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowdedness = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score = cap - 6.0 * crowdedness - 4.0 * progress;
        // Prefer opening a new bin for large items that leave unusable slivers elsewhere
        if item_size > bin_capacity / 2 {
            score -= 3.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
        return score;
    }

    // Prefer bins with below-average residual (consolidate fuller bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Mild time-based nudge: later in the stream, be more conservative with waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let w = 4.0 * progress * (1.0 - progress); // peaks mid-stream
    score -= w * 12.0 * (1.0 - norm_pr * norm_pr);

    // Reward tight fits more strongly as stream progresses (quadratic in progress)
    let tight = 1.0 - norm_pr;
    score -= tight * tight * (30.0 * progress + 10.0);

    // Penalize dead space that is too small to fit typical items (smooth logistic-like)
    let dead = norm_pr * (1.0 - norm_pr); // small when pr near 0 or near cap
    score += 6.0 * (1.0 - 4.0 * dead) * 0.5;

    // Lookahead coupling: reward leaving space for the next item (smooth)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_next = (pr - ns) / cap;
        let good = 1.0 / (1.0 + (-fit_next * 8.0).exp());
        score -= 8.0 * good * (0.5 + 0.5 * progress);
    } else {
        // last item: strongly prefer zero residual
        score -= tight * 20.0;
    }

    // Last-chance bin bonus (smooth in fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for proliferating bins relative to mean residual
    score += (open_bins_count as f64).sqrt() * 0.5 * (mean_residual / cap - norm_pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "clean" the leftover is.
    // Residuals divisible by common item sizes (10,20,25,50) are reusable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        60.0 // perfect fit
    } else if pr % 50 == 0 {
        40.0
    } else if pr % 25 == 0 {
        25.0
    } else if pr % 20 == 0 {
        20.0
    } else if pr % 10 == 0 {
        12.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize small dead space: residuals in (0,10) are almost unusable.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 35.0;
        } else if pr >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - pr) as f64 * 0.5;
        }
        // Next item leaves a harmonic residue?
        if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: prefer opening a new bin only when the fit here is poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; make it competitive with bad fits.
        score += 55.0;
        // If current item is large relative to capacity, a fresh bin is fine.
        score -= item_size as f64 * 0.15;
        // Late in the stream, avoid spreading bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    } else {
        // Reward tight fits relative to capacity fraction.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= fill * 25.0;
        // Prefer bins with larger residual among equally tight fits.
        score += (bin_residual as f64 - mean_residual) * 0.05;
        // Many open bins: encourage consolidation.
        if open_bins_count > 4 {
            score -= 3.0;
        }
    }

    // Integer-division threshold: reward placing into bins where the item
    // roughly halves or thirds the residual (good partitioning).
    if bin_residual >= item_size && bin_residual > 0 {
        let q = bin_residual / item_size.max(1);
        if q >= 2 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Post-residual that cannot fit even the smallest plausible next item is dead space.
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += post_residual as f64 * 2.0;
    }

    // Reward tight fits (waste ratio).
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 12.0;

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin before opening a new one: strong bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: mild penalty for stranded space.
        score += 4.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.0 * (1.0 - fill)) * (0.5 + 0.5 * progress);

    // Compare against mean residual: bins with much larger residual than average
    // are good candidates for big items (preserve tight bins).
    if (bin_residual as f64) > mean_residual * 1.25 {
        score -= 3.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., item is large relative to available residuals or fits are scarce).
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let large_item = item_size as f64 / bin_capacity as f64;
        // Default: opening a new bin is mildly penalized so good fits win.
        score += 20.0;
        // But open a fresh bin for large items or when this is the only option.
        score -= scarcity * 40.0;
        score -= large_item * 18.0 * (1.0 - scarcity);
        // Early in the stream, opening bins is cheaper.
        score -= (1.0 - progress) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: post_residual == 0 is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_gap = (post_residual - next_item_size) as f64;
        // Strong reward when next item exactly fills the residual afterwards
        score -= 200.0 * (1.0 - lookahead_gap / bin_capacity as f64);
        // Penalize leaving a residual that is too small for the next item (dead space)
    } else if next_item_size > 0 {
        // post_residual cannot fit next item: dead space penalty
        score += 50.0 + (post_residual as f64).sqrt() * 10.0;
    }

    // Penalize large leftover residuals relative to mean residual (wasteful bins)
    let mean_diff = post_residual as f64 - mean_residual;
    if mean_diff > 0.0 {
        score += mean_diff * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it unattractive unless all else is bad
    if bin_residual == bin_capacity {
        score += 300.0;
    }

    // Slight preference for tighter fits as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

