        // Extra reward for exact two-item chain
        if post_residual == next_item_size {
            score -= 100.0;
        }
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer opening a new bin when existing fits are poor (large post_residual)
        // or when many bins are open with high fragmentation
        let frag = mean_residual / bin_capacity as f64;
        score = 100.0 - 40.0 * frag;
        if post_residual >= next_item_size && next_item_size > 0 {
            score += 50.0; // keep new bin clean for next item
        }
        if fitting_bins_count == 1 {
            score += 200.0; // strongly prefer using the only fitting bin
        }
    }

    // Time horizon: late in stream, consolidate more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty proportional to fragmentation of the bin pool
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

