    let pr = post_residual as f64 / cap;
    let br = bin_residual as f64 / cap;
    let it = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear emphasis
    let mut score = pr * pr * 40.0 + pr * 20.0;

    // Smooth polynomial coupling of fit quality with stream progress:
    // early on, tolerate imperfect fits; late, demand tight fits.
    let tightness = 1.0 - pr;
    score -= (tightness * tightness) * (10.0 + 60.0 * progress * progress);

    // Penalize dead space relative to mean residual across open bins
    let dev = pr - mean_residual / cap;
    score += dev * dev * 25.0;

    // Reward bins whose residual is close to the item (smooth kernel)
    let fit_gap = br - it;
    score -= (-fit_gap * fit_gap * 8.0).exp() * 12.0 * (1.0 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
