    }

    // Lookahead: if next item fits the post-residual well, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= (-gap * gap * 20.0).exp() * 15.0;
        } else {
            score += (-gap) * 10.0;
        }
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate: keep it attractive early, discourage late
    if bin_residual == bin_capacity {
