pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: how "usable" is the leftover space
    let pr = post_residual;
    if pr > 0 {
        // Class by capacity fraction: leftover usable if >= typical small item (>= 10)
        let usable = (pr >= 10) as i32 as f64;
        score -= 40.0 * usable;

        // Modulo classes: leftover congruent to small sizes (mod 10) is easier to fill later
        let m = pr % 10;
        let class_bonus: f64 = match m {
            0 => 60.0, // round leftover, very flexible
            1..=3 => 30.0,
            4..=6 => 10.0,
            _ => -20.0, // awkward remainder
        };
        score -= class_bonus;

        // Integer division thresholds: leftover in "large-item compatible" zone
        let half = pr / (bin_capacity / 2);
        if half >= 1 {
            score -= 25.0; // leftover >= 50, can host almost any future item
        } else if pr >= 30 {
            score -= 10.0;
        } else {
            score += 15.0; // dead space below 30
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (next_item_size as f64 / cap);
        } else {
            score += 30.0; // next item won't fit here anyway
        }
    }

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave tiny waste
    if bin_residual == bin_capacity {
        // opening fresh bin is fine only if item is large relative to capacity
        let item_frac = item_size as f64 / cap;
        score += 120.0 * (1.0 - item_frac);
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 40.0; // pairing opportunity exists, but fresh bin keeps options open
        }
    }

    // Stream progression: late in stream, be greedier about filling bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * (post_residual as f64 / cap);

    // Prefer bins below mean residual (tighter bins) to consolidate waste
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
