    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) — already the base term.

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space that is too small to be useful later (min item 1).
        if post_residual < 10 {
            score += 12.0; // nearly unusable sliver
        }
        // Reward residuals that could fit typical upcoming items.
        if post_residual >= 20 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: if next item fits in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            score += 8.0; // item blocks the natural follow-up placement
        }
        // Exact two-item fill is excellent.
        if next_item_size == post_residual {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
        // Extra reward if this bin would otherwise be wasted.
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // New-bin candidate logic: empty bin gets a moderate penalty so we prefer
    // reusing open bins unless fits are poor, but reward opening a new bin when
    // the stream is young and many items remain.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in the stream: opening new bins is cheap; late: expensive.
        score += 20.0 * progress;
        // If many bins already open, discourage spreading further.
        score += open_bins_count as f64 * 1.5;
        // But if the current item is large, a fresh bin is fine.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Global pressure: when mean residual is low (bins nearly full), prefer
    // placements that keep residuals usable; when mean residual is high,
    // consolidation into fuller bins is preferred.
    let tightness = 1.0 - mean_residual / bin_capacity as f64;
    score -= tightness * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Slight preference to fill bins that are already relatively full.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Time horizon: early on, keep flexibility (avoid tiny residuals);
    // near the end, squeeze as much as possible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && post_residual > 0 {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with a non-linear penalty for
    // awkward leftover space (small-but-nonzero residuals are dead space).
    let mut score = pr_norm;
    score += 0.35 * pr_norm * (1.0 - pr_norm);

    // Smooth interaction of post-residual with stream progress:
    // early on, keep bins flexible (favor larger residuals); late, pack tight.
    let flexibility = (1.0 - progress) * (1.0 - progress);
    score -= 0.25 * flexibility * pr_norm;
    score += 0.20 * progress * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Non-linear coupling with mean residual: if this bin's leftover is far
    // below the mean, its space is scarce -> reward using it.
    let mean_norm = mean_residual / cap;
    let scarcity = (mean_norm - pr_norm).max(0.0);
    score -= 0.15 * scarcity * scarcity;

    // Lookahead: reward if next item fits the post-residual (smooth affinity).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_affinity = (-gap / 20.0).exp();
        score -= 0.30 * fit_affinity;
    } else {
        // Last item: pack as tightly as possible.
        score += 0.30 * pr_norm * pr_norm;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 1.5;
    } else if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64).ln();
    }

    // Mild penalty for proliferating bins early on.
    score += 0.02 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to capacity or no good fit exists (smooth, not piecewise).
    if bin_residual == bin_capacity {
        let largeness = item_size as f64 / cap;
        score += 0.6 - 0.8 * largeness * largeness;
        score += 0.4 * flexibility;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit the smallest
    // plausible item are pure waste; penalize them heavily.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit is ideal, but avoid overflow risk
    } else if post_residual <= 10 {
        // Unusable tiny gap -> dead space penalty proportional to tightness
        score += (12.0 - post_residual as f64) * 25.0;
    } else if post_residual <= 25 {
        // Small gap: likely dead unless next item is tiny
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        if !next_fits {
            score += (26.0 - post_residual as f64) * 6.0;
        } else {
            // Reward keeping room for the lookahead item
            score -= 8.0;
        }
    } else if post_residual >= 40 {
        // Large residual stays flexible; mild reward
        score -= 5.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 120.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post-residual too small for next item: extra dead-space risk
        score += (post_residual as f64).min(20.0) * 1.5;
    }

    // Open-bins pressure: with many open bins, discourage spreading into
    // yet another bin; consolidation becomes more valuable.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 2.0 * progress);
    score += pressure * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately unattractive so it is chosen
    // only when all open bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.2;
    }

    // Mean-residual coupling: penalize bins far below mean residual
    // (they are the most fragmented).
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for near-exact fit (minimize dead space non-linearly)
    let fit_gap = post_residual as f64;
    score -= 30.0 * (1.0 - fit_gap / cap).exp() * (1.0 - fit_gap / 10.0).max(0.0);

    // 2-step lookahead: reward if next item matches post_residual exactly
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let diff = (post_residual as f64 - look).abs();
        if post_residual as f64 >= look {
            // next item fits perfectly -> chain placement
            score -= 25.0 * (1.0 - diff / 20.0).max(0.0);
            if diff == 0.0 { score -= 40.0; }
        } else {
            // next item will NOT fit here; penalize small unusable residuals
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 5.0; // tiny dead space is fine
            } else if dead < look {
                // dead space that even the next item can't use
                score += 0.15 * dead;
            }
        }
    } else {
        // last item: pure tightness matters most
        score -= 20.0 * (1.0 - fit_gap / cap);
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty for opening a new bin
        score = cap + 10.0;
        // if many bins fit the item, opening new bin is wasteful
        if fitting_bins_count > 1 {
            score += 50.0;
        }
        // if only one bin fits, opening a new bin is a reasonable alternative
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // early in stream, allow more bins (better structure later)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // if mean residual is high, open bins are fragmented; new bin ok
        score -= 0.2 * mean_residual;
        // large items prefer fresh bins
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    } else {
        // prefer bins with residual below mean (pack tighter bins first)
        score -= 0.3 * (mean_residual - bin_residual as f64);
        // slight preference when few bins are open (consolidation)
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: favor small post_residual relative to capacity
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that next item can't use
    if next_item_size > 0 {
        if post_residual > 0 && (next_item_size as u32) > post_residual {
            score += 0.35 * post_residual as f64;
        } else if next_item_size as u32 == post_residual {
            score -= 120.0; // chains perfectly with lookahead
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when existing fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, reduced late in stream or when few bins open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 - 25.0 * progress;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 20.0; // big lookahead item may want fresh capacity
        }
    }

    // Fragmentation-aware: penalize leaving residual far from mean when mean is small
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Prefer filling bins with larger residuals when many bins are open
    if open_bins_count > 3 {
        score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 40.0
                 - norm_pr * progress * 25.0;
    score += coupling;

    // Penalize tight fits late (dead space), reward tight fits early
    let tight = 1.0 - norm_pr;
    score += tight * tight * progress * 20.0;

    // Last-chance bin bonus (subtract to favor using it)
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits post_residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let snug = 1.0 - ((pr - ni) / cap).abs();
            score -= 12.0 * snug * snug;
        } else {
            score += 6.0 * ((ni - pr) / cap);
        }
    } else {
        // last item: strongly prefer minimal post residual
        score += 5.0 * norm_pr;
    }

    // Mild pressure from many open bins: prefer filling existing bins
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - norm_pr);

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += ((pr - mean_residual) / cap).abs() * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries: post_residual in {0, <=10, <=20, <=50, >50}
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 45.0; // near-perfect fill, unusable sliver
    } else if post_residual <= 20 {
        score -= 20.0;
    } else {
        // Larger leftovers penalized superlinearly; harmonic ladder on integer division
        let class = post_residual / 10; // integer division class
        score += (class as f64) * 8.0;
        score += (pr / cap) * 30.0;
    }

    // Modulo-arithmetic coupling: does post_residual align with common item size classes?
    // Items 1..100; check if next item fits exactly into the leftover (harmonic match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0; // exact harmonic pairing with lookahead
        } else if next_item_size < post_residual {
            // leftover still usable by next item: reward proportional to tightness
            let tight = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 15.0 + 25.0 * tight;
        } else {
            // next item cannot fit here: penalize if we leave mid-range dead space
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer fuller bins when many bins are open (reduce fragmentation).
    score -= (1.0 - pr / cap) * (open_bins_count.min(50) as f64) * 1.5;

    // New-bin candidate: only attractive when existing bins would waste a lot.
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost, discounted early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 40.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0; // next item huge, fresh bin useful
        }
        if mean_residual > 40.0 {
            score -= 15.0; // existing bins fragmented; new bin competitive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Moderate residual is fine; large residual (loose fit) gets a mild penalty.
    if post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.3;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Pressure from number of open bins: encourage filling existing bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Lookahead: if next item fits the post residual exactly, reward strongly.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Penalize if post residual cannot hold the next item (dead space likely).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Slight preference to place into bins with below-mean residual (tighten loose bins).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits in the residual after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 10.0 * (next_item_size as f64 / post_residual as f64);
    }
    // Penalize creating residual that is too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 0.35 * gap;
    }

    // Reward tight fills (small post_residual), especially vs mean residual.
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    if (post_residual as f64) < mean_residual {
        score -= 0.4 * (mean_residual - post_residual as f64);
    } else {
        score += 0.25 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no bin fits well or stream is early.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            // Opening a new bin is wasteful when decent fits exist.
            score += 30.0
                + 0.5 * open_bins_count as f64
                - 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual), amplified late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity as f64 - post_residual as f64) * (0.3 + 0.5 * progress);

    // Penalize dead space: small residuals that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual exactly or well, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // Prefer filling bins that are already below-average residual (consolidation).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.4;
    } else {
        score += (residual_f - mean_residual) * 0.2;
    }

    // New-bin candidate: penalize opening new bins unless current fit is poor
    // and many open bins already exist relative to stream progress.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > (bin_capacity as f64 * 0.5);
        let crowd = open_bins_count as f64 / (1.0 + progress * 10.0);
        if poor_fit && crowd > 3.0 {
            score -= 20.0; // opening a fresh bin may be better than cramming
        } else {
            score += 30.0 + 20.0 * (1.0 - progress);
        }
    }

    // Mild penalty for very large items into nearly-full bins (fragmentation risk).
    if item_size > 60 && post_residual > 0 && post_residual < item_size / 2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: post-residual penalty grows with stream progress
    score += 18.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic dead-space term: tiny residuals are wasteful, weighted by progress
    score += 10.0 * norm_pr.powi(3) * (1.0 + progress);

    // Interaction: residual squared with mean residual deviation (smoothly favors
    // bins whose leftover differs from the fleet average)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * norm_pr * dev;

    // Lookahead coupling: reward residual that smoothly matches the next item
    let fit_gap = (norm_pr - norm_next).abs();
    score -= 14.0 * (-6.0 * fit_gap * fit_gap).exp() * (1.0 - 0.5 * progress);
    // Penalize next item not fitting anywhere if this bin is the only option
    if fitting_bins_count == 1 && next_item_size > post_residual {
        score -= 9.0 * (1.0 - progress);
    }

    // Smoothly discourage proliferation of open bins early on
    score += 2.5 * (open_bins_count as f64).ln() * (1.0 - progress) * norm_item;

    // Large fill fraction bonus, amplified over the stream
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.4 + progress);

    // Mild penalty for very small items into large residual when many bins open
    score += 4.0 * norm_item * (1.0 - norm_item) * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: partition capacity space into
    // residue classes modulo 10 and coarse integer-division bands.
    let pr = post_residual;
    let class_mod = pr % 10;                       // fine harmonic class
    let class_band = pr / 10;                      // coarse harmonic band (0..=10)

    // Reward residuals that are "friendly" sizes: small residuals waste less.
    // Dead space below 10 is unusable for the smallest items (size >= 1 but
    // typical streams cluster >= 10), so penalize tiny-but-nonzero leftovers.
    if pr > 0 && pr < 10 {
        score += 25.0; // awkward sliver, hard to fill
    }

    // Reward exact-fill: pr == 0 is a perfect harmonic (class 0).
    if pr == 0 {
        score -= 60.0;
    }

    // Harmonic coupling with next item: if the next item fits exactly in the
    // post residual, this placement is ideal (complementary pair).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size < pr {
            // Next item fits: reward proportionally to how well it fills.
            let fill = next_item_size as f64 / pr as f64;
            score -= 30.0 * fill;
            // If after next item the residual lands on a "good" class
            // (multiple of 10), give an extra harmonic bonus.
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot use this residual: mild penalty scaled by waste.
            score += 5.0 + (next_item_size - pr) as f64 * 0.15;
        }
    } else {
        // Last item: prefer tightest fit (score already ~ post_residual).
        score -= 10.0;
    }

    // Modulo-based preference: residuals that are multiples of 10 are
    // "harmonic nodes" — many common item sizes (10,20,...,80) tile them.
    if class_mod == 0 && pr > 0 {
        score -= 12.0;
    } else if class_mod >= 5 {
        // Odd half-class: moderately usable.
        score += 3.0;
    }

    // Band-based shaping: large bands (lots of leftover space) mean we are
    // under-filling this bin; encourage filling fuller bins first.
    score += class_band as f64 * 6.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has large residual; the band
    // term already penalizes it. Add an explicit opening penalty that decays
    // as the stream progresses (late in the stream, prefer consolidating).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 40.0 * progress;
        // Opening a new bin is attractive if no open bin fits at all.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight pressure to keep the number of open bins low.
    score += open_bins_count as f64 * 0.5;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "tight" — finishing it is good.
    let diff = mean_residual - pr as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (< 10, minimum item size) more harshly.
    if post_residual < 10 {
        score += 60.0; // dead space is pure waste
    } else if post_residual <= 20 {
        score += (20 - post_residual) as f64 * 2.0; // small gaps are hard to fill
    }

    // Reward tight fits (small post_residual relative to item size).
    score -= (item_size as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 12.0; // perfect two-item packing
        }
    }

    // Open bins pressure: when many bins are open, discourage opening more
    // by penalizing the empty new-bin candidate.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.5 * open_bins_count as f64;
        // But allow new bin if existing residuals are all small/unusable.
        if mean_residual < 12.0 {
            score -= 20.0;
        }
    }

    // Mild preference to fill bins with larger residuals early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 - post_residual as f64) * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
            // extra reward for near-exact chaining
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // penalize leaving dead space the next item cannot use
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 10.0 * (1.0 - dead / (next_item_size as f64));
            }
        }
    }

    // Relative to mean residual: prefer bins below-average residual (tighter bins)
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit decently
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if item is large and few bins fit
        score += 55.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large items coming, keep fresh capacity
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill_ratio = item_size as f64 / residual;
        score -= 12.0 * fill_ratio * fill_ratio;
    }

    // Penalize leaving awkward dead space (small but nonzero post_residual).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 8.0 * (10.0 - pr) / 10.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - nxt / bin_capacity as f64);
        } else {
            // Penalize blocking the next item unless post-residual is essentially unusable anyway.
            score += 3.0 * (pr / bin_capacity as f64);
        }
    }

    // Global state: many open bins with high mean residual -> discourage spreading into fresh space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > item_size as f64 * 1.5 && bin_residual >= bin_capacity {
        score += 10.0 * (open_bins_count as f64 / (1.0 + open_bins_count as f64)) * (0.5 + progress);
    }

    // Late in the stream, prefer consolidating into existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    } else {
        score -= 2.0 * progress;
    }

    // Mild preference for bins whose residual deviates favorably from the mean.
    score -= 0.5 * (mean_residual - residual).max(0.0) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (penalize large post residual quadratically).
    // Late: prefer preserving usable space (smoothly flip preference).
    let w_early = (1.0 - progress).powi(2);
    let w_late = progress * progress;
    score += w_early * (post / cap).powi(2) * 4.0;
    score -= w_late * (post / cap) * 0.5;

    // Penalize dead space that cannot fit the lookahead item (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = ((nxt - post) / cap).max(0.0);
        score += unusable.powi(2) * 3.0 * (1.0 - progress * 0.5);
        // Reward leaving space exactly usable by next item (smooth bump).
        let fit_gap = (post - nxt).abs() / cap;
        score -= (1.0 - fit_gap.min(1.0)).powi(3) * 1.5;
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 2.0 + (item_size as f64 / cap) * 2.0;
    }

    // Mild penalty when bin is far from the mean residual state (smooth dispersion).
    let dev = (post - mean_residual) / cap;
    score += dev.abs().powi(2) * 0.8;

    // New-bin candidate: keep it slightly attractive only when existing bins are tight.
    if bin_residual == bin_capacity {
        let tightness = ((cap - mean_residual) / cap).clamp(0.0, 1.0);
        score = 0.6 + 0.8 * (1.0 - tightness) + progress * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small, "usable" leftover classes.
    // Class 0 (perfect fill): strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        // leftovers in [10,30] are still fillable by typical small items
        score -= 12.0 - (post_residual as f64) * 0.2;
    } else if post_residual < 10 {
        // dead space: penalize
        score += 25.0 - (post_residual as f64) * 2.0;
    }

    // Modulo-10 harmonic class of post_residual: multiples of 10 pair well
    // with items drawn on a 10-grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Integer-division threshold: post_residual / item_size ratio
    let fill_fraction = item_size as f64 / bin_capacity as f64;
    if fill_fraction > 0.5 {
        // big item placed: reward tight packing
        score -= fill_fraction * 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // next item fits but leaves waste; scale by how snug
            let snug = next_item_size as f64 / post_residual as f64;
            score -= snug * 10.0;
        } else {
            // next item won't fit here: penalize wasting this bin's leftover
            score += 6.0;
            // if post_residual is too small for ANY item (min size 1..10 typical),
            // treat as near-dead
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer the tightest fit among many candidates,
        // already captured by post_residual term
        score += 0.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize opening a new bin progressively.
    if bin_residual == bin_capacity {
        // new bin: raw residual = 100, so baseline score is high already.
        // Penalize more when many bins are open and mean residual is healthy.
        score += 20.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.3;
        // but early in the stream, allow new bins cheaply
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
    }

    // Mean-residual coupling: if this bin's residual is far below mean,
    // it's a good "garbage absorber" — reward using it.
    if (bin_residual as f64) < mean_residual - 10.0 {
        score -= 5.0;
    }

    // Harmonic threshold on post_residual via integer division buckets
    let bucket = post_residual / 25; // 0..=4
    score -= match bucket {
        0 => 6.0,           // 0..24: tight fill
        1 => 3.0,           // 25..49
        2 => 0.0,           // 50..74
        _ => -0.0,          // large leftover: neutral, baseline dominates
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open bins pressure: penalize adding to many already-open bins mildly,
    // but reward using the last fitting bin before opening a new one.
    score += open_bins_count as f64 * 0.4;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make an empty bin less attractive unless
    // the current item would leave a large dead gap in an existing bin.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If next item is large and current item leaves big residual, opening
        // a new bin may be preferable; soften the penalty.
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            score -= 10.0;
        }
    }

    // Lookahead: reward bins whose residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Mild time coupling: later in stream, prefer tighter fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: if the next item exactly fills the post residual,
    // this bin is a perfect chain placement.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 500.0;
        } else if gap <= 5 {
            score -= 120.0;
        } else if gap <= 10 {
            score -= 40.0;
        } else {
            // Next item leaves a large dead remainder -> penalize mildly.
            score += gap as f64 * 0.3;
        }
        // If next item cannot fit in post residual at all, dead space likely.
        if next_item_size as u32 > post_residual {
            score += 15.0;
        }
    }

    // Relative-to-mean coupling: bins with residual above mean are more
    // flexible; slightly prefer using them for loose fits.
    if (bin_residual as f64) > mean_residual + 5.0 {
        score -= 10.0;
    } else if (bin_residual as f64) < mean_residual - 5.0 {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make opening a new bin only attractive when the
    // current item fits poorly everywhere (handled above); otherwise bias
    // against opening new bins to keep bin count low.
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * open_bins_count as f64;
        // But if the item is large relative to typical residuals, opening
        // a fresh bin is reasonable.
        if item_size as f64 > mean_residual {
            score -= 80.0;
        }
    }

    // Mild stream-progression pressure: later in the stream, avoid
    // spreading across many bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual already favored by base term).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // lookahead item can chain into this bin
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bin late in stream when many bins open and mean residual low.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0 * progress;
        }
    }

    // Prefer filling bins that deviate below mean residual (consolidate emptier bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight preference for bins with larger residual when many bins are open.
    score -= 0.05 * (open_bins_count as f64).ln() * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let tightness = 1.0 - (item_size as f64 / cap);
    let fit_frac = pr / cap;

    let mut score = pr;

    // Reward tight fits: quadratic bonus shrinking post_residual
    score -= (1.0 - fit_frac).powi(2) * cap * (0.5 + 0.5 * progress);

    // Penalize dead space that is too small to be useful later (smooth non-linear)
    let dead_zone = (1.0 - fit_frac / (1.0 - tightness + 1e-9)).abs();
    score += 8.0 * (-fit_frac * 4.0).exp() * (0.5 + 0.5 * dead_zone);

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New bin candidate: penalize early, allow late or when item is large
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 15.0 * (1.0 - progress) - 5.0 * (item_size as f64 / cap);
    }

    // Lookahead: reward if post_residual can still host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (pr - nxt + 1.0).ln().max(0.0) * 0.1;
        } else {
            score += 6.0 * ((nxt - pr) / cap);
        }
    }

    // Mild pressure toward consolidating residuals near mean
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "usable" residue classes (multiples of common small item sizes).
    let pr = post_residual;
    if pr > 0 {
        // Modulo classes: residuals divisible by 10 are highly reusable.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Integer-division thresholds: tiny dead space is nearly useless.
        let dead = pr < 10;
        if dead {
            score += 12.0;
        }
        // Half-capacity band is prime real estate.
        let half = bin_capacity / 2;
        if pr >= half / 2 && pr <= half {
            score -= 4.0;
        }
    } else {
        // Perfect closure: bin exactly filled.
        score -= 10.0;
    }

    // Coupling with lookahead item: if next item fits post_residual exactly
    // or cleanly (modulo class match), strongly reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 5.0;
        if pr % next_item_size == 0 {
            score -= 4.0;
        }
        if pr - next_item_size < 10 && pr != next_item_size {
            // next item would leave dead space
            score += 3.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item can't use this bin's residue; residue class mismatch penalty
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing bins are crowded and mean residual is small.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64;
        // base cost of a fresh bin, discounted when open bins are tight
        let base = 55.0 - 0.5 * crowd - mean_residual * 0.6;
        score = base + item_size as f64 * 0.3 + progress * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // pairing potential in fresh bin
            score -= (cap - item_size as f64 - next_item_size as f64).max(0.0) * 0.2;
        }
    }

    // Fractional capacity coupling: reward filling bins past 70% of capacity.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac >= 0.7 {
        score -= (fill_frac - 0.7) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable gaps (dead space): residuals that are
    // too small to hold even the smallest plausible item (size 1..10 range guard)
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10.min(item_size) {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        // moderately tight fit: mild reward
        score -= 8.0;
    }

    // Dead space relative to capacity: penalize leaving gaps the next item cannot use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + (next_item_size - post_residual) as f64 * 0.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0; // reward leaving room for the lookahead item
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; when few, allow it
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more when open bins exist and fit is possible elsewhere
        score += 40.0 + pressure * 2.0;
    } else {
        score -= pressure * 0.3;
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter packing)
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect fit for the next item is extremely desirable.
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0).powi(4);
        // Penalize post-residuals that are too small to hold the next item
        // (dead space that can never serve the lookahead).
        if post_residual < next_item_size {
            score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest fit naturally via post_residual.
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tight" bins;
    // filling them further is good (consolidate waste), opening slack in fat bins is worse.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (res - mean_residual) / mean_residual;
        score += 8.0 * rel; // below-mean residual => negative bonus
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual would be a perfect next-item fit elsewhere).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave tiny unusable
    // slivers or the fit is terrible. Penalize opening new bins while open bins remain.
    if bin_residual == bin_capacity {
        let waste = bin_residual - item_size;
        // A fresh bin is good if it leaves a large, reusable residual
        // and the item is big; bad if it fragments the stream with many open bins.
        score += 30.0 * (open_bins_count as f64).sqrt();
        score -= 0.15 * waste as f64;
        if next_item_size > 0 && waste >= next_item_size {
            score -= 10.0; // fresh bin can also serve the next item
        }
    }

    // Slight stream-progression modulation: as the stream matures, tighten up
    // and avoid spreading items across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
