pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: quadratic coupling of post-residual with stream progress.
    // Early on, prefer filling bins tightly (low post_residual favored);
    // late in stream, slightly tolerate larger residuals to keep bins flexible.
    let mut score = r * (1.0 + 0.5 * rn * rn) * (1.0 - 0.3 * progress);

    // Smooth non-linear interaction: dead-space penalty grows superlinearly
    // when post_residual becomes too small to be useful.
    let dead_zone = (rn - 0.2_f64).max(0.0);
    score += 20.0 * dead_zone * dead_zone * (1.0 + progress);

    // Reward tight fits: subtract a smooth function of item fraction.
    let fill = item_size as f64 / cap;
    score -= 15.0 * fill * fill;

    // Last-chance bin: strong smooth reward to use it rather than open new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Lookahead coupling: if next item fits in post-residual, reward this placement.
    if next_item_size > 0 {
        let next_fits = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        let gap = (next_item_size as f64 - r).abs() / cap;
        score -= 8.0 * next_fits * (1.0 - gap);
        score += 3.0 * (1.0 - next_fits) * gap;
    }

    // Mild preference toward bins with residuals near the mean (smooth balancing).
    let dev = (r - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // Slight bias against opening new bins when many are already open.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * rn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod 10 buckets
    let pr = post_residual;
    let harm = pr % 10;
    // Penalize residuals that are "awkward" harmonic classes (1..9 are hard to fill)
    if pr > 0 {
        match harm {
            0 => score -= 30.0,                    // perfect decade alignment
            1 | 9 => score += 18.0,                // nearly useless sliver
            2 | 8 => score += 12.0,
            3 | 7 => score += 7.0,
            4 | 6 => score += 3.0,
            5 => score -= 5.0,                     // half-slot, reusable by 15/25/...
            _ => {}
        }
    } else {
        score -= 60.0; // perfect closure
    }

    // Exact fit reward
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead: can next_item_size land exactly in the post residual?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 55.0; // chains perfectly with next item
            } else {
                // harmonic compatibility of the remaining gap
                let g = gap % 10;
                if g == 0 { score -= 15.0; }
                else if g == 5 { score -= 8.0; }
                else { score += (g as f64) * 1.5; }
            }
        } else {
            // next item cannot fit here; mild penalty scaled by shortfall
            score += (next_item_size - pr).min(20) as f64 * 0.8;
        }
    }

    // Integer-division thresholds: prefer leaving residuals in coarse bands
    let band = pr / 10; // 0..=10
    score += (band as f64 - 5.0).abs() * 2.0; // sweet spot around 40-50 residual

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if current bin would leave tiny waste
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 45.0;
        // attractive when the item is huge relative to capacity (harmonic class of item)
        let item_class = item_size / 10;
        if item_class >= 7 { score -= 30.0; }
        if fitting_bins_count == 0 { score -= 100.0; } // no alternative
    }

    // Slight preference to consolidate when many bins are open
    score -= (open_bins_count as f64) * 0.3;

    // Stream progression: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (100.0 - pr.min(100) as f64) * progress * 0.2;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item (1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Strongly prefer exact or near-exact fills
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty scaled by how tight the fit is relative to bin capacity
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Open-bin pressure: discourage scattering across many bins when pressure is high
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Favor bins whose residual is close to item size (minimal waste)
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * waste;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post residual blocks next item: penalize dead space harder
        score += 12.0;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 10.0 + 0.3 * mean_residual.abs();
    }

    // Prefer bins with residual below mean (consolidating fuller bins)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual exactly matches next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Next item fits into the residual left behind: strong lookahead reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64 / bin_capacity as f64) * 20.0;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize dead space proportional to its size.
        score += 8.0 + (next_item_size as f64 / bin_capacity as f64) * 15.0;
    }

    // Penalize very small unusable residuals (dead space), worse when large.
    if post_residual < 10 {
        score += 10.0 + (10 - post_residual) as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins fit well.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if next item is huge and current residual after placement is tiny,
        // opening fresh space is less bad.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 15.0;
        }
        // Early in stream, allow more bins to stay open for flexibility.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer bins with residuals near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slight preference for tighter bins overall.
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0; // moderately awkward gap
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * next_fit;
        } else {
            // Next item won't fit here; slight penalty for wasting large residual.
            score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (spread items);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and progress.
        let mut new_bin_cost = 55.0;
        new_bin_cost -= 30.0 * progress;
        new_bin_cost += 2.0 * open_bins_count as f64;
        // If mean residual across open bins is small, opening a new bin is reasonable.
        new_bin_cost -= 0.3 * mean_residual;
        // If no existing bin fits well (post_residual large relative to item), favor new bin.
        new_bin_cost += 0.4 * post_residual as f64 * (1.0 - fit_ratio);
        score = score.max(new_bin_cost);
    } else {
        // Existing bin: mild penalty if its residual is far above mean (keep balanced bins).
        score += 0.1 * (bin_residual as f64 - mean_residual).abs();
        // Consolidation pressure late in the stream.
        score -= 15.0 * progress;
    }

    // Discourage leaving residuals in the awkward 31..49 zone that few items can use.
    if post_residual >= 31 && post_residual <= 49 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Quadratic/cubic polynomial coupling of post_residual with stream progress
    let p2 = norm_pr * norm_pr;
    let p3 = p2 * norm_pr;
    score += 12.0 * p2 * (0.5 + progress);
    score -= 9.0 * p3 * (1.0 - progress);
    // Favor tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (2.0 + 6.0 * progress);
    // Penalize dead space relative to mean residual
    let dead = (pr as f64 - mean_residual) / cap;
    score += 4.0 * dead * dead * (1.0 + 3.0 * progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 3.5 + 4.0 * progress;
    }
    // Lookahead: reward if next item can fit into post_residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let snug = 1.0 - ((pr - ni) / cap);
            score -= 3.0 * snug * snug;
        } else {
            score += 2.0 * (1.0 - pr / ni);
        }
    }
    // Mild penalty for bin proliferation early; encourage reuse later
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);
    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 6.0 - 5.0 * progress;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes.
    let pr = post_residual;
    let class = pr % 10; // harmonic class mod 10

    // Reward near-perfect fits (small post_residual), with non-linear decay.
    if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 20.0;
    } else if pr <= 20 {
        score -= 5.0;
    }

    // Penalize dead space in "awkward" harmonic classes (hard to fill: 1..9 mod 10).
    if pr > 0 && pr < 10 {
        score += 30.0; // tiny unusable sliver
    }
    // Class-based coupling: residuals that pair well with common item sizes get bonuses.
    let next = next_item_size;
    if next > 0 {
        if next <= pr {
            // lookahead fits exactly in this bin after placement
            let after = pr - next;
            score -= 15.0 + (after as f64).min(10.0);
        } else {
            // lookahead cannot use this residual: penalize proportionally
            score += 0.2 * ((next - pr) as f64);
        }
        // modulo harmony: if (pr - next) lands in a good class (0 mod 10 or small), reward
        if next <= pr {
            let gap = pr - next;
            if gap % 10 == 0 { score -= 8.0; }
            if gap < 5 { score -= 10.0; }
        }
    } else {
        // Last item: strongly prefer exact fill
        if pr == 0 { score -= 100.0; }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer empty bin when open bins have bad residuals
    if bin_residual == bin_capacity {
        // neutral base; subtract if mean residual across open bins is fragmented
        score -= 5.0;
        if mean_residual > 0.0 && mean_residual < 15.0 && open_bins_count > 0 {
            score -= 10.0; // open bins are nearly full; new bin is good
        }
        // late in stream, prefer consolidation
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 8.0;
        }
    }

    // Mild penalty for spreading across many bins when residual is generous
    if open_bins_count > 4 && pr > 50 {
        score += 3.0;
    }

    // Small tie-breaker: prefer bins whose residual is an integer-division multiple of item size
    if item_size > 0 && bin_residual % item_size.max(1) == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
