    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward near-zero post residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post residual, this is a chained perfect fit — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            // Next item fits but leaves a further gap; penalize by the
            // remaining dead space after the hypothetical second placement.
            let second_gap = post_residual - next_item_size;
            score += second_gap as f64 * 1.5;
            // Small reward for keeping the chain alive.
            score -= 40.0;
        } else {
            // Next item cannot use the post residual: dead space likely.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Compare post_residual against mean residual: penalize bins that end up
    // far below the mean (creating outlier dead space), reward balancing.
    score += (post_residual as f64 - mean_residual).abs() * 0.6;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.7 {
            // Large item: opening a fresh bin is fine.
            score -= 50.0;
        } else {
            // Small/medium item: discourage wasting a fresh bin.
            score += 250.0 * (1.0 - fill_frac);
        }
    }

    // Mild late-stream pressure to consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0 * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly prefer placements leaving small residuals
    let tight_bonus = ((post_residual as f64) / bin_capacity as f64).powi(3) * 40.0;
    score += tight_bonus;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving residuals that are too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space
    }

    // Lookahead coupling: reward residuals that can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // residual too small for next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this bin
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        let mut new_bin_cost = 45.0;

        // Early in the stream, opening bins is cheaper (builds a pool for future fits)
        new_bin_cost -= (1.0 - progress) * 15.0;

        // If many bins are open with large mean residual, prefer reusing them
        new_bin_cost += (mean_residual / bin_capacity as f64) * 20.0;
        new_bin_cost += open_bins_count as f64 * 2.0;

        // If the item is large and would leave a big residual anyway, new bin is fine
        new_bin_cost -= (item_size as f64 / bin_capacity as f64) * 10.0;

        // If no open bin fits tightly (this is the only candidate), new bin less bad
        if fitting_bins_count <= 1 {
            new_bin_cost -= 20.0;
        }

        score += new_bin_cost;
    } else {
        // Reusing an existing bin: small reward scaled by how full the bin already is
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 10.0;

        // Slight preference to consolidate into fewer bins when many are open
        score -= open_bins_count.min(20) as f64 * 0.5;
    }

    // Mild time-horizon modulation: late in stream, be greedier about tight fits
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear waste penalty: dead space matters more as stream progresses
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Tight fit reward (small post residual)
    score -= 8.0 * (-pr / 8.0).exp();

    // Lookahead coupling: penalize if next item could have used this residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (pr - nxt).max(0.0);
        score += 6.0 * (waste / cap) * (1.0 + progress);
        // Reward leaving residual that exactly fits next item
        if nxt <= pr {
            score -= 4.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild pressure against proliferating open bins with large residuals
    score += (open_bins_count as f64).ln() * norm_pr * 2.0;

    // Mean residual deviation coupling
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate shaping: empty bin gets a smooth baseline that
    // decreases with progress (late stream favors opening bins for tight fits)
    if bin_residual == bin_capacity {
        score = cap * (0.35 - 0.2 * progress) + 10.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover divisible by common item
    // sizes (10,20,25,50) is more reusable, reward it.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 5.0; }
    } else {
        // Perfect closure of the bin is ideal.
        score -= 30.0;
    }

    // Dead-space penalty: leftovers in the "awkward" harmonic band (1..10)
    // are nearly unusable for items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0 * (10 - post_residual) as f64;
    }

    // Capacity-fraction classes: bins whose residual sits on clean fractions
    // of capacity are preferred targets.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == quarter { score -= 5.0; }
    if post_residual == half { score -= 6.0; }
    if post_residual == 3 * quarter { score -= 4.0; }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if it cannot fit, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 4.0;
        }
        // Harmonic pairing: next item leaves a multiple-of-10 leftover too.
        if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are
    // nearly full or the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = (mean_residual / bin_capacity as f64) < 0.25;
        if tight && item_size > 50 { score += 8.0; } else { score += 25.0 - 10.0 * progress; }
    }

    // Mild density bonus: filling more of the bin now is better.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    // Prefer bins whose residual is below the mean (compact bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize unusable small gaps.
    // A gap that cannot fit even the smallest plausible item (or the lookahead item)
    // is wasted space.
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual < min_useful {
        score += 60.0; // dead space penalty
    } else if post_residual <= 15 {
        score += 25.0; // near-dead space
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual == bin_residual - item_size && post_residual < 5 {
        score -= 30.0;
    }

    // Reward leaving room for the lookahead item (tight lookahead fit).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 15 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // and discourage opening new bins; when few bins are open, allow spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean residual is large.
        score += 40.0 + pressure * 12.0 + mean_residual * 0.4;
    } else {
        // Existing bin: slight reward scaled by tightness relative to mean residual.
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to item usage (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64 - post_residual as f64).abs() * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits with small slack left after that placement.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 25.0 - 2.0 * slack;
        } else {
            // penalize leaving awkward mid-size gaps relative to mean residual
            score += 0.3 * (slack - mean_residual).abs();
        }
    }
    // Next item too large for post_residual: dead space unless tiny.
    if next_item_size > post_residual {
        if post_residual <= 5 {
            score -= 15.0; // near-perfect closure, bin effectively closed
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Discourage opening a new bin when good open bins exist and item is small.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if item_size <= 50 && fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Mild preference for tighter bins (low residual) relative to mean.
    score += 0.2 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Late in stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: post residuals that cannot fit typical small items (>=10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Lookahead: if the next item can fit into the post residual, reward this bin;
    // if next item is large and post_residual is tiny, slight penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (next_item_size as f64 / 100.0);
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid wasting capacity elsewhere).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Global state: many open bins with high mean residual -> prefer reusing
    // existing bins to consolidate; few open bins -> new bins are cheaper.
    let mean_r = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    let consolidation_pressure = (open_bins_count as f64).ln().max(0.0) * (mean_r / bin_capacity as f64);
    score += 8.0 * consolidation_pressure;

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Penalize opening a new bin, but the penalty shrinks late in the stream
    // and when existing bins would leave bad dead space.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 45.0;
        if progress > 0.5 {
            new_bin_penalty -= 10.0 * progress;
        }
        // If the item is huge relative to capacity and fits nowhere well,
        // opening a fresh bin is more acceptable.
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 12.0;
        }
        // If next item is very large, a fresh bin gives flexibility.
        if next_item_size > 60 {
            new_bin_penalty -= 8.0;
        }
        score += new_bin_penalty;
    } else {
        // Mild preference for reusing already-open bins when they fit well.
        score -= 5.0;
    }

    // Small time-horizon modulation: early in the stream, be slightly more
    // willing to spread (penalize tight fits less); late, pack tightly.
    score += 10.0 * (1.0 - progress) * tightness - 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) growth
    let mut score = pr + (pr / cap).powi(2) * 20.0 + (pr / cap).powi(3) * 30.0;

    // Smooth stream-progress coupling: later in stream, penalize waste more strongly
    score += progress * (pr / cap) * 15.0;

    // Reward tight fits (small post_residual relative to item) via smooth interaction
    let tightness = 1.0 - (pr / cap);
    score -= tightness * fit_frac * 25.0 * (0.5 + progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits into the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + (next_item_size as f64 / cap) * 10.0;
    } else if next_item_size > 0 {
        // next item won't fit: mild penalty scaled by dead-space potential
        score += (pr / cap) * 8.0;
    }

    // Deviation from mean residual: prefer bins whose residual differs from average (diversification)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 10.0;

    // Slight preference for consolidating into fewer bins
    score += (open_bins_count as f64).ln() * 0.5;

    // New-bin candidate handling: empty bin gets moderate base cost so it only wins on poor fits
    if bin_residual == bin_capacity {
        score += 35.0 - 15.0 * progress + fit_frac * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are "friendly"
    // to small items (mod classes), penalize awkward dead-space classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit bonus (post_residual == 0 or exactly divisible classes)
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // modulo arithmetic on post_residual: residuals divisible by 5 or 10
        // are more likely to be filled by common item sizes.
        if post_residual % 10 == 0 {
            score -= 8.0;
        } else if post_residual % 5 == 0 {
            score -= 4.0;
        } else {
            score += 3.0;
        }

        // Integer division thresholds: very small residuals are dead space
        if post_residual <= 10 {
            score += 12.0; // nearly unusable
        } else if post_residual <= 20 {
            score += 5.0;
        }

        // Fraction of capacity remaining: encourage tight but usable fits
        let frac = pr / cap;
        if frac > 0.5 {
            score += 6.0; // wasteful placement in a big empty bin
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, strong bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here; slight penalty for blocking
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score -= (mean_residual - pr).clamp(-cap, cap) * 0.15;

    // New bin candidate: penalize opening a new bin unless current bins are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * (open_bins_count as f64).sqrt();
        // but if the item is large relative to mean residual, new bin is attractive
        if (item_size as f64) > mean_residual {
            score -= 12.0;
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range,
    // but small gaps < 20 are nearly unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 + (20 - post_residual) as f64 * 4.0;
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }
    // Small post-residual that could still fit a small item is mildly rewarded.
    if post_residual >= 20 && post_residual <= 40 {
        score -= 15.0;
    }

    // Open-bins pressure: discourage opening new bins when plenty are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 40.0 + open_bins_count as f64 * 3.0;
        // Allow new bin if this bin would be the only fitting option AND fit is bad.
        if fitting_bins_count <= 1 && post_residual < 15 {
            score -= 70.0;
        }
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 5.0 + open_bins_count as f64 * 0.5;
    }

    // Last-chance bin: strongly favor placing here to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement strongly (chains future fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 20.0 {
            score -= 25.0 - gap;
        }
    }

    // Mild progression term: early in stream, be more tolerant of spreading;
    // later, tighten packing to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates from mean toward fullness.
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item fills the bin.
    if post_residual == 0 {
