        let waste = post_residual as f64;
        score += 0.02 * waste * waste;
    }

    // 2-step lookahead: if the next item fits exactly in the post-residual,
    // reward heavily (chain of tight fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item can still be placed here: mild reward proportional to fit tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.5 * slack;
        } else {
            // Next item cannot use leftover space: penalize dead space creation,
            // worse when the leftover is small-but-unusable.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 60.0 - 5.0 * dead; // tiny unusable slivers are very bad
            } else {
                score += 10.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: neutral baseline, slightly penalized so we prefer
    // reusing open bins unless the fit is genuinely poor.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 5.0;
        // If no other bin fits well (many open bins but few fitting), allow new bin.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Contextual adjustment: bins with residual far below mean are "odd" bins;
    // using them for tight fits is good, otherwise deprioritize slightly.
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with a convex penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.35 * (waste / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Reward bins whose residual exactly matches the item (perfect fit).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * (next_item_size as f64);
        } else {
            // Dead space that the next item cannot use: penalize proportionally.
            let dead = post_residual as f64;
            score += 0.25 * dead.min(next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global state: when many bins are open with scattered residuals, prefer consolidating
    // into bins with small residuals (avoid fragmenting).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * frag * (1.0 + open_bins_count as f64 / 20.0);

    // Time horizon: early in the stream, tolerate opening new bins (exploration);
    // late in the stream, pack tightly and avoid new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and as open bins grow.
        score += 30.0 + 40.0 * progress + 1.5 * open_bins_count as f64;
        // But if no open bin fits well (large waste), opening a new bin is attractive.
        if waste > 0.45 * bin_capacity as f64 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 45.0;
        }
        // Late stream: discourage new bins unless item is large.
        if progress > 0.7 && item_size < 40 {
            score += 20.0;
        }
    } else {
        // Favor bins whose residual is "complementary" to the item: residual close to item.
        let fit_gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.1 * fit_gap;
        // Late stream: extra reward for using existing bins.
        score -= 10.0 * progress;
    }

    // Small structural bonus for keeping mean residual low (balanced bin set).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64 / cap;
    let next = next_item_size as f64 / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) coupling
    let mut score = norm_pr + 2.0 * norm_pr * norm_pr + 4.0 * norm_pr * norm_pr * norm_pr;

    // Smooth stream-progress interaction: tight packing matters more later
    score *= 1.0 + 1.5 * progress * norm_pr;

    // Reward bins that can also fit the lookahead item smoothly (sigmoid-like)
    if next > 0.0 {
        let fit_next = (pr - next).max(0.0) / cap;
        let bonus = fit_next / (1.0 + (-8.0 * fit_next).exp());
        score -= 1.2 * bonus * (1.0 - progress);
    }

    // Penalize dead space relative to mean residual (smooth coupling)
    score += 0.5 * (norm_pr - mean_residual / cap).abs();

    // Last-chance bin bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 + 3.0 * progress;
    }

    // New-bin candidate: mild penalty so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * progress + 2.0 * item;
    }

    // Slight preference for fuller bins (small post_residual relative to item)
    score -= 0.3 * item * (1.0 - norm_pr);

    // Smooth open-bins pressure: encourage consolidation when many bins open
    score += 0.02 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "harmonic"
    // with the capacity (i.e. post_residual is a divisor-like fraction of C).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    for k in [2.0f64, 3.0, 4.0, 5.0] {
        let band = cap / k;
        if (pr - band).abs() < 3.0 {
            score -= 12.0 / k; // landing exactly on a harmonic fraction is great
        }
    }

    // Penalize dead space: tiny unusable residuals.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 2.5;
    }

    // Lookahead: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainability bonus, stronger when the next item nearly fills the leftover
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 6.0 + 10.0 * tight;
        } else {
            // leftover too small for next item: penalize proportionally to waste
            score += (next_item_size as f64 - pr).min(20.0) * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // mean residual across open bins is small (bins nearly full).
    if bin_residual == bin_capacity {
        let pressure = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 30.0 * pressure; // costly when open bins still have room
        // but cheaper as the stream matures and bins accumulate
        score -= 10.0 * (open_bins_count as f64).min(10.0) / 10.0;
        // new bin has perfect post_residual for lookahead: small nudge
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    // Mild preference for tighter fits overall (small post_residual base already
    // does this; add non-linear sharpening).
    score += (pr * pr) / (cap * 10.0);

    // Slight stream-position modulation: early on, be more conservative about
    // leaving large residuals; late, accept fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any plausible future item (items in [1,100]) are heavily penalized.
    if post_residual > 0 {
        // Unusable gap: smaller than the smallest conceivable useful item (say 10)
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual <= 20 {
            // Small gaps are risky: superlinear penalty
            score += 0.6 * (20 - post_residual) as f64;
        } else if post_residual >= 80 {
            // Huge leftover is also wasteful (item barely filled the bin)
            score += 0.3 * (post_residual - 80) as f64;
        }
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Open-bin pressure: prefer consolidating into existing bins; opening
    // new bins should carry a cost unless the fit is genuinely good.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin, scaled by how many bins are already open
        score += 15.0 + 2.0 * open_bins_count as f64;
        // If the next item is large and this fresh bin could take it later,
        // slightly soften the penalty (preserve capacity for big items).
        if next_item_size as f64 >= 0.7 * bin_capacity as f64 {
            score -= 8.0;
        }
    } else {
        // Last-chance bonus: this is the only open bin that fits the item
        if fitting_bins_count == 1 {
            score -= 20.0;
        } else {
            // Mild preference for bins below the mean residual (keep balance)
            score -= 0.2 * (mean_residual - bin_residual as f64);
        }
    }

    // Lookahead: if the post-residual exactly accommodates the next item,
    // this is an excellent chaining placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 10 {
        score -= 6.0;
    }

    // Late in the stream, closing bins tightly matters more (no future to amortize)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-match bonus: next item almost fills the remaining space
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack);
    }

    // Penalize leaving space too small for the next item (dead space)
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.5;
    }

    // Reward bins tighter than the mean residual (good consolidation)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist, unless it enables
    // a perfect lookahead pairing
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0;
        }
    }

    // Late in the stream: prefer packing tight to close bins out
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward;
    // if post-residual is just barely below next item, penalize the near-miss.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 8.0;
        } else if (next_item_size as u32) > post_residual && (next_item_size as u32) <= bin_residual {
            score += 6.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere else (post_residual on empty bin is large).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening new bins is cheaper early (more future to amortize) —
        // scale penalty with progress.
        score += 10.0 + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: no open bin fits
        }
    }

    // Global state: many open bins with high mean residual -> prefer reusing
    // bins with residual close to mean (keeps a balanced portfolio).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for fuller bins (smaller residual) overall.
    score += 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = x * x * (1.0 - x) * (1.0 - x);
    let coupling = poly * (0.5 + progress) * cap;

    let mut score = pr;

    // Reward tight fits more strongly as the stream progresses.
    score -= 2.0 * coupling * (0.3 + 0.7 * progress);

    // Penalize bins that leave residual too small to be useful (dead space).
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Prefer bins below mean residual (consolidating space) with smooth term.
    score -= 0.3 * (mean_residual - pr) * (0.5 + progress);

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 0.5 * (nx / cap) * (1.0 - progress) * 10.0;
        } else {
            score += 0.2 * nx * progress;
        }
    }

    // Mild penalty for spreading across many open bins early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

