    let pr = post_residual;
    let class = pr / 10; // integer division: 10-wide harmonic classes
    score += class as f64 * 5.0;

    // Modulo arithmetic: residuals divisible by 10 are "usable" classes
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    // Odd tiny residues are dead space
    if pr < 10 && pr > 0 {
        score += 25.0;
    }

    // Fraction of capacity used
    let fill_frac = (bin_capacity - pr) as f64 / cap;
    score -= fill_frac * 20.0;

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size < pr {
            // harmonic class match: next item leaves a clean residue class
            let next_post = pr - next_item_size;
            if next_post % 10 == 0 {
                score -= 15.0;
            }
            if next_post < 10 {
                score += 10.0;
            }
        } else {
            // next item cannot fit here: slight penalty if this is last-chance bin
            if fitting_bins_count == 1 {
                score -= 30.0;
            }
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Last-chance bin bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin gets a baseline that open bins
    // with decent fits should beat, but poor fits should not.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, modulated by stream progression
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 30.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // fewer open bins relative to items -> cheaper to open
        score -= (open_bins_count as f64).min(10.0);
    }

    // Mean residual coupling: penalize bins far from the mean residual
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Threshold on item_size: large items prefer tightest bin
    if item_size > 50 {
        score += (bin_residual - item_size) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
