        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual - post_residual as f64).max(0.0);
        let big_item = item_size as f64 / bin_capacity as f64;
        // Penalize new bin by default, but discount the penalty when mean residual
        // is low (open bins nearly full) or the item is large.
        let mut new_bin_penalty = 22.0;
        new_bin_penalty -= 12.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
        new_bin_penalty -= 10.0 * big_item;
        // Late in the stream, prefer filling existing bins (fewer wasted partial bins).
        new_bin_penalty += 8.0 * progress;
        // If no open bin fits well (this is the only fitting bin and it's empty),
        // opening a new bin is natural.
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 18.0;
        }
        // Fragmentation bonus: if other bins are much emptier than this placement,
        // a new bin wastes less.
        new_bin_penalty -= 4.0 * (fragmentation / bin_capacity as f64).min(1.0);
        score += new_bin_penalty.max(-5.0);
    }

    // Mild preference for filling bins with larger residuals when many bins are open,
    // to consolidate open bins and allow closing them.
    if open_bins_count > 3 {
        let residual_ratio = bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * residual_ratio * (open_bins_count as f64).ln() / 10.0;
    }

    // Small nudge toward exact fills.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;
    // Non-linear polynomial coupling: post_residual penalized more as stream progresses
    let pr = post_residual as f64;
    score += 2.0 * pr * pr / bin_capacity as f64 * (0.5 + progress);
    // Reward tight fits smoothly
    score -= 30.0 * (1.0 - pr / bin_capacity as f64).powi(3) * (1.0 + progress);
    // Last-chance bonus with smooth progress interaction
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * progress);
    }
    // Lookahead coupling: prefer bins whose post-residual fits next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0 * (1.0 - progress);
    }
    // Penalize deviation from mean residual smoothly
    score += 0.5 * (pr - mean_residual).abs() * (0.3 + progress);
    // Mild new-bin penalty to prefer filling existing bins early
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).sqrt();
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity divided into 10 classes of 10.
    let class = post_residual / 10;
    // Dead-space penalty: residuals in awkward classes (1..4 of 10) are hard to fill.
    if post_residual > 0 && class < 4 {
        score += (4 - class) as f64 * 12.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with next item: does the residual still accommodate the lookahead?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Harmonic match: residual class equals next item's class (mod-10 alignment).
            if post_residual / 10 == next_item_size / 10 {
                score -= 10.0;
            }
        } else if next_item_size > bin_residual {
            // Next item won't fit anywhere in this bin anyway; residual is pure waste.
            score -= 3.0;
        } else {
            // Next item fits currently but not after this placement: penalize.
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if mean_residual >= item_size as f64 * 1.5 {
            score += 10.0; // existing bins have plenty of room; avoid fragmentation
        }
    }

    // Mild preference for tighter bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps that can't hold even the smallest item)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10.0 - post_residual as f64);
    }
    // Penalize gaps too small for the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 0.6 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits strongly
    score -= 1.5 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin bonus: avoid opening new bins when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        score += 15.0 + pressure;
    } else {
        score -= 0.1 * pressure;
    }

    // Prefer bins below mean residual (more filled bins)
    score += 0.2 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-item match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits exactly into post_residual region (small leftover slack).
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward proportionally to tightness of the follow-up fit.
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        // Extra bonus if slack is small enough to be "dead-space safe".
        if slack <= 10.0 {
            score -= 10.0;
        }
    }
    // Next item does NOT fit: post_residual becomes dead space; penalize.
    else if next_item_size > 0 {
        score += 15.0;
        // Heavier penalty if the dead space is large (waste potential).
        if post_residual > bin_capacity / 4 {
            score += 10.0;
        }
    }

    // Penalize bins far below mean residual (they are already loose/inefficient).
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score -= 0.3 * (residual_f - mean_residual);
    } else {
        score += 0.3 * (mean_residual - residual_f);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in the stream: slightly prefer opening/using fresh large-residual bins
    // to keep flexibility; late in the stream: pack tightly, minimize post residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 0.2 * residual_f * 0.1;
    score += progress * 0.1 * post_residual as f64;

    // Brand-new bin candidate: prefer it only when no open bin gives a tight fit
    // (i.e., when item leaves large post_residual in every open bin).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // But if this is a fresh stream or the item is huge, opening is attractive.
        if item_size >= 60 || fitting_bins_count == 0 {
            score -= 15.0;
        }
        // If next item is small, a new big bin gives it a home.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 8.0;
        }
    }

    // Strongly reward very tight fits overall (small post_residual).
    if post_residual <= 5 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post residual that cannot fit typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: if the next item fits in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.3 * next_item_size as f64;
        } else {
            // Waste if next item nearly fits but not quite.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 10.0 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 10.0);
    score -= 8.0 * open_pressure;

    // Mean residual coupling: bins with residual far below mean are "scarce space",
    // favor them; bins far above mean can absorb items later.
    let dev = mean_residual - bin_residual as f64;
    score += 0.25 * dev;

    // Time horizon: early in stream, keep bins flexible (penalize very low post residual
    // only mildly); late in stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.6 + 0.8 * progress;

    // New-bin candidate adjustment: opening a new bin costs; only attractive when
    // item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let openness = 1.0 - progress;
        score = 100.0 - 30.0 * (item_size as f64 / bin_capacity as f64) * openness
            - 20.0 * open_pressure;
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    // Early in the stream (t small): prefer tight fits strongly (dead space penalized).
    // Late in the stream (t large): mild preference, allow spreading.
    let progress_weight = 0.5 + 1.5 * t * (1.0 - t) * 4.0; // peaks mid-stream
    let mut score = pr * (1.0 + 0.8 * progress_weight * (1.0 - norm_pr));

    // Quadratic dead-space penalty: unusable slivers cost more as stream advances.
    score += (norm_pr * norm_pr) * cap * (0.3 + 0.7 * t);

    // Reward near-perfect fits (post_residual small relative to item size).
    let tightness = 1.0 - (pr / item_size.max(1) as f64);
    score -= tightness * item_size as f64 * (0.4 + 0.6 * t);

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / cap) * (0.5 + 0.5 * t);
    } else if next_item_size > 0 {
        // Post residual cannot host next item: penalize, scaled by dead-space size.
        score += 4.0 + norm_pr * 10.0 * t;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Scarcity of fitting bins: mild reward for consolidating.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0).ln() * 2.0;
    }

    // New-bin candidate: penalize opening bins, more so mid/late stream,
    // unless current bin residual is badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - norm_pr).abs();
        score += 15.0 * (0.4 + 0.6 * t) - 5.0 * fragmentation;
    }

    // Deviation from mean residual: prefer bins that reduce residual variance.
    score += ((pr - mean_residual) / cap).powi(2) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post residual: classify by capacity fractions.
    // Classes: [0], [1..=9] (dead space, nearly unusable), [10..=33], [34..=50], [51..=66], [67..=100]
    let pr = post_residual;
    if pr > 0 && pr <= 9 {
        // dead space: tiny leftover that likely never fits an item (min size 1..100 unknown, but small leftovers are waste)
        score += 12.0;
    }

    // Reward leaving residuals that are "harmonic" with common capacity fractions
    // (multiples of 10, 25, 50 are reusable targets).
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 50 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Integer-division thresholds: post_residual bucket index
    let bucket = pr / 17; // harmonic granularity
    score += bucket as f64 * 2.5;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after next placement
            let post2 = pr - next_item_size;
            score -= 10.0 + (post2 as f64).min(30.0) * 0.4;
            if post2 % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize mildly unless this bin is last chance
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 * 0.5)).abs();
        // Prefer new bin when open bins are already tight (low mean residual)
        score += 30.0 - mean_residual * 0.35 + fragmentation * 0.2;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host the next item too
        }
    }

    // Stream progression: early on, be more willing to open bins (keep flexibility);
    // late, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0 * (post_residual as f64 / cap);

    // Prefer bins whose residual was already small relative to mean (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // realistic future item (min size 1, but tiny gaps < 10 are near-unusable)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, opening a new one is cheaper.
    score += 2.5 * open_bins_count as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // New-bin candidate calibration: an empty bin should only win when the
    // current fit is poor (large post_residual) or many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 1.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins deviating below the mean residual
    // (concentrate packing into emptier-context bins).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the leftover,
    // penalize when the leftover is smaller than the next item (dead space).
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 400.0;
        } else if post_residual < next_item_size {
            // Leftover can't host next item: dead-space penalty, worse when large.
            score += 0.6 * (post_residual as f64).powf(1.3);
        } else {
            // Leftover can host next item: reward closeness of the resulting gap.
            let gap = post_residual - next_item_size;
            score -= 2.0 * (next_item_size as f64) - 0.5 * (gap as f64);
        }
    }

    // Prefer bins tighter than average (fill crowded bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 60.0 - 80.0 * poor_fit;
    }

    // Late in the stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can never hold the next item.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        let nx = next_item_size as f64;
        if gap > 0.0 && gap < nx {
            score += 12.0 * (1.0 - gap / nx);
        } else if gap >= nx {
            // Reward bins whose leftover can host the lookahead item.
            score -= 6.0 * (nx / gap);
        }
    } else {
        // Last item: just fill as much as possible.
        score -= 20.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 + 0.25 * item_size as f64;
    } else if fitting_bins_count > 1 {
        // With alternatives, mildly prefer fuller bins.
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // is large relative to typical residual space (poor fit everywhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open = if open_bins_count > 0 { mean_residual } else { bin_capacity as f64 };
        // Open a new bin when the item barely fits anywhere (large item, small residuals).
        let scarcity = item_size as f64 / avg_open.max(1.0);
        let penalty = 45.0 - 25.0 * scarcity.min(1.5) - 10.0 * progress;
        score += penalty.max(0.0);
    }

    // Time-horizon modulation: early in the stream, be conservative with
    // fragmentation; late in the stream, pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);

    // Mild penalty for bins far from the mean residual (prefer balanced states),
    // scaled by how many bins are open.
    let spread = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * spread * (open_bins_count as f64).sqrt();

    // Small bonus for using bins that are already quite full.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 4.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = post * (1.0 + 0.8 * progress) - 0.35 * post * post / cap * (1.0 - progress);

    // Prefer tight fits: reward small post_residual, especially late in stream
    let tight_fit = -1.5 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + progress);

    // Dead space penalty: small but nonzero post_residual is hard to reuse
    let dead = if post > 0.0 && post < 10.0 {
        (10.0 - post) * (1.5 + progress)
    } else { 0.0 };

    // Lookahead: if next item fits into post_residual, reward this placement
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= post {
        -2.0 * (next_item_size as f64 / cap) * (1.0 - progress)
    } else if next_item_size > 0 {
        0.5 * (next_item_size as f64 / cap)
    } else { 0.0 };

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    let last_chance = if fitting_bins_count == 1 { -3.0 } else { 0.0 };

    // Slight preference to keep bins balanced vs mean residual
    let balance = 0.2 * (post - mean_residual).abs() / cap;

    // New-bin candidate: penalize mildly so open bins are preferred unless fit is bad
    let new_bin = if bin_residual == bin_capacity {
        2.0 + 3.0 * progress * (1.0 - item_size as f64 / cap)
    } else { 0.0 };

    poly + tight_fit + dead + lookahead + last_chance + balance + new_bin
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items whose sizes divide capacity well
    // leave residuals that are "reusable" classes (multiples of common sizes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that are multiples of common item classes (10,20,25,50)
    let class_bonus = if post_residual % 50 == 0 {
        12.0
    } else if post_residual % 25 == 0 {
        8.0
    } else if post_residual % 20 == 0 {
        6.0
    } else if post_residual % 10 == 0 {
        4.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Penalize tiny dead space that no item (>=1) can use usefully, but
    // reward exact fills.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score += 6.0;
    }

    // Integer-division threshold: bucket post_residual into fifths of capacity.
    let fifth = (cap / 5.0).floor();
    let bucket = (pr / fifth).floor();
    score += bucket * 2.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly
            let slack = (post_residual - next_item_size) as f64;
            if slack % 10.0 == 0.0 {
                score -= 10.0;
            }
            score -= 5.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: mild penalty if residual becomes dead
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    // (large post_residual waste) or many bins already open with high mean residual.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.0);
        let mean_frac = mean_residual / cap;
        score += 5.0 + pressure * 2.0 - mean_frac * 10.0;
        // If item is large relative to capacity, prefer existing bins.
        score += (item_size as f64 / cap) * 8.0;
    }

    // Progress coupling: later in stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += pr * (0.1 + 0.2 * progress);

    // Reward tight fits overall (small post_residual relative to item).
    score -= 10.0 * (1.0 - (item_size as f64 / bin_residual.max(1) as f64).min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps too small to fit the smallest plausible item (size 1..10 zone)
    if post_residual > 0 && post_residual < item_size.min(10) {
        score += 25.0;
    }

    // Reward tight fits (near-perfect packing)
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: penalize adding to crowded bin sets mildly,
    // but reward consolidating into open bins vs opening new ones.
    if bin_residual != bin_capacity {
        score -= 8.0 + (open_bins_count as f64).min(20.0) * 0.4;
    } else {
        // New-bin candidate: penalize opening new bins, more when many bins are open
        score += 12.0 + open_bins_count as f64 * 1.5;
        // But allow opening a new bin early in the stream when few bins exist
        if open_bins_count <= 2 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: if next item can use this bin's post-residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit post-residual and post_residual is small, penalize
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 10.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins)
    score -= (mean_residual - post_residual as f64).clamp(-30.0, 30.0) * 0.3;

    // Stream progression: later in stream, be more conservative about waste
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward when the lookahead item fits into post_residual (2-step lookahead).
    if next_item_size > 0 && next_item_size <= post_residual {
        // Reward proportional to how snugly the next item will fit.
        let next_post = post_residual - next_item_size;
        score -= 40.0 + (next_post as f64) * 0.1;
    } else if next_item_size > 0 {
        // Penalize if the next item cannot follow into this bin (dead space risk).
        let gap = (next_item_size - post_residual) as f64;
        score += 5.0 + gap * 0.05;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize creating small unusable residuals (dead space) relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins whose residual is below the mean (filling emptier bins first keeps
    // larger residuals available for large future items).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Mild preference for keeping the number of open bins in check early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly: residuals that can't hold
    // even a small item (<=10) are wasted.
    if post_residual < 10 {
        score += 40.0;
    } else {
        let r = post_residual as f64;
        score += 0.15 * (r * r) / bin_capacity as f64;
    }

    // Lookahead: reward bins whose post residual can host the next item
    // (keeps chains of placements alive), penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Crowding penalty: when many bins are open, favor tighter fits to
    // consolidate; when few bins are open, allow spreading.
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64 / 20.0);
    score += crowding * (post_residual as f64) * 0.05;

    // Mean-residual coupling: if average residual is high, tighten fits;
    // if low, be more tolerant and prefer keeping big bins for big items.
    let tightness = mean_residual - post_residual as f64;
    score += 0.10 * tightness;

    // Time horizon: late in the stream, prefer aggressive packing of
    // existing bins; early, allow new-bin exploration.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when it creates a fresh large
    // residual and existing fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.6 * bin_capacity as f64
            && (fitting_bins_count == 0 || mean_residual < 20.0);
        if poor_fit {
            score -= 12.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr;
    // smooth non-linear coupling of post_residual with stream progress
    score += 12.0 * (pr_norm * pr_norm) * (0.5 + progress);
    score -= 20.0 * pr_norm * (1.0 - progress) * (1.0 - pr_norm);
    // penalize near-full bins slightly less as stream progresses (pack tightly early)
    score -= 15.0 * (1.0 - pr_norm).powi(3) * (1.0 - progress);
    // lookahead: reward residual matching next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0) * (1.0 - pr_norm);
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }
    // tie-break toward bins with larger residuals relative to mean
    score += 0.05 * (pr - mean_residual);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 (items are multiples of 10 in classic streams)
    let post = post_residual as u32;
    let residue_class = post % 10;
    // Dead-space penalty: residuals not forming a "harmonic" usable class are penalized
    if post > 0 {
        // residuals that are multiples of 10 are reusable; others get graded penalty
        let harmonic_bonus = match residue_class {
            0 => 6.0,
            5 => 3.0,
            _ => 0.0,
        };
        score -= harmonic_bonus;
        // penalize awkward mid-range dead space (11..=29) strongly
        if post >= 11 && post <= 29 {
            score += 8.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Small residual is good (tight packing) but not too small to be useless
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac < 0.10 {
        score += 4.0; // tiny slivers are nearly dead space
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // harmonic pairing: exact match or multiple-of-10 match rewarded
            if next_item_size == post {
                score -= 20.0;
            } else if post % 10 == 0 && next_item_size % 10 == 0 {
                score -= 6.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item cannot follow here; penalize proportional to overflow
            let over = (next_item_size - post) as f64;
            score += 2.0 + over * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // with many options, prefer tighter fits: mild competition scaling
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // New-bin candidate handling: empty bin has residual == capacity
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, decays as stream progresses
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * (0.9 - 0.2 * progress);
        // opening a bin is fine if current item is large (few future pairing options)
        if item_size >= 50 {
            score -= 10.0;
        }
        // if only one fitting bin exists, opening new bin is bad
        if fitting_bins_count <= 1 {
            score += 30.0;
        }
        // if mean residual across open bins is large, prefer reusing them
        if mean_residual > item_size as f64 * 1.5 {
            score += 12.0;
        }
    }

    // Mild preference for bins below mean residual (consolidating emptier bins)
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for any item (min size 1..10 range) are wasted.
    if post_residual < 10 {
        score += 200.0; // unusable dead space
    } else if post_residual < 20 {
        score += 60.0; // nearly unusable gap
    }

    // Reward tight fits (small post_residual relative to item size).
    score -= 0.8 * (item_size as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 40.0 + 12.0 * (open_bins_count as f64);
        // But if no open bin fits well, allow new bin when item is large.
        if item_size > 70 && fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 25.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 15.0;
    }

    // Mild normalization against mean residual state.
    score -= 0.1 * (mean_residual - post_residual as f64);

    // Late-stream consolidation: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but avoid tiny useless residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead-space penalty
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if nxt <= pr {
            // next item fits in this bin after current placement
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 80.0; // perfect chaining
            }
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            score += 10.0 * (diff / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: bins below mean residual are "tighter",
    // filling them first keeps many spacious bins open.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 25.0 * (pr / mean_residual - 1.0).clamp(-1.0, 1.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score so it wins
    // only when no open bin offers a good (tight) fit.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.75 + 20.0;
        if next_item_size > 0 && (next_item_size as f64 - item_size as f64).abs() < 5.0 {
            score -= 30.0; // two similar large items pair well in a fresh bin
        }
    }

    // Late-stream consolidation: near the end, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - pr / bin_capacity as f64);

    // Many open bins: encourage using the fullest ones.
    if open_bins_count > 3 {
        score += 0.5 * pr * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post residual (chaining placements).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.1 * next_item_size as f64;
        } else if post_residual > 0 {
            // Penalize leaving a residual that wastes capacity for the next item.
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins have poor fits and global residuals are low.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let global_tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Penalize new bins more when many bins are open with slack.
        score += 20.0 + 15.0 * (open_bins_count as f64).ln().max(0.0)
               - 20.0 * global_tightness
               - 10.0 * progress;
    } else {
        // Mildly prefer bins with below-average residual (consolidate waste).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Early stream: be slightly conservative with filling bins perfectly,
    // keep flexibility; late stream: commit harder to tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let progress_curve = t * t * (3.0 - 2.0 * t); // smoothstep
    let mut score = pr * (1.0 + 0.8 * progress_curve);

    // Polynomial penalty for small-but-nonzero dead space
    let dead = base * base * (1.0 - base);
    score += 60.0 * dead;

    // Reward tight fits (low post residual) more as stream progresses
    score -= (1.0 - base) * (1.0 - base) * 20.0 * (0.5 + t);

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item could fit in the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 - pr) / cap;
    }

    // Mild penalty for scattering across many open bins
    score += 0.5 * open_bins_count as f64 * t;

    // Penalize when this bin's residual deviates strongly from mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: discourage unless current bin fits are very poor
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 / cap - 1.0).abs();
        score += 25.0 - 15.0 * progress_curve - 10.0 * poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residual mod small divisors
    let r = post_residual;
    let frac = r as f64 / bin_capacity as f64;

    // Penalize leftovers in "dead" harmonic classes (hard to fill later)
    let class_penalty = |r: u32| -> f64 {
        let mut p = 0.0;
        for &d in &[3u32, 5, 7] {
            let m = r % d;
            // classes near half of divisor are worst (awkward gaps)
            let bad = ((m as f64) - (d as f64) * 0.5).abs() / (d as f64) * 0.5;
            p += bad;
        }
        p
    };
    score += class_penalty(r) * 4.0;

    // Reward near-perfect packing: post_residual in low classes
    if r == 0 {
        score -= 40.0;
    } else if r <= 3 {
        score -= 25.0;
    } else if r <= 10 {
        score -= 10.0;
    }

    // Exact harmonic complement: next item exactly fills leftover
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;
        } else if next_item_size <= r {
            // next item fits: reward proportional to fill of leftover
            score -= 12.0 * (next_item_size as f64 / r as f64);
            // leftover after next item, its class quality
            let r2 = r - next_item_size;
            if r2 % 2 == 0 {
                score -= 3.0;
            }
            if r2 <= 10 && r2 > 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this leftover: penalize small leftovers
            if r < next_item_size && r < 25 {
                score += 6.0;
            }
        }
    } else {
        // last item: strongly prefer zero residual
        score -= 20.0 * (1.0 - frac);
    }

    // Last-chance bin: avoid wasting it on a bad fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when all open bins are tight
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 0.75;
        if tight || open_bins_count == 0 {
            score -= 8.0;
        } else {
            score += 10.0 + mean_residual * 0.15;
        }
    }

    // Prefer fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * (0.5 + progress);

    // Coupling with mean residual: prefer bins below mean residual (tighter)
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are tiny relative to typical items
    // are nearly unusable -> penalize them heavily (non-linear).
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 10.0 {
        score += 60.0 * (1.0 - pr / 10.0); // worst for gap == 1
    } else if pr > 10.0 && pr < 30.0 {
        score += 8.0 * ((30.0 - pr) / 20.0); // moderate dead-space penalty
    }

    // Reward tight fits (small post_residual already low, add bonus).
    if post_residual == 0 {
        score -= 25.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // mild penalty keeps competition meaningful
        score += 3.0;
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins unless residual is large and useful.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure;

    // New-bin candidate handling: empty bin should only win when it can
    // eventually host large items (large useful residual) and current fits are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a bin, reduced when few bins open or stream is early
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut nb = 45.0 - 20.0 * (1.0 - progress) - 5.0 * pressure;
        // lookahead: if next item is large, a fresh bin is more valuable
        if next_item_size >= 50 {
            nb -= 15.0;
        } else if next_item_size > 0 && next_item_size <= post_residual as u32 {
            nb += 5.0; // next item could have fit here anyway; keep current bins tight
        }
        score += nb;
    }

    // Lookahead synergy: if next item exactly fits the post_residual, big bonus.
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 30.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 6.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // next item won't fit here; slight penalty for stranding residual
        score += 4.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins first),
    // keeping looser bins available for larger future items.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Two-step lookahead: reward post_residual that exactly matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact 2-step match
        if gap == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits here too: reward closeness
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item would not fit: penalize leftover that is too small to be useful
            score += 12.0 * (1.0 - post_residual as f64 / 30.0).max(0.0);
        }
    } else {
        // Last item: minimize waste directly
        score -= 10.0;
    }

    // Last chance: only bin that fits the item -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating tiny dead space (< 10, unusable since min item size is 1..100 unknown; use small threshold)
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // Prefer bins tighter than average (best-fit flavor relative to mean residual)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening new bins when stream is long and many bins already open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 10.0 * progress;
        // But if existing residuals are large/wasteful, opening a new bin is fine
        if mean_residual < 15.0 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual already encodes this, amplify slightly.
    score += 0.3 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count >= 2 {
        // Mild competition penalty scaled by scarcity inverse.
        score += 2.0 / fitting_bins_count as f64;
    }

    // Lookahead: if the next item can fit into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining: post residual exactly matches next item.
            if post_residual == next_item_size {
                score -= 40.0;
            } else {
                score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
            }
        } else {
            // Residual too small for next item: penalize dead space relative to next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // New-bin candidate: penalize unless it's genuinely better than poor fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Opening a new bin wastes residual capacity of open bins.
            score += 30.0 + mean_residual * 0.2;
        }
        // If stream is nearly done, opening bins is cheap-ish; reduce penalty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Time horizon: late in the stream, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates favorably from the mean (tighter than average).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Penalize very large open-bin counts slightly to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post-residual), with non-linear shaping.
    let mut score = pr
        + 30.0 * pr_norm * pr_norm          // penalize large dead space quadratically
        - 18.0 * (1.0 - pr_norm) * pr_norm; // reward near-full fills (peak around pr_norm ~ 0.5)

    // Smooth stream-progress coupling: early on, keep bins flexible;
    // late in the stream, push harder for tight packing.
    let flexibility = (1.0 - progress).max(0.0);
    score += 25.0 * progress * pr_norm * pr_norm;
    score -= 10.0 * flexibility * pr_norm * (1.0 - pr_norm);

    // Lookahead: reward residual that can host the next item, smoothly.
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as f64;
        let slack = (pr - next_item_size as f64).abs() / cap;
        score -= 14.0 * fits_next * (1.0 - slack);
        score += 8.0 * (1.0 - fits_next) * (next_item_size as f64 / cap);
    }

    // Last-chance bin: smooth bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr_norm);
    }

    // Mild penalty when bin is far from mean residual (imbalance), smooth coupling.
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: large residual → naturally high score; add smooth deterrent
    // that relaxes as the stream progresses (late stage may prefer consolidation).
    if bin_residual == bin_capacity {
        score += 40.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap;

    // Harmonic class penalty: post_residual divisible by common item sizes
    // leaves "friendly" residue that other items may fill exactly.
    let mut harmonic_bonus = 0.0;
    if post_residual > 0 {
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                harmonic_bonus += 6.0;
            }
        }
        // Odd residue classes are dead space
        if post_residual % 2 == 1 {
            harmonic_bonus -= 3.0;
        }
        if post_residual < 10 {
            harmonic_bonus -= 8.0; // unusable sliver
        }
    } else {
        harmonic_bonus += 12.0; // perfect closure
    }

    score -= harmonic_bonus;

    // Lookahead coupling: does next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + (next_item_size as f64 / cap) * 8.0;
            // exact match with next item
            if next_item_size == post_residual {
                score -= 15.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bin attractive only when
    // current open bins have poor fits.
    if bin_residual == bin_capacity {
        // Empty bin baseline: moderately high so it's chosen only when needed
        score = 45.0 + mean_residual * 0.3 - (open_bins_count as f64) * 1.5;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing else fits, must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_f / cap) * 5.0;

    // Small tie-break on mean residual alignment
    score += (mean_residual - post_f).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item (size 1) are fine, but gaps below a "usable threshold" are dead
    // space. Penalize unusable gaps quadratically.
    let usable_threshold = 10.0f64; // smallest plausible item is 1..100; treat <10 as near-dead
    if (post_residual as f64) < usable_threshold && post_residual > 0 {
        score += (usable_threshold - post_residual as f64) * (usable_threshold - post_residual as f64) * 6.0;
    }

    // Perfect / near-perfect fits are highly desirable: reward strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward leaving a gap that can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap that blocks the next item: penalize proportionally.
        score += (next_item_size as f64 - post_residual as f64) * 0.9;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.15 * (bin_residual as f64);
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; with few open bins, opening a new one is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score += 12.0 + pressure;
        // Early in the stream, new bins are relatively cheap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 8.0;
        // If the next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 6.0;
        }
    } else {
        // Existing bins get a mild bonus to be preferred over new bins,
        // scaled by how tight the fit is relative to the mean residual.
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score -= 10.0 - tightness * 5.0;
        // Penalize bins far below the mean residual (wasteful choice).
        if (bin_residual as f64) > mean_residual * 1.5 {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            score -= 100.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit: penalize wasted space relative to next_item_size
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Mild penalty for opening new bins when plenty fit
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 20.0 + mean_residual * 0.1;
    }

    // Progression: later in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly preferred.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward; if it
    // would be blocked by a tiny leftover, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else if next_item_size <= bin_residual {
            // Next item fits this bin now but not after placement -> mild penalty
            // unless current placement is very tight.
            if post_residual > 15 {
                score += 5.0;
            }
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 && mean_residual > item_size as f64 {
        score -= 10.0 * (mean_residual / bin_capacity as f64);
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize new-bin less implicitly by not over-rewarding tight fits);
    // late in the stream, squeeze existing bins harder.
    if progress > 0.7 {
        score -= 3.0;
    } else if progress < 0.2 && bin_residual == bin_capacity {
        score -= 12.0; // early: fresh bins are cheap
    }

    // New-bin candidate handling: only attractive early or when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 18.0 };
        score += desperation - 10.0 * (1.0 - progress);
    }

    // Mild preference for bins whose residual is close to the item (perfect fit shaping).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 5.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, non-linearly warped by stream progress.
    // Early: prefer tight fits (quadratic penalty on large residual).
    // Late: residual waste dominates, stronger convex penalty.
    let warp = 1.0 + 1.5 * progress * progress;
    let mut score = pr * warp + norm_pr * norm_pr * cap * (0.5 + progress);

    // Dead-space avoidance: residuals too small for the smallest plausible item.
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) * (2.0 + 3.0 * progress) } else { 0.0 };
    score += dead;

    // Lookahead coupling: reward residuals that still fit the next item,
    // penalize residuals that would leave the next item stranded.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= (1.0 - norm_pr) * nx * 0.4;
        } else {
            score += (nx - pr) * 0.6 * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Slight penalty relative to mean residual: avoid fragmenting bins
    // that are already loose when mean residual is high.
    score += 0.15 * (mean_residual - pr).max(0.0);

    // Mild preference for filling existing bins over opening new ones,
    // scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let post = post_residual;
    let class = post % 10;

    // Penalize residuals that are small but nonzero (dead space, unusable for typical items)
    if post > 0 && post < 10 {
        score += 25.0;
    }

    // Reward exact fits
    if post == 0 {
        score -= 40.0;
    }

    // Harmonic classes: residuals that are multiples of 10 are "clean" states
    if class == 0 && post > 0 {
        score -= 8.0;
    }
    // Odd/awkward classes penalized mildly
    if class == 1 || class == 9 {
        score += 4.0;
    }

    // Integer division thresholds on post_residual: how well next item fits
    if next_item_size > 0 {
        if next_item_size <= post {
            // Next item fits here: reward tight coupling
            let tightness = (next_item_size as f64) / (post as f64);
            score -= 15.0 * tightness;
            if post == next_item_size {
                score -= 20.0;
            }
        } else {
            // Next item cannot use this residual: penalize by wasted fraction
            let waste = (next_item_size as f64 - post as f64) / (bin_capacity as f64);
            score += 12.0 * waste;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad dead space
    if bin_residual == bin_capacity {
        let dead = post as f64;
        if dead > 0.0 && dead < 10.0 {
            score -= 20.0; // opening new bin better than leaving tiny dead space
        } else {
            score += 15.0; // prefer open bins generally
        }
    }

    // Favor fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post as f64 / bin_capacity as f64);

    // Coupling with mean residual: prefer bins below mean (tighter packing)
    score += 0.3 * (post as f64 - mean_residual);

    // Many open bins: encourage consolidation into fuller bins
    if open_bins_count > 3 {
        score += 0.05 * (open_bins_count as f64) * (post as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Anything below the minimum item size (1) is impossible, but gaps in
    // the low range (1..=10) are effectively dead space for most streams.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity (small post_residual
    // relative to capacity already handled by base term, add coupling).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score += tightness * 8.0;

    // Open-bin pressure: discourage spreading across many bins when a
    // compact packing is possible; mild penalty grows with open_bins_count.
    score += (open_bins_count as f64).powf(1.3) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item would fit exactly into the post_residual,
    // reward this placement; if next item is larger than post_residual
    // but small enough to matter, penalize blocking it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += (next_item_size - post_residual).min(20) as f64 * 0.8;
        }
    }

    // New-bin candidate handling: an empty bin has zero dead-space risk;
    // make it moderately attractive only when current bin would leave
    // a very poor (tiny) residual, otherwise prefer filling open bins.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
        score = (bin_capacity as f64) * 0.9 + poor_fit * 30.0 - (open_bins_count as f64) * 0.5;
        // If no other bin fits, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Slight progression bias: later in the stream, consolidation matters
    // more; nudge toward bins with below-average residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (tiny dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits exactly
    // into the post residual, penalize when it cannot fit.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportional to how tightly the next item nests.
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize more as post residual
            // becomes unusable dead space relative to mean residual.
            let waste = post_residual as f64 - mean_residual.min(post_residual as f64);
            score += 40.0 + 0.5 * waste.max(0.0);
        }
    }

    // Penalize creating dead space below the minimum item size (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive if no good fit exists; make the
    // empty bin mildly unattractive so existing bins are preferred.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if the item is large and next item is also large, opening a
        // fresh bin keeps residuals balanced.
        if item_size >= 70 && next_item_size >= 50 {
            score -= 80.0;
        }
    }

    // Mild penalty for spreading across many open bins: prefer tighter bins
    // (small residual relative to mean) to consolidate load.
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Late-stream pressure: as the stream nears its end, waste matters more,
    // so favor filling existing bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness;

    // Penalize residual that is small but nonzero (dead space unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Perfect two-item fill is excellent.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            score += 5.0;
        }
        // If next item is large, prefer consolidating into few bins now.
        if next_item_size > 50 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // New-bin candidate handling: empty bin gets baseline attractiveness,
    // better when open bins have poor fits or high fragmentation.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 10.0;
        // If many open bins already have large mean residual, prefer reusing them.
        if mean_residual > item_size as f64 * 1.5 {
            score += 20.0;
        }
        // Late in stream, avoid opening new bins unless fragmentation is severe.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.7 && fragmentation < 30.0 {
            score += 15.0;
        }
        // Early stream: opening fresh bins is cheap, slightly encourage.
        if progress < 0.3 {
            score -= 5.0;
        }
    }

    // Penalize bins whose residual deviates wildly from mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild penalty per open bin to discourage bin sprawl indirectly.
    score += 0.02 * open_bins_count as f64;

    // Prefer filling bins that are already more than half empty used.
    if bin_residual as f64 <= mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: raw post-residual, gently damped at extremes via smooth coupling.
    let mut score = pr * (1.0 + 0.35 * (x - 0.5) * (x - 0.5));

    // Non-linear progress coupling: later in stream, penalize waste more strongly.
    score += 18.0 * x * x * progress;
    score -= 10.0 * (1.0 - x) * (1.0 - x) * progress;

    // Smooth interaction between post_residual and mean residual: prefer bins
    // whose post-residual aligns with the fleet's average slack.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.5 + progress);

    // Lookahead: reward residual that leaves room for the next item (smooth kernel).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let d = (pr - n) / cap;
        score -= 9.0 * (-8.0 * d * d).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x) * (1.0 + progress);
    }

    // Mild penalty for opening a new bin when many bins are already open.
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (3.0 + 0.4 * open_bins_count as f64 * (0.3 + progress));

    // Smooth dead-space penalty: residuals too small to ever fit (below min item size).
    let dead = ((10.0 - pr) / cap).max(0.0);
    score += 40.0 * dead * dead * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal post_residual (tight fits win).
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near multiples of small
    // item sizes are more reusable. Penalize "dead" residues that cannot
    // host typical items (1..100 range): residue < smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        // Dead space: nearly unusable — heavy penalty.
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Modulo-classes: residue divisible by common item classes (e.g. 10, 20, 25)
    // is more likely to be exactly filled later -> reward.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 { score -= 6.0; }
        if r % 20 == 0 { score -= 3.0; }
        if r % 25 == 0 { score -= 3.0; }
        if r % 50 == 0 { score -= 4.0; }
    }

    // Lookahead coupling: if next item fits the post_residual exactly or
    // nearly, strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0; // perfect chain fit
        } else if next_item_size <= r {
            let slack = r - next_item_size;
            // reward decays with slack; harmonic class of slack
            score -= 15.0 / (1.0 + slack as f64 / 10.0);
            if slack % 10 == 0 { score -= 4.0; }
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += 2.0 * ((next_item_size - r).min(30) as f64) / 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual.
    // Penalize opening a new bin unless current fit is poor / no good option.
    if bin_residual == bin_capacity {
        // New bin cost: grows with number of open bins (fragmentation risk).
        score = (bin_capacity - item_size) as f64 + 8.0 + 0.5 * open_bins_count as f64;
        // If mean residual across open bins is large, opening new bins is bad.
        score += 0.3 * mean_residual;
        // But if this is a large item and open bins are fragmented, allow it:
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
        // Early stream: fewer bins open, new bins are cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for filling bins that are already partially loaded
    // when many bins are open (reduce bin count pressure).
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward placements where the gap could still fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for lookahead: dead space risk.
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins,
    // but reward using bins when few are open.
    score += open_bins_count as f64 * 0.7;

    // Last-chance bin: strongly favor filling it to avoid waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin opening unless the item leaves a useful gap
    // or open bins are already numerous/tight.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 30.0 - pressure * 20.0;
        if post_residual >= 20 {
            score -= 10.0;
        }
    }

    // Prefer bins with residuals close to the item (tight fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Late-stream urgency: consolidate as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 4 {
            score -= 300.0;
        } else if post_residual < next_item_size {
            // Dead space relative to the next item: penalize proportionally.
            let gap = post_residual as f64;
            score += gap * 1.5;
        }
        // Chain potential: next item leaves room again for a small item.
        if post_residual >= next_item_size {
            let chain_residual = post_residual - next_item_size;
            if chain_residual <= 10 {
                score -= 80.0;
            }
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize bins whose residual deviates far below the mean (wasting space in tight bins is fine,
    // but dumping into a large-residual bin with a bad fit is not).
    let res = post_residual as f64;
    if res > mean_residual + 15.0 {
        score += (res - mean_residual) * 0.8;
    }

    // Prefer tighter fits as stream progresses (less time to fix fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += res * (0.3 + 0.7 * progress);

    // Mild preference for consolidating into fewer bins when many are open.
    score -= (open_bins_count as f64) * 0.5;

    // Slight penalty for leaving large awkward residuals (hard to fill later).
    if post_residual > item_size && post_residual > 30 {
        score += (post_residual as f64) * 0.2;
    }

    // New-bin candidate: only attractive if no good fit exists (post_residual here == capacity).
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling)
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.8 * waste.min(40.0);
        } else if post_residual >= next_item_size {
            // Reward bins whose leftover can still host the next item
            score -= 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize creating very small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: default mild penalty so we prefer reusing bins,
    // but relax it when the fit into open bins is bad (large item relative to residual)
    if bin_residual == bin_capacity {
        let mut newbin_penalty = 8.0;
        // If item is large and mean residual is tight, opening a new bin is attractive
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        if fit_ratio > 0.5 && mean_residual < item_size as f64 * 1.2 {
            newbin_penalty -= 6.0;
        }
        // Late in stream, prefer closing out bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        newbin_penalty *= 1.0 - 0.3 * progress;
        score += newbin_penalty;
    }

    // Prefer bins below mean residual (more full bins first)
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time-horizon modulation: early stream, be greedy for tight fits; later, be conservative
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: penalize residuals more as stream advances
    score += 12.0 * pr_norm * progress * (1.0 + progress);

    // Tight-fit reward: strongly favor small post residuals
    score -= 18.0 * (1.0 - pr_norm).powi(4);

    // Dead-space penalty: residuals too small to fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only fitting bin -> encourage using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 - pr).max(0.0) / cap;
    }

    // Mean-residual alignment: prefer bins near the mean residual
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin unless residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64) * (1.0 - mean_residual / cap);
        score += 30.0 - 20.0 * (fragmentation / (open_bins_count.max(1) as f64 + 1.0)).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: small dead space is valuable, huge residual waste is bad.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // capacity fraction remaining

    // Dead-space penalty: strongly punish residuals that are hard to fill (e.g. 1..=9 or 51..=59 style gaps).
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10; // harmonic subclass
        let dead_penalty = match class {
            0 => -6.0,           // round residual: very reusable
            1..=3 => 4.0,        // awkward slivers
            4..=6 => 0.5,
            7..=9 => 2.5,
            _ => 0.0,
        };
        score += dead_penalty;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Fractional capacity coupling: residuals in [0, 0.1C] are gold; in (0.5C, 0.6C) are mediocre
    if frac <= 0.1 && frac > 0.0 {
        score -= 8.0;
    } else if frac > 0.5 && frac < 0.6 {
        score += 5.0;
    }

    // Integer-division threshold: residual that can hold next_item_size is good (lookahead pairing)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual / next_item_size.max(1)) as f64 * 2.0;
        } else {
            score += 6.0; // this bin becomes dead after placement
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral-ish, slightly penalized so we prefer filling existing bins
    if bin_residual == bin_capacity {
        score += 55.0;
        // but allow new bin if stream is early and current bins are crowded
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 8 && mean_residual < 25.0 {
            score -= 40.0 * (1.0 - progress);
        }
    }

    // Mild preference to spread load when many bins are open
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized.
    if post_residual >= 1 && post_residual <= 12 {
        score += 45.0 - (post_residual as f64) * 1.5; // smaller gap => bigger penalty
    }

    // Medium gaps (13..=25) are mildly wasteful; larger gaps are more reusable.
    if post_residual > 12 && post_residual <= 25 {
        score += 8.0;
    }

    // Reward leaving a gap that can fit the known next item (lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64) * 0.15;
    }

    // Penalize if the residual left is below the minimum plausible item size (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor consolidation.
    score += (open_bins_count as f64) * 1.2;

    // Last-chance bin: if this is the only bin that can fit, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.8 + (mean_residual / bin_capacity as f64) * 15.0;
        // Opening a new bin is penalized by default; relaxed when many bins / high mean residual.
        score += 55.0 - pressure;
        // If next item is large and this item is small, a fresh bin keeps flexibility.
        if next_item_size > item_size {
            score -= 12.0;
        }
    }

    // Slight late-stream tightening: near the end, prefer filling existing bins fully.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Deviation from mean residual: prefer bins whose residual is far from average
    // (fills outliers, keeps a homogeneous pool of residuals).
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual exactly equals next item -> strong reward.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == nr {
            score -= 60.0;
        } else if pr > nr {
            // Residual can still host the next item: reward proportional to leftover tightness.
            let slack = pr - nr;
            score -= 25.0 - 0.35 * slack;
        } else {
            // Next item won't fit: dead space penalty grows with gap.
            score += 0.5 * (nr - pr);
        }

        // Two-step chain: if post_residual equals item_size too (same-size stream), extra reward.
        if pr == item_size as f64 && pr == nr {
            score -= 15.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.3 * post_residual as f64;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor vs fleet average).
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin before opening a new one: strong bonus to use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening new bins when plenty of open bins exist and fit is decent.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        // But allow new bin if current bin would leave awkward small residual.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (build diversity).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 12.0;

    // Penalize dead space that next item cannot use.
    if next_item_size > 0 {
        if (post_residual as u64) < (next_item_size as u64) {
            score += (next_item_size as f64 - post_residual as f64) * 0.6;
        } else if post_residual == next_item_size {
            // Perfect lookahead fit: strong reward.
            score -= 25.0;
        } else {
            score -= 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 18.0 + 30.0 * (1.0 - progress) + (open_bins_count as f64).powf(0.8);
        score += new_bin_penalty;
        // Allow new bin if residual is very fragmented (mean residual small).
        if mean_residual < item_size as f64 * 0.5 {
            score -= 22.0;
        }
    } else {
        // Slight preference for bins below mean residual (consolidate fullness).
        if (bin_residual as f64) < mean_residual {
            score -= 2.5;
        }
        // Reward filling bins closer to capacity.
        let used_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= used_ratio * 6.0;
    }

    // Mild time-horizon modulation: early on, be conservative with big bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.6 * progress) - 0.35 * post * post / cap;

    // Tight fits are rewarded more as the stream progresses
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * (10.0 + 40.0 * progress);

    // Lookahead synergy: reward residual that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 + progress);
        } else {
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize bins that are outliers vs mean residual (fragmentation control)
    score += 0.15 * (post - mean_residual).abs();

    // New-bin candidate: prefer it early or when it enables a clean fit
    if bin_residual == bin_capacity {
        score -= 12.0 * (1.0 - progress);
        score += 5.0 * norm_post;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does it fall into?
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Class via integer division thresholds (harmonic bands: 1/2, 1/3, 1/4 of capacity)
    let class = if post_residual == 0 { 0 }
        else if post_residual >= 50 { 1 }
        else if post_residual >= 34 { 2 }
        else if post_residual >= 25 { 3 }
        else { 4 };

    // Reward exact/low waste strongly
    match class {
        0 => score -= 40.0,                       // perfect fill
        1 => score -= 18.0,                       // half-bin or better left
        2 => score -= 8.0,                        // third-band residual
        3 => score -= 2.0,                        // quarter-band residual
        _ => score += 6.0,                        // tiny dead space
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // item sizes (10, 20, 25, 50) are reusable -> reward them.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 3.0; }
        if post_residual % 20 == 0 { score -= 2.0; }
        if post_residual % 25 == 0 { score -= 2.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    }

    // Lookahead: does next item fit into post_residual? Strong coupling reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if next item exactly fills the post-residual (harmonic closure)
        if next_item_size == post_residual { score -= 10.0; }
        // Reward if next item's post-residual would also be in a good class
        let npr = post_residual - next_item_size;
        if npr >= 50 { score -= 3.0; }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space relative to lookahead: penalize proportionally
        score += (next_item_size as f64 - pr) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen if open bins look bad
        score += 25.0;
        // Early in stream or many open bins with low mean residual: opening fresh is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 20.0 || progress < 0.1 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 10.0; // big lookahead item benefits from a fresh bin
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05 * frac;

    // Slight preference for tighter fits overall
    score += (item_size as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps: post_residual below the minimum item size (1)
    // is fine, but gaps that are small-but-positive (1..=8) are "dead space"
    // since typical items rarely fit them.
    if post_residual > 0 && post_residual <= 8 {
        score += 40.0 - (post_residual as f64) * 2.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 15.0;
    }

    // Reward tight fits relative to residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Open bins pressure: discourage spreading when many bins are open
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // would leave a very poor residual in existing bins.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If next item is large and this item is small, opening fresh may help
        if next_item_size > 0 && next_item_size > post_residual && item_size < 30 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item would fit in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }

    // Progress-based mild tightening: later in stream, be greedier about fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // next item fits here too: mild reward proportional to tightness
            score -= 50.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // dead space relative to lookahead: penalize, worse when gap is small-but-nonzero
            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 * gap;
            if gap <= 10.0 {
                score += 60.0; // unusable sliver
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New bin candidate: only attractive when current bin residual is small/dead
    if bin_residual == bin_capacity {
        // penalize opening new bins early on; allow late in stream or when few bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 200.0 - 100.0 * progress;
        if item_size > 50 && next_item_size == 0 {
            score -= 250.0; // endgame: fresh bin harmless
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let residual = bin_residual as f64;
    let fit_ratio = item_size as f64 / residual; // in (0, 1]
    score -= 0.6 * fit_ratio * fit_ratio * residual;

    // Exact / near-exact fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual < 10 {
        // Dead space below minimum item size is unusable.
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Lookahead: if the next item can chain into the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let chain_eff = nxt / post_residual as f64;
            score -= 8.0 * chain_eff;
        } else {
            // Next item won't fit here: mild penalty proportional to leftover gap.
            score += 0.15 * (post_residual as f64 - nxt).abs().min(20.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.2 * fit_ratio * residual;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to capacity or all open fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_alternatives = mean_residual - item_size as f64;
        // Penalize new bins generally; relax when open bins have large scattered residuals
        // late in the stream (fragmentation) or the item is big.
        let mut nb = 20.0;
        if poor_alternatives < 10.0 {
            nb -= 10.0; // open bins are nearly full anyway
        }
        if item_size > 60 {
            nb -= 6.0;
        }
        if progress > 0.7 && open_bins_count > 3 {
            nb -= 5.0 * (mean_residual / bin_capacity as f64);
        }
        score += nb;
    }

    // Global fragmentation pressure: when mean residual is small, squeezing items
    // into existing bins becomes more valuable.
    let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += 6.0 * frag * (post_residual as f64 / bin_capacity as f64);

    // Mild preference to keep bin residuals aligned with common item sizes.
    if post_residual >= 10 {
        score += 2.0 * ((post_residual as f64).rem_euclid(10.0) / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress * (1.0 - progress) * 4.0; // peaks mid-stream, ~0 at ends
    score -= 8.0 * (norm_pr * norm_pr) * (1.0 + t);
    score += 3.0 * norm_pr * norm_pr * norm_pr * (1.0 - progress);

    // Tight fit reward: quadratic in post-residual smallness
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Last-chance bonus when few fitting bins
    if fitting_bins_count == 1 {
        score -= 5.0 + 4.0 * progress;
    }

    // Penalize opening new bin when open bins could fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 4.0 + 6.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    // Lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) as f64;
            score -= 3.0 * (1.0 - (slack / cap).min(1.0)) * (0.4 + 0.6 * progress);
        } else {
            score += 2.0 * (nx - pr) / cap;
        }
    }

    // Mean residual coupling: prefer bins near the mean
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // Harmonic class width: capacity split into 10 residue classes
    let cw = (bin_capacity / 10).max(1);
    let cwf = cw as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Core: quadratic waste-risk model.
    // Expected waste ~ residual * P(residual never filled); P(filled) shrinks as residual grows.
    let mut score = pr + (pr * pr) / cap;

    // Late in the stream, leftover residual increasingly becomes pure waste
    score += progress * 0.4 * pr;

    // Perfect fit: close the bin with zero waste
    if post_residual == 0 {
        score -= 1.5 * cap;
    }

    // Harmonic lookahead (k=2): couple post_residual class with next item size
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if next_item_size == post_residual {
            // exact chain: next item closes this bin perfectly
            score -= 1.2 * cap;
        } else if next_item_size < post_residual {
            let after = pr - ni;
            // reward chains that land in a low (usable) harmonic class
            score -= 0.4 * cap / (1.0 + after / cwf);
            // residue classes tile exactly by the next item's size
            if post_residual % next_item_size == 0 {
                score -= 0.25 * cap;
            }
            // chaining would strand dead space below one class width
            if after > 0.0 && after < cwf {
                score += 0.2 * cap;
            }
        }
        // if next_item_size > post_residual: no chain possible, core risk term already penalizes
    }

    if is_new_bin {
        // Fresh capacity is expensive: base cost
        score += 0.25 * cap;
        // Prefer consuming existing slack spread across open bins
        score += 0.10 * mean_residual;
        // Many open bins already: opening more fragments capacity
        score += 0.05 * open_bins_count as f64;
        // Late-stream: almost never open a new bin
        score += progress * 0.60 * cap;
        // Large items naturally seed a fresh bin
        if item_size as f64 >= 0.5 * cap {
            score -= 0.15 * cap;
        }
    } else {
        // Within-class tiebreak: lower position inside the harmonic class wins
        score += 0.05 * (post_residual % cw) as f64;
        // Last-chance bin: if this is the only open bin that fits, use it
        // rather than paying for fresh capacity
        if fitting_bins_count == 1 {
            score -= 0.35 * cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than large leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Large leftover space is still somewhat usable; mild reward.
        score -= (post_residual as f64) * 0.15;
    }

    // Tight fit reward relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    score += open_bins_count as f64 * 1.5;

    // If this bin's residual is near the mean residual, it's a "typical" bin;
    // slightly prefer compacting bins with low residual.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        // Next item cannot use this tiny gap anyway; soften the dead-space penalty.
        score -= 15.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by its large flexibility.
        score = 55.0 - (post_residual as f64) * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 40.0;
        } else if diff <= 5.0 {
            score -= 15.0 - diff * 2.0;
        } else {
            // Penalize post-residuals that are too small to fit the next item (dead space),
            // scaled by how small they are relative to next item.
            if post < nxt {
                score += (nxt - post) * 0.8;
            } else {
                // Post-residual larger than next item: mild penalty growing with gap.
                score += (diff - 5.0) * 0.15;
            }
        }
        // Bonus if bin can host BOTH current and next item tightly (post_residual >= next).
        if post >= nxt && post - nxt <= 10.0 {
            score -= 8.0;
        }
    } else {
        // Last item: just prefer minimal waste, slight sharpening.
        score *= 1.2;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    let post_f = post_residual as f64;
    score += (post_f - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current bin fits are very poor.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins unless they create big dead space.
        score += 5.0;
        // If placing item in an open bin would leave tiny unusable residue (<10),
        // opening a fresh bin becomes competitive.
        if next_item_size > 0 && post_residual < 10 && post_residual > 0 {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheap; late, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space with a superlinear term
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 10.0);
    }

    // Reward tight fits strongly
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so new bins are not opened frivolously
        score += 15.0;
        // early in stream, keep some openness to new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
        // if many bins are open and fragmented, a fresh bin is more attractive
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain fit
        } else {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        }
    }
    // Penalize if next item is slightly larger than post residual (near-miss wastes space)
    if next_item_size > post_residual && next_item_size <= bin_capacity {
        let gap = next_item_size as f64 - post_residual as f64;
        if gap <= 10.0 {
            score += gap * 1.5;
        }
    }

    // Prefer bins with residual below mean (consolidate fragmentation)
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.3;

    // Time horizon: late in stream, be conservative, favor filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.3 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * (1.0 - pr_norm);
    score += 12.0 * poly;

    // Tight fits rewarded more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space that can't fit typical future items
    if pr > 0 && pr < 10 {
        score += 6.0 * (1.0 - progress);
    }

    // Last-chance bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.3 + 0.7 * progress);
    }

    // Lookahead: if next item fits post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 7.0;
    } else if next_item_size > 0 && (next_item_size as f64) <= pr + 10.0 {
        score -= 2.0;
    }

    // Mild penalty for leaving residual far from mean (fragmentation)
    score += 0.15 * (pr - mean_residual).abs();

    // Discard tendency to open new bins early when many bins already open
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible into fine classes.
    let pr = post_residual as i64;
    let nis = next_item_size as i64;

    // Class A: post_residual exactly matches next item -> near-perfect lookahead fit.
    if nis > 0 && pr == nis {
        score -= 60.0;
    }
    // Class B: next item fits with small slack (<= 5).
    if nis > 0 && nis <= pr && (pr - nis) <= 5 {
        score -= 35.0;
    }
    // Class C: next item fits with moderate slack (<= 15).
    if nis > 0 && nis <= pr && (pr - nis) <= 15 {
        score -= 15.0;
    }
    // Class D: next item does NOT fit this residual -> dead space risk, penalize.
    if nis > 0 && nis > pr {
        score += 12.0 + (nis - pr) as f64 * 0.4;
    }

    // Modulo-class bonuses: residuals that are nice packing targets.
    if pr > 0 && pr % 10 == 0 {
        score -= 8.0; // round-decade residual is a reusable class
    }
    if pr > 0 && pr % 25 == 0 {
        score -= 6.0;
    }
    // Ugly residuals: tiny unusable slivers.
    if pr > 0 && pr < 10 {
        score += 20.0; // dead space, effectively wasted
    }

    // Integer-division thresholds on post_residual.
    let quart = (bin_capacity as i64) / 4; // 25
    if pr > quart && pr <= 2 * quart {
        score -= 5.0; // sweet middle band
    }
    if pr > 3 * quart {
        score -= 10.0 * (pr as f64 / bin_capacity as f64); // large residual: keep bin flexible
    }

    // Last-chance bin: strongly prefer filling it rather than leaving it hanging.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Brand-new bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 18.0 };
        score += pressure;
        // Early stream: opening bins is fine; late stream: prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If next item is huge and this item is small, opening a fresh bin is good.
        if nis >= 70 {
            score -= 15.0;
        }
    }

    // Slight preference toward bins tighter than the mean residual (fragmentation control).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Exact fit is maximally rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Fit tightness: reward placements that consume a large fraction of residual.
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 5.0; // creates a gap the next item cannot use
        }
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the empty-bin candidate gets penalized), encouraging consolidation.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 3.0;
        // But if the current bin would be a poor host, opening a new bin is fine.
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0;
        }
    } else {
        // Slight preference for bins with larger residuals (better hosts).
        score += (bin_capacity as f64 - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this is an ideal chained placement.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * lookahead_gap;
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize residuals too small for the next item (dead space risk).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare residual against mean residual across open bins: prefer using
    // bins that are already below-average filled (consolidation).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize leaving large awkward dead space relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // tiny residual is nearly dead space; use it now
    }

    // Early in stream: be slightly conservative, prefer new bins for big items
    // to keep flexibility; late in stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // New empty bin candidate: baseline penalty so it's only chosen when
    // open bins score poorly.
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: penalize proportional to wasted space ratio.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Reward near-perfect fills (post_residual small relative to capacity).
    if post_residual as f64 <= 0.05 * bin_capacity as f64 {
        score -= 25.0;
    }

    // Penalize leaving dead space that the next item likely cannot use.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // Next item won't fit here: dead space penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        } else {
            // Next item fits in the leftover: reward chaining.
            score -= 8.0;
        }
    }

    // Last-chance bin before opening a new bin: strong bonus to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make opening a new bin attractive only when
    // existing residuals are large relative to the item (poor fits everywhere).
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins, grows with number of open bins.
        score += 12.0 + 0.5 * open_bins_count as f64;
        // But if mean residual is high (existing bins are all nearly full),
        // opening a fresh bin becomes more attractive.
        let mean_fit = item_size as f64 / mean_residual.max(1.0);
        if mean_fit > 0.8 {
            score -= 20.0;
        }
        // Late in the stream, avoid opening new bins unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference for bins with residual close to mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Small penalty for many open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // Time-decay on wasted space: early on tolerate slack, later be strict.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr + 0.5 * (1.0 - progress) * norm_pr * norm_pr);

    // Smooth penalty for small post_residual (dead space), stronger late in stream
    let dead = 1.0 - norm_pr;
    score += 30.0 * dead * dead * dead * (0.5 + 0.5 * progress);

    // Reward tight fits via smooth coupling with item size fraction
    let fit_quality = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_quality * fit_quality * (1.0 - progress * 0.5);

    // Last-chance bonus: strongly prefer this bin when it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - 0.3 * progress);
    } else {
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: penalize if next item won't fit the post-residual (smooth margin term)
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += 10.0 * (gap / cap) * (1.0 + progress);
        } else {
            score -= 6.0 * (-gap / cap) * (1.0 - progress);
        }
    }

    // Mild preference to consolidate into fewer bins, weighted by mean residual divergence
    score += 0.5 * (mean_residual - pr).abs() / cap;

    // New-bin candidate handling: make empty bin attractive only when fits are poor
    if bin_residual == bin_capacity {
        score = pr + 20.0 * (1.0 - fit_quality.min(1.0)) * (0.5 + 0.5 * progress) + 5.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact quarter classes are ideal
    let post = post_residual;
    let q = (post * 4) / bin_capacity; // 0..3 harmonic quarter class
    let rem = post % (bin_capacity / 4);

    // Reward residuals that are exact fractions of capacity (perfect future fits)
    let frac_bonus = match post {
        0 => 100.0,
        p if p == bin_capacity / 2 => 60.0,
        p if p == bin_capacity / 4 || p == 3 * bin_capacity / 4 => 40.0,
        p if p % 10 == 0 => 20.0,
        _ => 0.0,
    };
    score -= frac_bonus;

    // Penalize being just inside a harmonic class boundary (dead space trap)
    if rem <= 5 && post > 0 {
        score += 25.0 - rem as f64 * 4.0;
    }

    // Integer-division threshold: small post residuals are wasted capacity
    let small_class = post / 10; // 10-unit granularity
    if small_class < 3 && post > 0 {
        score += (3 - small_class) as f64 * 15.0;
    }

    // Lookahead coupling: does the next item fit a harmonic class of post_residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // next item fits: reward if it lands exactly in a class
            let slack = post - next_item_size;
            if slack % 10 == 0 {
                score -= 35.0;
            } else {
                score -= 12.0;
            }
            // perfect pair: post_residual becomes a clean fraction again
            if slack == 0 || slack == bin_capacity / 4 || slack == bin_capacity / 2 {
                score -= 30.0;
            }
        } else {
            // next item cannot fit here: penalize less if post residual is still useful
            score += if post >= 20 { 8.0 } else { 20.0 };
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when item is huge or no good open bins
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = (item_size as f64 / cap) > 0.7;
        let poor_open = mean_residual < item_size as f64 * 0.6;
        if big_item || poor_open {
            score -= 30.0 + 20.0 * progress;
        } else {
            score += 55.0; // discourage wasting fresh bins
        }
    }

    // Mild preference for tighter bins overall (below mean residual)
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // Small tie-break noise-free deterministic jitter via modulo of step index
    score - ((step_index % 4) as f64) * 0.25
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

