    }
    // Reward perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Reward gaps that can fit the next item (future-proofing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    if new_bin {
        score += 30.0 + 12.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        // Last-chance bonus: if this is the only fitting bin, strongly favor it.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Favor tighter bins relative to mean residual.
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward exact match of post_residual to next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect 2-step fill: residual consumed exactly by next item
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual as f64 >= nxt {
            // Next item fits in leftover: partial reward decaying with slack
            score -= 30.0 * (nxt / (post_residual as f64 + 1.0));
        } else {
            // Dead space that next item cannot use: penalize proportionally
            score += 0.5 * diff;
        }
    }

    // --- Tightness: reward small post residual relative to capacity ---
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // --- Last chance: strongly favor using the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // --- Prefer bins below mean residual (keep residuals balanced) ---
    score += 0.3 * (post_residual as f64 - mean_residual);

    // --- Early stream: be slightly more exploratory (favor new bins less) ---
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it only wins on bad fits
        score += 15.0 - 10.0 * progress;
        // Opening fresh is good if lookahead item is huge and current item small
        if next_item_size > 60 && item_size < 30 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score -= 60.0 * (1.0 - tight).powi(4);

    // Penalize dead space that no future small item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 30.0 * (1.0 - (slack as f64) / bin_capacity as f64);
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // Next item would need another bin if placed here; slight penalty unless tight fit.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
