    }

    // Global pressure: many open bins with low mean residual -> consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    score -= 10.0 * consolidation * (0.5 + progress);

    // New-bin candidate handling: neutral-ish early, expensive later unless item is large.
    if bin_residual == bin_capacity {
        let openness = 1.0 - progress;
        score -= 35.0 * openness;
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // Avoid opening new bins when existing bins have plenty of room.
        if mean_residual > 30.0 {
            score += 20.0;
        }
    }

    // Mild preference for filling bins with larger residual when few bins open.
    if open_bins_count <= 2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: post residual, mildly non-linear (quadratic waste penalty)
    let mut score = post + 30.0 * norm_post * norm_post;

    // Smooth polynomial coupling with stream progress:
    // early stream: tolerate loose fits; late stream: strongly prefer tight fits
    let progress_coupling = 60.0 * progress * (1.0 - progress) * (norm_post - 0.5);
    score -= progress_coupling;

    // Last-chance bonus (avoid opening a new bin when only one bin fits)
    if fitting_bins_count == 1 {
        score -= 25.0 + 40.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 - post) / cap;
    }

    // Penalize bins far below mean residual (unbalanced dead space)
    score += 10.0 * ((post - mean_residual) / cap).abs();

    // Slight preference for existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    // Normalize by open bin pressure
    score /= 1.0 + 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Penalize residuals in "dead" classes: too small for typical next items
    // (mod 25 classes: 0 is perfect, 1..10 nearly dead, 11..25 usable)
    let dead_zone = (post_residual % 25) as f64;
    if post_residual > 0 {
        score += (10.0 - dead_zone.min(10.0)) * 1.5;
    } else {
        score -= 30.0; // perfect closure reward
    }

    // Reward tight fits: post_residual small relative to item
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 12.0;

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        // extra reward if next item nearly fills it (harmonic pairing)
        let pair = post_residual - next_item_size;
        if pair <= 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // neutral baseline; penalize slightly so decent fits win
        score += 5.0;
        // but if stream is early or mean residual is high (fragmentation),
        // opening fresh bins is fine
        if mean_residual > 40.0 {
            score -= 10.0;
        }
        if step_index < total_items / 10 {
            score -= 8.0;
        }
    }

    // Mild fragmentation pressure: prefer bins below mean residual
    // (consolidate into emptier bins, keep fuller ones for small items)
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Integer division threshold: residuals divisible by common item sizes
    // are more reusable
    for d in [10u32, 20, 25, 50].iter() {
        if post_residual >= *d && post_residual % d == 0 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mild preference toward bins tighter than average residual.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // next item fits here afterwards: mild reward proportional to coupling
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot use leftover: penalize dead space
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Penalize opening a new bin when an open bin could fit reasonably
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0 + 2.0 * fitting_bins_count as f64;
    }

    // Early in stream: be more conservative about leaving tiny fragments
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // lookahead fits: reward roomy leftovers slightly
            score -= 5.0 * (next_item_size as f64 / 100.0);
        } else {
            // dead space for the next item: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 0.4 * waste;
        }
    } else {
        // last item: only tightness matters
        score -= 10.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Early in the stream, encourage opening new bins to build a good pool
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it early or when existing bins are fragmented
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 20.0 - 25.0 * progress;
        score += 0.3 * open_bins_count as f64;
        score += 0.1 * fragmentation;
    } else {
        // Prefer bins whose residual deviates favorably from the mean (consolidate)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
        // Late in the stream, be greedy about tight fits
        score -= 15.0 * progress * tightness;
    }

    // Mild penalty for large post_residual creating unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let is_new_bin = (bin_residual as u64 == bin_capacity as u64) as f64;

    // Base: minimize waste, non-linearly penalized
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth coupling of waste with stream progress: waste matters more early
    score += 25.0 * pr_norm * pr_norm * (1.0 - progress) * (1.0 - progress);

    // Polynomial coupling: post_residual vs mean residual (fragmentation spread)
    let spread = (pr - mean_residual) / cap;
    score += 10.0 * spread * spread * spread.abs() * cap;

    // Lookahead: reward if next item fits smoothly in post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let tight = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 15.0 * tight * tight;
    } else if next_item_size > 0 {
        // penalize dead space that cannot host next item
        score += 8.0 * pr_norm * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 30.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening new bins when open bins exist,
    // penalty decays smoothly with progress and with large waste avoided
    score += is_new_bin * (20.0 + 30.0 * (1.0 - progress) * (1.0 - progress) + 2.0 * open_bins_count as f64);

    // Mild reward for tightening bins as stream advances
    score -= 5.0 * (item_size as f64 / cap) * progress;

    // Crowding: slightly prefer bins among many fitting options to be tighter
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln() * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 8ths.
    let eighth = bin_capacity as f64 / 8.0;
    let class = (post_residual as f64 / eighth).floor(); // 0..=8

    // Perfect fits (post_residual 0 or tiny) are golden.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Penalize leftovers in awkward harmonic classes (dead space zones).
    // Classes 1 and 2 (<=25 residual) are hard to refill; classes near half
    // capacity (4) are reusable by mid-size items.
    match class as u32 {
        0 => score -= 300.0,          // nearly full bin: excellent
        1 => score += 60.0,           // 12.5..25 residual: awkward
        2 => score += 25.0,           // 25..37.5: mildly awkward
        3 => score -= 20.0,           // good zone
        4 => score -= 40.0,           // ~half full: very reusable
        5 => score -= 10.0,
        6 => score += 0.0,
        7 => score += 15.0,           // mostly empty: weak placement
        _ => score += 30.0,           // nearly empty
    }

    // Lookahead coupling: does post_residual accommodate next_item_size?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly: reward proportionally to how snugly next item fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 80.0 - snug.min(80.0);
            // Harmonic bonus if post_residual is an exact multiple of next size.
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here; penalize if this was the only fitting bin.
            if fitting_bins_count <= 1 {
                score += 70.0;
            } else {
                score += 15.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 2 {
        score -= 90.0;
    }

    // New-bin candidate handling: fresh bin has full residual. Only prefer it
    // when the current item is large and would leave a bad class elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Mild penalty so open bins with good fits win; escalate late in stream
        // when consolidation matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 40.0 * (1.0 - progress);
        // But a fresh bin is great for very large items leaving class-1 leftovers
        // in existing bins... reward if item is in top third of capacity.
        if item_size * 3 >= bin_capacity * 2 {
            score -= 25.0;
        }
    }

    // Slight preference to fill bins that are already below mean residual
    // (balance toward compacting low-residual bins).
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Tie-break: fewer open bins is better; nudge toward denser packing early.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small leftover gaps that few future items can use.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }

    // If the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    }
    // Penalize if next item cannot use this bin's leftover but could use current residual.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 40.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score -= pressure * 2.0;

    // Prefer bins below mean residual (waste consolidation).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0 || (fitting_bins_count == 1 && bin_residual >= bin_capacity);
        if poor_fit {
            score -= 150.0 + progress * 50.0;
        } else {
            score += 250.0 + open_bins_count as f64 * 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect 2-step matches: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Penalize leftover after hypothetical next-item placement
        let after_next = (post_residual - next_item_size) as f64;
        score += after_next * 0.5;
        // Reward if next item fits snugly relative to mean residual
        if after_next < mean_residual * 0.2 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit in this bin after placement; penalize dead space
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Penalize large post_residual (wasted space) relative to mean residual
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when current bin fits are poor
    if bin_residual == bin_capacity {
        // Base penalty so open bins are usually preferred
        score += 15.0;
        // But if the item is large relative to capacity and mean residual is small,
        // opening a fresh bin is better
        if (item_size as f64) > bin_capacity as f64 * 0.5 && mean_residual < item_size as f64 {
            score -= 30.0;
        }
        // Late in stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Small bonus for tight fits overall
    score -= (bin_capacity as f64 - post_residual as f64).recip() * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly: post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Dead-space penalty: leftover that no plausible item (>=1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this bin heavily (chaining placements).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 20.0 + 0.3 * slack_after_next as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement; slight penalty if it
        // would have fit the current residual (we may be blocking it).
        if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins: encourage consolidation into fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.05 * open_pressure * (bin_residual as f64 - post_residual as f64);

    // Mean residual coupling: if this bin is below-average fullness,
    // prefer it slightly (balance), unless it's a fresh bin.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.1 * dev;
    }

    // New-bin candidate handling: only attractive when the item fits poorly
    // everywhere else (large post_residual elsewhere) or stream is early.
    if bin_residual == bin_capacity {
        let base = 55.0;
        // Late in the stream, opening new bins is more costly.
        let time_cost = 30.0 * progress;
        // If the item is large, a fresh bin is more forgiving for the future.
        let size_relief = 0.4 * item_size as f64;
        score = base + time_cost - size_relief;
        // If next item is huge, a fresh bin keeps flexibility.
        if next_item_size > 60 {
            score -= 15.0;
        }
        // If many bins are open and this item fits somewhere, discourage new bin.
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - pr / cap; // how full the bin becomes
    let mut score = pr;

    // Reward tight fits with a smooth cubic bonus
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize large dead space quadratically, growing with stream progress
    let dead = pr / cap;
    score += 25.0 * dead * dead * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty when bin residual deviates from mean residual (diversity of gaps)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate: keep it slightly unattractive unless it's a large item
    if bin_residual == bin_capacity {
        score += 12.0 - 0.08 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: harmonic class 0 (post_residual == 0)
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic classes on post_residual: divisible-by-10 residuals are "clean"
    // and likely reusable by future items; penalize dirty residuals.
    let clean = post_residual % 10 == 0;
    if clean {
        score -= 8.0;
    } else {
        score += (10 - (post_residual % 10)) as f64 * 1.5;
    }

    // Small dead space is bad: post_residual in [1..=9] is nearly unusable
    // for items >= 10, so penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Coupling with next item: if the next item fits exactly into post_residual,
    // strongly reward; if it nearly fits (within 10), mild reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (large post_residual waste).
    if fitting_bins_count == 1 {
        score -= 60.0;
        if post_residual >= 50 {
            score += 30.0; // but bad fit overrides
        }
    }

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity.
    // Prefer it only when the item is huge relative to capacity or no clean fits exist.
    if bin_residual == bin_capacity {
        // baseline penalty so full bins are usually preferred
        score += 30.0;
        // but if the item is large (> half capacity), opening fresh is reasonable
        if item_size * 2 > bin_capacity {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Tight fit reward: fraction of bin consumed
    let fill = (item_size as f64) / (bin_capacity as f64);
    score -= fill * 25.0;

    // Late in the stream, consolidate: prefer bins with low residual to close them out
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // Prefer bins below mean residual slightly (balance residuals across bins)
    score += ((mean_residual - post_residual as f64) * 0.2).max(-10.0).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers (1..=10) are nearly unusable
    // for future items (sizes >= 1 but typically >= 10), so penalize them heavily.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    } else if post_residual > 80 {
        // Large leftover is still very usable; reward keeping big spaces.
        score -= 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward exact fit for the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap that the next item just barely misses.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
        score += 12.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill_fraction = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_fraction;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins; opening new bins becomes relatively more attractive
    // only when open_bins_count is small (early stream).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., filling the fullest bins first keeps emptier bins flexible).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild penalty for the brand-new empty bin candidate unless the stream
    // is early or the fit into open bins is bad; empty-bin residual equals
    // capacity so its post_residual is large, which already favors it.
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the remaining space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits, but penalize leftover proportional to how much stays stranded.
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.5;
            if after_next == 0 {
                score -= 250.0;
            }
        } else {
            // Next item cannot use this residual: penalize dead space more strongly.
            score += post_residual as f64 * 0.8;
        }
    }

    // Penalize residuals too small to be useful for typical items (dead space band).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below the mean (tighter packing).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: make empty bins attractive only when current bins would leave
    // large unusable residuals; otherwise keep using open bins.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen when open-bin fits are poor.
        score += 60.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin guarantees a fit for the next item too.
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Penalize dead space quadratically: small post-residuals are good,
    // but residuals too small for the smallest future item (<=10) are dead.
    if post_residual < 10 {
        score += 30.0; // unusable sliver — strongly penalize
    } else {
        score -= (post_residual as f64 / bin_capacity as f64) * 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 5.0; // next item cannot follow here
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate logic: empty bin should only win when no open bin
    // gives a decent fit. Penalize opening a new bin normally, but the
    // penalty shrinks late in the stream or when open bins are already crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 18.0 - 8.0 * progress - crowd.min(10.0);
        // If lookahead item is large and a fresh bin guarantees a good pair, soften penalty.
        if next_item_size >= item_size && next_item_size + item_size <= bin_capacity {
            score -= 4.0;
        }
    }

    // Mild preference for bins below mean residual (consolidating emptier bins
    // keeps fuller bins available for small items).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    let fit = item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: penalize large residuals more as stream progresses
    score += prn * prn * (40.0 + 60.0 * progress) * cap * 0.1;

    // Reward tight fits via smooth cubic term
    score -= fit * fit * fit * 30.0 * (1.0 - progress);

    // Dead-space penalty: residuals too small for typical future items
    let dead = ((prn - 0.15) * (prn - 0.15) * (prn - 0.15)).max(0.0);
    score += dead * cap * 0.5 * (0.5 + progress);

    // Lookahead: reward leaving room for next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = prn - nx;
        let match_term = 1.0 - (gap * gap).min(1.0);
        score -= match_term * 25.0;
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count <= 1 {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for bin proliferation early on
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // New-bin candidate: keep it slightly worse than good fits
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by its residue class mod 10
    // (typical item granularity). Small residues are "dead space" classes.
    let r = post_residual;
    if r > 0 {
        let m = r % 10;
        // Dead-space penalty: residues 1..=5 are nearly unusable for items >=10.
        if m > 0 && m <= 5 {
            score += 6.0 - m as f64; // residue 1 worst
        }
        // Exact division classes reward: post_residual divisible by 10/20/25/50
        if r % 50 == 0 { score -= 8.0; }
        else if r % 25 == 0 { score -= 5.0; }
        else if r % 20 == 0 { score -= 4.0; }
        else if r % 10 == 0 { score -= 2.5; }
    } else {
        // Perfect fill — best possible outcome.
        score -= 20.0;
    }

    // Tight-fit reward: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac * fill_frac;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 15.0;
        } else if slack % 10 == 0 {
            score -= 6.0;
        } else if slack <= 5 {
            score += 4.0; // leaves dead space for the next item
        }
    } else if next_item_size > 0 {
        // Next item cannot go here; bin becomes dead space for it.
        score += 3.0 + (next_item_size as f64 - post_residual as f64).min(10.0) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless all open bins are bad.
    if bin_residual == bin_capacity {
        let base = 30.0;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 14.0 * (fitting_bins_count as f64).min(3.0) };
        let progress = 6.0 * (step_index as f64 / (total_items.max(1) as f64));
        score = base + scarcity + progress;
        // If mean residual is large, open bins are fragmented; new bin more attractive.
        score -= (mean_residual / 10.0).min(6.0);
    }

    // Mild penalty for proliferating open bins with large mean residual (fragmentation).
    score += 0.15 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Integer-division threshold: prefer post_residual in coarse buckets
    let bucket = post_residual / 10;
    score += match bucket {
        0 => -10.0,
        1 => -4.0,
        2 => 0.0,
        3 => 2.0,
        4 => 3.0,
        _ => 4.0 + (bucket as f64 - 5.0) * 0.5,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: penalize leftovers that cannot host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (post_residual as f64 / next_item_size as f64).min(3.0);
        } else {
            score += 25.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else {
        // Pressure from number of open bins: prefer denser bins when many are open.
        score += open_bins_count as f64 * 0.5;
    }

    // Prefer bins tighter than the mean residual (consolidate slack).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild preference for using existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
    }

    // Late-stream: tighten packing as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer bins that leave small post-residual, but avoid tiny dead space.
    let post = post_residual as f64;
    if post > 0.0 && post < 5.0 {
        score += 12.0; // penalize creating nearly-unusable slivers
    }

    // 2-step lookahead: reward if next item fits the post-residual well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            // Reward tight 2-step packing; penalize leaving big slack after next item.
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
            if slack < 3.0 {
                score -= 6.0; // near-perfect 2-step match
            }
        } else {
            // Next item cannot fit here: penalize proportionally to the gap.
            score += 0.5 * (nxt - post).min(30.0);
        }
    } else {
        // Last item: just minimize post-residual, slightly stronger.
        score -= 3.0;
    }

    // Relative to mean residual: favor bins already tighter than average
    // (consolidate waste), unless it's a fresh empty bin.
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        score += 0.3 * (post - mean_residual).max(-20.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate: default penalty so it's chosen only when it wins outright.
    if is_new_bin {
        score += 8.0;
        // But if the current stream is early and bins are scarce, opening is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count == 0 {
            score -= 25.0;
        }
        // Late in the stream, prefer compacting into existing bins.
        score += 10.0 * progress;
    }

    // Mild preference for filling larger items into tighter bins overall.
    score += 0.05 * (item_size as f64) * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize dead space too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if bin_residual >= next_item_size {
            // Next item could go here instead; mild penalty for consuming this space.
            score += 5.0;
        }
        // If post_residual is exactly what next item leaves as perfect fit chain.
        if post_residual >= next_item_size && (post_residual - next_item_size) == 0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 40.0;
        // More open bins already => less eager to open another.
        score += open_bins_count as f64 * 2.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If mean residual across bins is large, opening a new bin is wasteful.
        score += mean_residual * 0.3;
        // Exception: item is huge and unlikely to fit elsewhere nicely.
        if item_size > 70 {
            score -= 15.0;
        }
    }

    // Slight preference for bins below mean residual (balancing residuals).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Prefer filling bins that are already mostly full (low residual) to close them out.
    if bin_residual <= item_size * 2 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: quadratic coupling of fill level with stream progress.
    let fill = (bin_residual - post_residual) as f64;
    score -= 0.35 * (fill * fill) / cap * (0.6 + 0.8 * t);

    // Penalize large leftover space (dead space), superlinearly.
    score += 0.004 * pr * pr * (0.5 + t);

    // Smooth interaction: leftover scaled by relative item size.
    let rel_item = item_size as f64 / cap;
    score += 8.0 * pr / cap * (1.0 - rel_item) * (1.0 - t);

    // Lookahead chaining: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0 * (1.0 - nx / cap) * (1.0 - 0.5 * t);
        } else {
            score += 3.0 * (nx - pr) / cap * t;
        }
    }

    // Last-chance bonus: only fitting bin -> strong preference.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 20.0 * t;
    } else if fitting_bins_count > 1 {
        // Mild normalization across many candidates.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: penalize opening a fresh bin, more so mid/late stream,
    // unless the item is large and residuals across open bins are tight.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tight = if cap > 0.0 { (mean_residual / cap).clamp(0.0, 1.0) } else { 0.0 };
        score += 18.0 * (1.0 - t) + 10.0 * t;
        score -= 25.0 * rel_item * (1.0 - tight);
        score += 5.0 * (open_bins_count as f64).sqrt() * t;
    } else {
        // Prefer bins deviating below the mean residual (tighter than average).
        score -= 2.0 * ((mean_residual - pr) / cap).clamp(-1.0, 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, with a mild convex penalty
    // on large residuals (dead space) using harmonic-style quadratic term.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Harmonic class of the residual: residuals divisible into small
    // classes are more reusable. Class = post_residual % 10.
    let class = post_residual % 10;
    let class_bonus: f64 = match class {
        0 => -6.0,           // perfectly "round" residual, highly reusable
        5 => -3.0,           // half-class, moderately reusable
        _ => (class as f64) * 0.15, // odd/ragged classes penalized
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual: tiny dead space is
    // nearly worthless; strongly penalize residuals below common small
    // item sizes (1..10 range).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into the
    // post-residual, reward heavily (chained harmonic match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // modulo coupling: how well next item divides into remaining space
            let rem = post_residual % next_item_size.max(1);
            score -= 8.0 - (rem as f64) * 0.5;
        } else {
            // next item cannot fit here anyway; slight penalty if this
            // placement leaves the bin stranded
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it
    // only wins when all open bins have poor fits.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.85 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can host the current item then next
        }
        return score;
    }

    // Progression-aware tightening: late in the stream, be greedier about
    // filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // Mean-residual context: if this bin's residual is far above the mean,
    // it is an underused bin; nudge selection toward it to balance bins.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score -= dev * 5.0;

    // Slight preference for bins that are already fairly full.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals that are too small to fit any plausible
    // future item (min item size 1, but practically < 10 are hard to reuse)
    // are pure waste. Penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }
    // Mid-range unusable gaps (10..=20) are mildly wasteful too.
    if post_residual >= 10 && post_residual <= 20 {
        score += 0.5 * (20.0 - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Prefer bins whose residual was already tight before placement
    // (consolidation of large items).
    if bin_residual < bin_capacity {
        let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 8.0 * tightness;
    }

    // Open-bins pressure: with many open bins, favor filling existing ones
    // over spreading; with few bins, opening a new one is cheap.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large (poor fit elsewhere) or there is heavy bin pressure.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 12.0 - 20.0 * large_item;
        if open_bins_count as f64 > mean_residual / 10.0 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item would fit exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item cannot fit in the post residual but this bin's pre-residual
    // could have held it, slightly penalize creating a gap that strands it.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 5.0;
    }

    // Late in the stream, consolidation matters more (no future to amortize
    // new bins): mildly strengthen preference for existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item size (perfect two-item fill).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64));
        // Exact match: strong bonus.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: prefer minimal leftover waste overall.
        score -= 20.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize large dead space that nothing small can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny leftover is fine (near-perfect fit)
    } else if post_residual >= 10 && post_residual < 40 {
        score += 5.0; // moderate dead space is mildly bad
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    // or this is a very tight fit elsewhere. Penalize default new bin.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // opening fresh may serve the future item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) non-linearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual > 0 && post_residual < 20 && post_residual < next_item_size {
        score += 12.0;
    }

    // Lookahead: if the next item fits the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.3 * (next_item_size as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't chain here: mild penalty proportional to waste
        score += 5.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // With multiple candidates, prefer tighter fits even more.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins with residual below mean residual (consolidating space).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in stream, be more willing to open new bins
    // (keep options open); late in stream, prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus exploration adjustment.
        score = bin_capacity as f64 - 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // new bin pairs well with large upcoming item
        }
        if open_bins_count > 8 {
            score += 10.0 * ((open_bins_count as f64) / 10.0); // discourage bin explosion
        }
    } else {
        score -= 10.0 * progress; // late stream: reward reusing open bins
        if open_bins_count > 8 {
            score -= 5.0; // too many open bins: consolidate
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) matter more
    let progress_coupling = (pr * pr) / cap * (progress * progress);
    score -= progress_coupling * 0.5;

    // Penalize dead space relative to mean residual (smooth quadratic divergence)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev;

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward leaving space compatible with next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_gap = (pr - n).abs() / cap;
        score += 5.0 * fit_gap * fit_gap;
        // bonus if post_residual exactly enables next item
        if pr >= n {
            score -= 3.0 * (1.0 - (pr - n) / cap);
        }
    }

    // Mild penalty for proliferating open bins, modulated by progress
    score += (open_bins_count as f64) * 0.3 * (0.5 + progress);

    // New-bin candidate handling: empty bin gets a smooth default score
    if bin_residual == bin_capacity {
        score = cap * (1.0 - 0.4 * progress) + 10.0 * norm_pr;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by residue classes.
    // Small leftovers (dead space) are penalized super-linearly.
    if post_residual > 0 {
        let pr = post_residual;
        // Dead space penalty: leftover in (0, 10) is nearly unusable (min item size region)
        if pr < 10 {
            score -= 40.0; // perfect fit: strongly reward
        } else if pr < 20 {
            score -= 12.0;
        } else if pr < 35 {
            score -= 4.0;
        } else if pr < 55 {
            score += 3.0;
        } else {
            score += 6.0; // large leftover: mildly wasteful placement
        }
        // Harmonic residue classes: leftovers divisible by common item sizes are reusable
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        }
        if pr % 25 == 0 {
            score -= 3.0;
        }
    } else {
        score -= 60.0; // exact fill
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 - 0.06 * slack.min(50.0); // reward chains
        } else {
            score += 5.0; // next item won't fit here; wasted coupling
        }
        // Harmonic match: leftover equals a multiple of next item
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score modulated by context
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when few bins fit or mean residual is high (fragmented)
        score = 45.0 + 0.25 * mean_residual - 3.0 * (fitting_bins_count as f64);
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 5.0; // next item needs fresh space anyway
        }
    }

    // Mild pressure to prefer fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Tie-break: prefer bins whose residual is close to item (tight fit)
    score += 0.05 * ((bin_residual as f64 - item_size as f64) - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Fit quality relative to item size: tighter fits preferred.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Pressure from number of open bins: prefer filling existing bins
    // when many bins are already open.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += 10.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current
    // placement would leave a large, reusable gap or no bin fits well.
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 25.0;
        }
    }

    // Lookahead: if next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > post_residual && next_item_size > 0 && post_residual < 10 {
        score += 30.0; // dead space that cannot serve the next item
    }

    // Stream progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * tightness;

    // Prefer bins whose residual is below mean (compact bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: this placement enables exact fit next step
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover slack after the lookahead item would fit
            score += slack * 0.35;
            if slack <= 10.0 {
                score -= 12.0; // near-perfect chain bonus
            }
        } else {
            // next item cannot follow into this bin
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Compare post_residual against mean residual: prefer bins driven near the mean
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += mean_gap * 0.25;

    // Penalize large dead space that nothing (min size 1..10) can use
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // tiny residual is excellent (almost full bin)
    }
    if post_residual > bin_capacity as f64 * 0.5 {
        score += 8.0; // wasteful placement leaving over half the bin
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        // fresh bin has full residual; lookahead chain into empty bin is fine
        if next_item_size == 0 {
            score += 15.0;
        }
        // discourage opening new bins late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 20.0 * progress;
        // but encourage when open bins are all crowded
        score -= (mean_residual - 50.0).max(0.0) * 0.2;
    }

    // Slight preference for tighter bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Mild noise-free tie-break by step for determinism
    score += (step_index % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score -= 14.0 * (1.0 - tight * tight) * (item_size as f64 / bin_capacity as f64);

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
        // Chain fit: next item exactly fills residual.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: only open a new bin when fits are poor or bin count is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = if fitting_bins_count <= 1 { 0.0 } else { 30.0 };
        score = 35.0 + poor_fits + 10.0 * (1.0 - progress) - 8.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && bin_capacity >= next_item_size && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // pairing potential in a fresh bin
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    if bin_residual != bin_capacity {
        score -= 0.05 * mean_residual + 0.3 * open_bins_count as f64;
        // Time horizon: late in stream, consolidate aggressively.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth progress coupling: later in stream, penalize large residuals more strongly.
    let p2 = progress * progress;
    score += pr * (0.8 * p2 + 0.4 * progress * norm_pr);

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 18.0 * fit_quality * fit_quality;
        } else {
            // next item cannot use this bin: mild penalty scaled by wasted space
            score += 3.0 * norm_pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * (1.0 - norm_pr);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Mean residual coupling: penalize deviating far from the fleet mean (keeps bins balanced).
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * cap * 0.01;

    // Brand-new empty bin candidate: only attractive when it's a near-perfect fit for the item.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste * (1.5 + 2.0 * p2) - 0.5 * (item_size as f64);
        // discourage new bins when many open bins already fit
        score += 6.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class logic: classify post_residual by modulo classes.
    // Residuals that are multiples of 10 are "clean" (likely reusable by
    // typical item sizes); small non-zero remainders are semi-useful;
    // large remainders indicate awkward dead space.
    let harmonic_class = post_residual % 10;
    score -= match harmonic_class {
        0 => 6.0,
        1..=5 => 3.0,
        _ => 0.0,
    };

    // Lookahead coupling: reward bins whose post_residual can still host
    // the next item (chained packing); penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 + 0.1 * next_item_size as f64;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        // Opening a new bin is attractive for large items that fill it well,
        // unattractive for small items that would waste capacity.
        score += 12.0 - 10.0 * fill_frac;
        // No open bins yet: must open.
        if open_bins_count == 0 {
            score -= 15.0;
        }
        // If no open bin residual can host this item meaningfully, opening is fine.
        if mean_residual < item_size as f64 {
            score -= 6.0;
        }
    }

    // Prefer tighter-than-average bins (below-mean residual).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps that are too small to hold
    // even the smallest item (1) are pure waste; gaps below a practical threshold
    // (next item likely can't use them) are heavily penalized.
    if post_residual > 0 {
        // Unusable dead space: nothing can fit (post_residual < 1 is impossible for
        // integer sizes >= 1, but tiny gaps < next_item_size are likely wasted).
        let usable_threshold = if next_item_size > 0 { next_item_size } else { 10 };
        if post_residual < usable_threshold {
            // Dead space penalty: gap too small for the lookahead item.
            score += 60.0 * (1.0 - post_residual as f64 / usable_threshold as f64);
        }
        // Perfect fit bonus: strongly reward leaving zero residual.
        if post_residual == 0 {
            score -= 100.0;
        } else if post_residual <= 5 {
            // Near-perfect fit: small gaps are acceptable only if truly tiny.
            score -= 30.0;
        }
    }

    // Tightness reward: relative fill quality of this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 40.0 * tightness;

    // Last-chance pressure: if this is the ONLY bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items across
    // bins; with few open bins, be more permissive.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += 8.0 * bin_pressure;

    // Mean residual coupling: if this bin's residual is far above the mean,
    // it is "loose" and less attractive; below-mean residuals indicate well-packed bins.
    let residual_diff = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_diff;

    // New-bin candidate handling: an empty bin gets a baseline score that makes it
    // attractive only when no open bin offers a good fit. It has full residual
    // (100) so tightness term is low; add a mild opening cost so it is chosen
    // only when open bins would waste significant space.
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64;
        // If lookahead item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Lookahead synergy: reward placing current item so the next item fits well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tightness = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * next_tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: waste below 10 is heavily penalized.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    } else {
        // Dead-space penalty: unusable residual (too small for min item size 1..100 range)
        let dead = if post_residual > 50 { (post_residual - 50) as f64 } else { 0.0 };
        score += 1.5 * dead;
    }

    // 2-step lookahead: reward if next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain: this bin will close after next item
        } else if next_item_size < post_residual {
            let next_gap = post_residual - next_item_size;
            // Favor bins whose post-residual is a good host for the next item.
            score -= 2.0 * (100.0 - next_gap.min(100)) as f64 * 0.5;
            if next_gap < 10 {
                score -= 100.0;
            }
        } else {
            // Next item won't fit here; mild penalty scaled by how much it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.3 * miss;
        }
    }

    // Relative to mean residual: prefer bins with residual close to item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.4 * tightness;

    // Compare against mean residual: bins below mean residual are "tighter" -> prefer
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else {
        // More competing bins -> slight penalty to encourage consolidation into tightest
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: make opening a new bin costly unless nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        // Base cost of opening a new bin; reduced late in the stream.
        score += 120.0 - 40.0 * progress;
        // If no open bin can fit the item, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        // If the next item is large and current item small, opening a fresh bin
        // preserves large contiguous space for the future item.
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 60.0;
        }
    }

    // Slight preference for fewer open bins (consolidation) early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - step_index as f64 / (total_items as f64).max(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward (small dead space)
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Lookahead: penalize bins whose post residual cannot host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // chain potential
            // bonus proportional to how well next item fits after this
            let after2 = post_residual - next_item_size;
            score -= 10.0 * (after2 as f64 / bin_capacity as f64);
        } else {
            score += 20.0; // dead end for lookahead
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // spread competition: prefer bins with less residual among many options
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Global state coupling: many open bins with high mean residual -> encourage consolidation
    if open_bins_count > 0 {
        let consolidation_pressure = mean_residual / bin_capacity as f64;
        score += 15.0 * consolidation_pressure * (open_bins_count as f64).ln();
    }

    // Time horizon: early in stream, allow new bins more freely; late, pack tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 40.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: accept only when no open bin fits or current fit is terrible
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 500.0; // forced new bin
        } else if post_residual > 50 {
            score -= 10.0; // large residual usable later
        } else {
            score += 80.0; // discourage wasteful new bin
        }
    }

    // Penalize leaving residuals that are awkward (small but nonzero)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with progress:
    // early on, larger post_residual is tolerable; later, dead space is punished harder.
    let pr = post_residual as f64 / cap;
    let coupling = pr * pr * (1.0 + 2.0 * progress) + pr * (0.5 * progress * (1.0 - progress) * 4.0);
    score += coupling * cap;

    // Reward tight fits: quadratic bonus as post_residual approaches zero
    let tightness = 1.0 - pr;
    score -= 6.0 * tightness * tightness * tightness;

    // Penalize bins whose residual deviates from mean (fragmentation avoidance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev * cap;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let fit_gap = (post_residual as u32 - next_item_size) as f64 / cap;
        score -= 4.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
    }
    // If next item would be blocked, mild penalty
    if next_item_size > post_residual && next_item_size > 0 {
        score += 2.0;
    }

    // New-bin candidate: penalize mildly early, more when good fitting bins exist
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { 6.0 } else { -3.0 };
        score += pressure + 5.0 * (1.0 - progress);
    }

    // Mild penalty for proliferating bins
    score += 0.05 * open_bins_count as f64 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: small classes are "dead space"
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Integer-division thresholds on post_residual (harmonic classes of C)
        // Leftovers <= 10 are nearly dead space; leftovers in (10, 25] are risky.
        if post_residual <= 10 {
            score += 40.0; // penalize tiny unusable slivers
        } else if post_residual <= 25 {
            score += 12.0;
        } else if post_residual <= 50 {
            score -= 6.0; // half-bin leftovers are reusable
        } else {
            score -= 10.0; // large leftovers are very reusable
        }

        // Modulo-10 harmonic class: multiples of 10 align with typical item sizes
        if post_residual % 10 == 0 {
            score -= 8.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // chain perfect fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward based on how well next item harmonically divides leftover
            if slack <= 10 { score -= 60.0; }
            else if post_residual % next_item_size == 0 { score -= 25.0; }
            else { score -= 10.0 * (1.0 - slack / cap); }
        } else {
            // next item won't fit here: leftover must serve future unknowns
            score += 5.0 + pr * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline penalty so we prefer existing bins with decent fits
        score += 35.0;
        // early in stream or many open bins -> prefer consolidation instead
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 0 && mean_residual < (item_size as f64) {
            // no open bin is really usable -> allow new bin
            score -= 60.0;
        }
        if progress < 0.1 { score += 10.0; }
    } else {
        // mild preference for tighter existing bins via residual fraction
        score += (bin_residual as f64 / cap) * 3.0;
        // favor bins whose residual is close to item (fractional coupling)
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fit_ratio * fit_ratio;
    }

    // Mean-residual drift: keep global residuals balanced
    score -= 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps (< 10, min item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that are too small for the known next item are also likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual tightly matches the item (good fit quality).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and stream progress.
        score += 20.0 + 3.0 * open_bins_count as f64 + 15.0 * progress;
        // But if next item could combine with current item in a fresh bin, soften slightly.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0;
        }
    } else {
        // Using existing bins relieves pressure; scale with open bin count.
        score -= (open_bins_count as f64).min(10.0);
    }

    // Prefer bins with residual close to the mean (keeps bin residuals balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item can't follow: penalize dead space in this bin
            score += 25.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Compare post residual to mean residual: prefer bins that end below average residual
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: only prefer new bin when all fits are poor
    if bin_residual == bin_capacity {
        let tight_fit = next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 5;
        if post_residual == 0 || tight_fit {
            score -= 50.0;
        } else {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space that the next item cannot use: penalize proportionally.
            let waste = (next_item_size - post_residual).min(post_residual) as f64;
            score += 4.0 * waste / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins far below mean residual (fragmented outliers) mildly.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev.max(0.0);

    // Prefer filling bins when many bins are open (reduce fragmentation).
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * (item_size as f64 / bin_capacity as f64);

    // Early in the stream, be more willing to keep bins balanced; late, pack greedily.
    score += 3.0 * (1.0 - progress) * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln() };
        let poor_fit = post_residual as f64 > (bin_capacity as f64 - item_size as f64) * 0.5;
        if fitting_bins_count > 0 && !poor_fit {
            score += 40.0 + 15.0 * scarcity;
        } else {
            // Opening a fresh bin is neutral-to-good when fits are scarce.
            score -= 5.0 - 3.0 * scarcity;
        }
        // Late in stream, discourage opening new bins unless necessary.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1)

    // Base: minimize wasted space, with smooth non-linear penalty on tiny residuals
    let mut score = pr as f64;
    score -= 18.0 * x * (1.0 - x); // reward mid-range fits (tight packing)
    score += 30.0 * (1.0 - x) * (1.0 - x) * x; // penalize near-zero dead space quadratically

    // Progress coupling: later in stream, prefer tighter fits more aggressively
    let tight_bias = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= tight_bias * 10.0 * x * x; // favor small residuals as stream matures
    score += progress * 6.0 * x; // late stream: keep some slack for future items

    // Lookahead: if next item fits in post-residual, reward strongly (smooth)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit = ((x - nx) * 10.0).tanh(); // smooth sign of "next fits"
        score -= 12.0 * fit.max(0.0) * (1.0 - nx);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Many open bins: discourage spreading; few bins: encourage consolidation
    let density = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += density * 8.0 * (x - mean_residual / cap).abs();

    // New-bin candidate: make it attractive only when fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = (x - 0.5).abs(); // item leaves huge or tiny residual
        score = 40.0 + 30.0 * poor_fit - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: smaller post_residual preferred (already base term).

    // Harmonic class of post_residual: residues mod 10 create dead-space classes.
    let r = post_residual % 10;
    let dead_penalty = match r {
        0 => -12.0, // perfectly reusable class
        1 | 2 => 4.0, // nearly useless slivers
        3..=7 => 1.5,
        8 | 9 => 5.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Reward exact fills
    if post_residual == 0 {
        score -= 40.0;
    }

    // If next item fits the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 {
        // penalize leaving a gap the next item cannot use
        score += 6.0;
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when no open bin gives a good fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin baseline: post_residual = capacity - item_size.
        // Penalize when many bins could fit (fragmentation avoidance).
        score += (fitting_bins_count as f64) * 4.0;
        // Early in stream, opening bins is cheaper; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If mean residual is high, open bins are already fragmented -> new bin ok.
        score -= ((mean_residual - 25.0) * 0.2).clamp(-5.0, 5.0);
    }

    // Prefer bins whose residual deviates from mean in a useful (small) way.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps in the "awkward" band (10..=25) are semi-dead: penalize extra.
    if post_residual >= 10 && post_residual <= 25 {
        score += 12.0 + (25 - post_residual) as f64 * 0.5;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect-fit anticipation: if the lookahead item exactly fills the gap,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If lookahead item fits in the residual, mild reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }
    // If lookahead item cannot fit this residual, penalize (dead space likely).
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new bin is cheaper, so penalize the new-bin candidate.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 5.0 + open_pressure * 2.5;
        // If no open bin fits at all, new bin is necessary: cancel penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, consolidation is preferable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    } else {
        // Reward using existing bins more when many bins are open.
        score -= open_pressure * 0.8;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (i.e., tighter bins) to keep average residual capacity usable.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 && residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else if residual_f > mean_residual {
        score += (residual_f - mean_residual) * 0.2;
    }

    // Waste ratio term: fraction of the bin left empty relative to item size.
    score += (post_residual as f64) / (item_size.max(1) as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot fit here; penalize dead space
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Penalize tiny unusable leftovers (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when it enables a future good fit
    if bin_residual == bin_capacity {
        score += 12.0; // default penalty: prefer filling existing bins
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 25.0; // good pair fits in fresh bin
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest item (1..=100 range, keep general).
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score -= 50.0; // perfect fill
    } else if post_residual > 0 && (post_residual as f64) < 10.0 {
        score += 3.0; // awkward sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // penalize leaving a residual that cannot fit the lookahead item
        score += 4.0;
    }

    // Prefer filling bins that are already relatively empty vs. congested state:
    // when mean residual is high, prioritize consolidating into large-residual bins.
    let dev = (bin_residual as f64) - mean_residual;
    score -= 0.05 * dev;

    // Time horizon: early in stream, allow more openness (favor new bins slightly);
    // late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * (1.0 - progress) * (open_bins_count as f64 / 20.0).min(1.0);

    // New-bin candidate handling: empty bin gets a mild exploration bonus early,
    // but a penalty when open bins fit well (avoid bin explosion).
    if bin_residual == bin_capacity {
        let exploration = 1.0 - progress;
        score += 2.0 - 10.0 * exploration * (fitting_bins_count == 0) as i32 as f64;
        if fitting_bins_count > 0 {
            score += 4.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Small global-load coupling: many open bins -> discourage spreading further.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them more.
    let prog_coupling = pr * (progress * progress) * 2.0
        + pr * norm_pr * progress * 1.5;
    score += prog_coupling;

    // Reward tight fits (small relative post_residual) more strongly as stream advances
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize dead space that cannot fit the next item (smooth gate via lookahead)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += gap * (0.5 + progress);
        // Reward reserving space for next item
        let reserve = (pr - next_item_size as f64).max(0.0);
        score -= reserve * 0.3;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Mild penalty when many bins are open relative to progress (encourage consolidation)
    score += open_bins_count as f64 * (0.5 + 1.0 * progress);

    // Prefer bins below mean residual slightly (balance load smoothly)
    score += (mean_residual - pr) * 0.2;

    // New-bin candidate: make it unattractive unless post_residual is large (nothing better)
    if bin_residual == bin_capacity {
        score += 60.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of common
    // item sizes (10,20,25,50) are "usable" classes; odd/wasteful residues
    // are penalized.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -40.0 // perfect closure is ideal
    } else if pr <= 10 {
        12.0 // tiny dead space, mostly unusable
    } else if pr % 10 == 0 || pr % 25 == 0 {
        -15.0 // aligns with common size classes
    } else if pr % 5 == 0 {
        -6.0
    } else {
        5.0 // irregular residue
    };
    score += harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // next item fits but leaves another residue: mild reward scaled
            // by how well it subdivides the leftover
            let nxt_post = pr - next_item_size;
            if nxt_post % 10 == 0 { score -= 10.0; } else { score -= 3.0; }
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += (next_item_size as f64 - pr as f64).min(30.0) * 0.3;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the item is large or no open bin fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for big items (they'd wreck open bins' flexibility)
        score -= 20.0 * large_item;
        // Prefer reusing open bins when many are open with slack
        score += (open_bins_count as f64) * 1.5 + mean_residual * 0.2;
        // Early in the stream, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer tighter bins overall (small residual before placement = good packing)
    score += (bin_residual as f64 / bin_capacity as f64) * 4.0;

    // Slight penalty for fragmenting across too many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that no plausible item (1..=100) can use
    // are only "wasted" if they are tiny and unattractive; small gaps (< 20)
    // are almost unusable given typical item sizes, so penalize them extra.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 3.0;
    }

    // Reward tight fits (post_residual near zero but not creating a tiny gap).
    if post_residual == 0 {
        score -= 40.0; // perfect fit: best possible outcome
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when several are open,
    // making the new-bin candidate (residual == capacity) less attractive.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 10.0 + (open_bins_count as f64) * 4.0;
        // If the next item could combine well with the current one in a fresh
        // bin, slightly favor the new bin.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            let combo = (item_size + next_item_size) as f64;
            if (bin_capacity as f64 - combo) < 15.0 {
                score -= 20.0;
            }
        }
    } else {
        // Placing into an existing bin: reward keeping bin count low.
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Partial fit lookahead: mild reward proportional to how well it fits.
        score -= 10.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize leaving a gap that
        // blocks the known next item.
        score += 8.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "leftover" bin; using it up is good (cleans up fragmented bins).
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    }

    // Late-stream pressure: as the stream progresses, prefer filling existing
    // bins to avoid leaving many partially-filled bins at the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild quadratic penalty on waste.
    score += 0.02 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= next {
            let gap = pr - next;
            // Perfect chain fit: subtract a large bonus scaled by tightness.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // Extra reward for exact match.
            if gap < 1.0 {
                score -= 20.0;
            }
        } else {
            // Next item cannot fit here; penalize slightly to prefer bins
            // that leave usable residue for the lookahead item.
            score += 8.0 * (next - pr) / bin_capacity as f64;
        }
    } else {
        // Last item: just minimize waste.
        score += 5.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // "almost full" -> finishing them off is good; penalize using spacious bins
    // when mean residual is large.
    let pr = post_residual as f64;
    let dev = pr - mean_residual;
    score += 0.15 * dev;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual == 0 {
            score -= 10.0; // perfect closure under pressure
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; grows with number of open bins
        // to discourage bin proliferation, shrinks late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 0.45 * bin_capacity as f64
            + 3.0 * open_bins_count as f64
            - 10.0 * progress
            + (next_item_size as f64 - bin_capacity as f64).max(0.0) * 0.5;
        // If item is large relative to capacity, new bin is more acceptable.
        score -= 0.2 * item_size as f64;
    }

    // Small tie-breaker: prefer bins with larger current residual consumed
    // (keeps small-residual bins available for small items).
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.5;

    // Reward tight fits (small post residual relative to capacity)
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * 30.0;

    // Penalize dead space that likely can't be reused by next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post > 0.0 && post < nx {
            score += (nx - post) * 2.0; // next item won't fit here
        } else if post >= nx {
            score -= 6.0; // chain placement possible
        }
        // perfect pair: item + next exactly fills bin
        if post == nx as f64 {
            score -= 25.0;
        }
    } else {
        // last item: prefer fullest bin
        score -= 20.0 * tightness;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly unless current fit is bad or many bins open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = post / cap; // for empty bin, post = cap - item
        let mut penalty = 15.0 + 20.0 * (1.0 - fit_quality);
        if fitting_bins_count == 0 {
            penalty -= 60.0; // must open
        }
        // late in stream, prefer consolidating into open bins
        penalty += progress * 10.0;
        // many open bins with slack: discourage new bin
        penalty += (open_bins_count as f64) * (mean_residual / cap) * 5.0;
        score += penalty;
    }

    // Mild preference for bins below mean residual (balance load) early on
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - bin_residual as f64) * 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer bins with small post_residual (tight fits);
    // later, allow slightly larger residuals to avoid opening bins.
    let tightness = 1.0 - progress;
    score += tightness * (pr * pr) / cap;

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + progress);
        } else {
            score -= (pr - nxt).min(20.0) * 0.3;
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Slight penalty for new-bin candidate unless residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs() / cap;
        score += 8.0 - 6.0 * fragmentation;
    }

    // Mild preference for bins with residuals below the mean (compact usage).
    score += 0.2 * (pr - mean_residual);

    // Small reward for larger items placed into already-open bins.
    score -= 0.05 * item_size as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 (dead-space bands).
    let band = post_residual % 10;
    // Residues 1..9 are "dead" fragments (few items of size 1..9 exist); 0 is perfect.
    score -= match band {
        0 => 25.0,
        10 => 0.0,
        _ => {
            // Penalize small unusable fragments more as they shrink.
            let b = band as f64;
            12.0 * (11.0 - b) / 10.0
        }
    };

    // Integer-division threshold classes on post_residual (capacity fractions).
    let quarter = bin_capacity / 4;      // 25
    let half = bin_capacity / 2;         // 50
    let post = post_residual as u32;
    if post == 0 {
        score -= 30.0; // perfect fit, always excellent
    } else if post < 10 {
        // Fragment smaller than any item: total dead space.
        score += 20.0;
    } else if post <= quarter {
        score += 4.0;
    } else if post <= half {
        score -= 6.0;
    } else {
        score -= 2.0;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 22.0; // chain a perfect follow-up fit
        } else if next_item_size < post {
            let gap = post - next_item_size;
            // Reward closeness; harmonic class of the resulting gap.
            score -= 10.0 * (1.0 - gap as f64 / post as f64);
            if gap % 10 == 0 { score -= 5.0; }
        } else {
            // Next item cannot use this bin's remainder: penalize if we leave a big gap.
            score += (post as f64) * 0.15;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0;
    }

    // Slight preference for consolidating when many bins are open.
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins tighter than average (best-fit refinement).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Early stream: be more open to new bins; late stream: pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only if current fit is poor.
        let waste = post as f64;
        score = 40.0 + waste - 10.0 * progress;
        if next_item_size > 0 && next_item_size <= post {
            score -= 15.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable gap
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 15.0; // marginal gap, only fits the smallest items
    }

    // Reward tight fits (perfect packing).
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // fractional tightness reward
        score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powf(2.0));
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if fit elsewhere would leave bad dead space
        // or no open bin fits well.
        score = bin_capacity as f64 - 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 90.0; // keep the last-chance bin alive
        }
        score += open_bins_count as f64 * 2.0;
    } else {
        // Prefer bins whose residual is close to item_size (minimize waste relative to mean).
        score += 0.5 * (mean_residual - bin_residual as f64).abs();
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 25.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 10.0; // next item can't use this residual anyway
    }

    // Mild stream-progression term: tighten packing as the stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 150.0;
        } else if (post_residual as f64 - next).abs() <= 5.0 {
