        }
        // Penalize leaving residual too small for the next item (dead space).
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 40.0 * (1.0 - post_residual as f64 / next.max(1.0));
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But allow new bin if next item is large and would leave dead space here.
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
            score -= 100.0;
        }
    }

    // Late in stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 1.0)) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: squared post-residual punishes dead space super-linearly.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Fill ratio reward: bins that become fuller get priority.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Lookahead: penalize leaving residual that cannot fit the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 4.0; // residual remains useful
            // Extra reward if next item fits almost exactly in post_residual.
            let lookahead_fit = (pr - ni) / bin_capacity as f64;
            score -= 10.0 * (1.0 - lookahead_fit).max(0.0) * (ni / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize proportionally.
            score += 0.5 * (ni - pr);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: open a fresh bin only when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 30.0;
        // Cheaper to open new bins early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If many bins are open with slack, discourage adding another.
        score += 1.5 * open_bins_count as f64;
        // If mean residual across open bins is large, discourage new bin.
        score += 0.3 * mean_residual;
        // Large items prefer fresh bins (less fragmentation risk).
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // Slight preference to reuse existing bins as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress;
    }

    // Coupling: when mean residual is high, prioritize bins below-average residual
    // (consolidate slack) — i.e., penalize bins that are unusually roomy.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress * (1.0 - progress) * 4.0; // peaks at 0.5, smooth in [0,1]
    score += norm_pr * norm_pr * 40.0 * (1.0 - t);
    score -= (norm_pr * (1.0 - norm_pr)) * 25.0 * t;

    // Reward tight fits, stronger late in the stream
    let fit_quality = 1.0 - norm_pr;
    score -= fit_quality * fit_quality * (1.0 + progress) * 10.0;

    // Penalize dead space that can't hold the next item
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        let waste = nxt - pr;
        if waste > 0.0 {
            score += (waste / cap) * 30.0 * (0.5 + progress);
        } else {
            score -= 5.0;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across too many open bins
    score += (open_bins_count as f64) * 0.3 * norm_pr;
    score += (mean_residual - pr).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fits (class 0) are gold.
    let class = post_residual % 10;
    match class {
        0 => score -= 30.0,
        1 | 2 | 3 => score += 6.0,   // tiny dead space is nearly unusable
        4 | 5 | 6 => score -= 4.0,   // mid-range leftovers still usable
        _ => score += 2.0,
    }

    // Integer-division threshold: residual buckets of capacity/4.
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 8.0; // near-full bin: fine, but don't over-reward
    } else if post_residual <= 2 * quarter {
        score -= 6.0; // half-full bin: good target
    }

    // Lookahead coupling: if next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // harmonic bonus if next item leaves another class-0 residual
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot follow in this bin: slight penalty for tight fit chains
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor (large post_residual
    // relative to capacity) or bin is genuinely fresh.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.35 * bin_capacity as f64;
        if poor_fit {
            score -= 20.0;
        } else {
            score += 35.0; // keep filling partially-used bins when fit is decent
        }
    }

    // Stream progression: early on, be greedy for tight fits; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (mean_residual - post_residual as f64) * 0.15;
    score += progress * open_bins_count as f64 * 0.5;

    // Mean residual coupling: avoid dumping into bins far from the mean unless tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    let pr = post_residual;
    if pr > 0 {
        // Dead space below half capacity is highly penalized (unusable gap).
        if pr < bin_capacity / 2 {
            score += 25.0 * (1.0 - pr as f64 / (bin_capacity as f64 / 2.0));
        }
        // Perfect fit gets a strong bonus.
        if pr == 0 {
            score -= 40.0;
        }
    }

    // Reward bins that can also host the lookahead item (chain fitting).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + next_item_size as f64 * 0.05;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leaving a gap that neither fits the next item nor is reusable.
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bins pressure: when many bins are open, favor filling existing ones
    // over opening new bins (penalize the fresh-bin candidate implicitly).
    score += open_bins_count as f64 * 0.35;

    // Prefer bins with below-mean residual (tighter bins) to consolidate space.
    score += (mean_residual - bin_residual as f64) * 0.10;

    // Early in the stream, be slightly more willing to open bins (better packing
    // structure later); later, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0;

    // Penalize the brand-new bin candidate mildly unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 5.0 + item_size as f64 * 0.10;
        // If the item would leave a large dead space in any bin, new bin is fine.
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 60.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits after this placement -> strong reward
            score -= 45.0;
            // Extra reward proportional to how well next item fills the remaining space
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= next_fill * 25.0;
        } else {
            // Next item won't fit -> penalize, scaled by how close the miss is
            let gap = (next_item_size - post_residual) as f64;
            let gap_frac = gap / bin_capacity as f64;
            score += gap_frac * 40.0;
            // If post_residual is small dead space anyway, slightly forgive
            if post_residual < 10 {
                score -= 10.0;
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize creating tiny unusable slivers (<10) unless it's the last fitting bin
    if post_residual > 0 && post_residual < 10 && fitting_bins_count > 1 {
        score += 30.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 80.0;
    }

    // New-bin candidate handling: discourage opening a new bin when good fits exist,
    // but allow it when open bins are nearly full and the item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open_fill = bin_capacity as f64 - mean_residual;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Open a new bin if existing bins are congested or item is large
        if avg_open_fill > 0.6 * bin_capacity as f64 || item_frac > 0.7 {
            score -= 20.0 + 30.0 * progress;
        } else {
            score += 40.0;
        }
        // Lookahead: a fresh bin can always host the next item too
        if next_item_size > 0 {
            score -= 15.0;
        }
    }

    // Mild pressure to consolidate as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize leaving dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty for blocking chain packing
            score += 5.0;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer the tightest among many; relative tiebreak
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Time horizon: late in the stream, consolidate aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.3 * progress;

    // Bin balancing: prefer bins with residuals near the mean when residuals are large
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // New-bin candidate: prefer opening a new bin only when item is large
    // relative to residual of existing bins (i.e., poor fit everywhere).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is attractive for large items or when many bins exist
        // with scattered residuals; discourage early-stream new bins for small items.
        let openness = fill_ratio * 60.0
            + progress * 20.0
            + (open_bins_count as f64).ln().max(0.0) * 3.0;
        score = openness + post_residual as f64;
        // If next item is small, a fresh bin can host both — mild discount
        if next_item_size > 0 && next_item_size <= post_residual.saturating_sub(item_size).max(0) {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: penalize leftover space, with non-linear polynomial coupling to progress.
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.8 * progress * progress + 0.6 * (1.0 - progress));

    // Smooth convex penalty on normalized dead space (quartic coupling).
    score += 20.0 * norm_post * norm_post * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits: post_residual near zero is excellent.
    let tightness = 1.0 - norm_post;
    score -= 15.0 * tightness * tightness * (1.0 + progress);

    // If the next item would fit exactly into the post-residual, reward strongly (smooth kernel).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        let kernel = (-gap * gap / 50.0).exp();
        score -= 12.0 * kernel;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Penalize bins far from mean residual (prefer homogeneity), smooth quadratic coupling.
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / (1.0 + progress);

    // New empty bin candidate: baseline cost of opening a bin, decreasing with progress
    // (late in the stream, consolidating is more valuable than new bins).
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress) * (1.0 - progress);
        // But if the item is large and fills most of a fresh bin, that's attractive.
        score -= 20.0 * (item / cap) * (item / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals that are multiples of common small item sizes are reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals lying in harmonic classes (multiples of 10/20/25/50)
    let mut harmonic_bonus = 0.0;
    if post_residual % 10 == 0 { harmonic_bonus += 6.0; }
    if post_residual % 20 == 0 { harmonic_bonus += 4.0; }
    if post_residual % 25 == 0 { harmonic_bonus += 3.0; }
    if post_residual % 50 == 0 { harmonic_bonus += 3.0; }
    score -= harmonic_bonus;

    // Penalize dead space: residuals below the minimum plausible item size
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // partial reward scaled by how much slack remains after next item
            let after2 = post_residual - next_item_size;
            score -= 10.0 + (after2 as f64).min(20.0);
        } else {
            // next item cannot follow in this bin: penalize by overshoot class
            let over = next_item_size - post_residual;
            score += (over as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless
    // no open bin fits well or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        score += 12.0 + 30.0 * (1.0 - progress) - pressure;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (tighter-than-average bins get priority).
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score -= dev * 0.2;
    } else {
        score += (-dev) * 0.1;
    }

    // Integer-division threshold on post_residual: coarse usability tiers
    let tier = post_residual / 15;
    score -= tier as f64 * 1.5;

    // Mild preference for compact bins as stream matures
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (pr / cap) * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).sqrt() * (2.0 + 4.0 * progress);
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: only attractive when current item fits poorly elsewhere
        score += pressure * 0.8;
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Slight preference for bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits but not exact-to-zero waste unless truly exact.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: excellent
    } else if post_residual < 10 {
        score += 15.0; // tiny dead space: hard to reuse, mild penalty
    }

    // 2-step lookahead: strongly reward if the next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain fit: reward proportionally to how snugly next item fills the remainder
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 + 0.5 * slack.max(0.0);
            if slack == 0.0 {
                score -= 25.0; // perfect 2-chain
            }
        } else {
            // next item won't fit here; penalize more if leftover is small (wasted)
            let miss = (next_item_size - post_residual) as f64;
            score += 0.6 * miss;
        }
    }

    // Compare residual against mean residual across open bins: prefer bins that
    // are more filled than average (smaller residual than mean).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Late in the stream, consolidation matters more: penalize spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.05;

    // New-bin candidate: make empty bin moderately attractive only when current
    // fit is very poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        // neutral baseline; slightly penalized so we prefer good existing fits
        score += 5.0;
        if item_size >= 50 {
            score -= 20.0; // large items start fresh bins happily
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale waste non-linearly.
    let waste = post_residual as f64;
    score += 0.35 * (waste * waste) / bin_capacity as f64;

    // Reward leaving residuals that match the next item (lookahead k=2).
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 1.5
        };
        score += 0.4 * gap;
        // Bonus if next item fits exactly after placement.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else {
        // Last item: pure waste minimization.
        score += 0.2 * waste;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.05 * item_size as f64;
    }

    // Penalize opening new bins when many bins are already open and mean residual is high.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open = (mean_residual + open_bins_count as f64 * 0.5) / (open_bins_count.max(1) as f64 + 1.0);
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 6.0 + 10.0 * crowding + 5.0 * (1.0 - progress) + 0.05 * avg_open;
        // New bin is acceptable if current item is large and no small residual could hold it well.
        if item_size >= 60 && post_residual < 40 {
            score -= 9.0;
        }
    }

    // Mild preference for fuller bins relative to the fleet mean residual.
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Penalize creating residuals that are hard to fill (small odd slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    let mut score = post;

    // Smooth non-linear penalty for dead space: cubic in normalized post-residual
    score += 6.0 * post_norm * post_norm * post_norm * cap;

    // Polynomial coupling with stream progress: later in the stream, punish residual waste more
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress);
    score += 12.0 * progress_coupling * post_norm * post_norm * cap;

    // Reward tight fits: subtract a smooth bump centered at post_residual == 0
    let tightness = (-post_norm * 4.0).exp();
    score -= 8.0 * tightness * (1.0 + progress_coupling);

    // Lookahead: reward bins whose post-residual fits the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_quality = 1.0 - ((post - nxt) / cap).powi(2);
            score -= 5.0 * fit_quality * (1.0 + 0.5 * progress);
        } else {
            // smooth penalty proportional to gap, non-linear in progress
            let gap = (nxt - post) / cap;
            score += 4.0 * gap * gap * cap * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 + progress);
    }

    // Slight preference for bins with residual far below mean (consolidating waste)
    let mean_norm = mean_residual / cap;
    let residual_norm = bin_residual as f64 / cap;
    score += 3.0 * (residual_norm - mean_norm).powi(2) * (1.0 - progress_coupling);

    // New-bin candidate: make empty-bin score depend smoothly on stream progress and open bins
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln().max(0.0);
        score = cap * (1.0 + 0.35 * progress_coupling + 0.05 * crowding) + 4.0 * post_norm * cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (multiples of small divisors) are more valuable.
    let r = post_residual;
    let class_bonus = if r == 0 {
        -40.0 // perfect closure
    } else if r % 10 == 0 {
        -12.0
    } else if r % 5 == 0 {
        -6.0
    } else if r % 3 == 0 {
        -2.0
    } else {
        4.0 // awkward leftover
    };
    score += class_bonus;

    // Dead-space penalty: leftovers too small for the smallest plausible item.
    if r > 0 && r < 10 {
        score += 25.0;
    } else if r >= 10 && r < 20 {
        score += 6.0;
    }

    // Lookahead coupling: does next_item_size harmonically fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            let slack = r - next_item_size;
            score -= 10.0 - (slack as f64).min(20.0) * 0.3;
            if (r % next_item_size.max(1)) == 0 {
                score -= 5.0; // exact harmonic division
            }
        } else {
            score += 3.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: prefer keeping it closed unless open bins are crowded.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0
            + (mean_residual / bin_capacity as f64) * 10.0;
        if r == bin_capacity {
            score += 5.0; // discourage premature new bins when a fit exists
        }
    }

    // Tight-fit reward relative to capacity fractions.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    // Late-stream consolidation: as the stream ends, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - item_size) as f64 * 0.05;

    // Mean-residual coupling: if open bins are generally slack, punish waste more.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A residual gap is "unusable" if it is too small to hold even the
    // smallest plausible item (<= 10) or cannot fit the lookahead item.
    if post_residual > 0 && post_residual < 10 {
        score += 400.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 150.0;
    }

    // Reward bins whose post-residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
    }

    // Open-bin pressure: mildly discourage opening new bins.
    score += open_bins_count as f64 * 5.0;

    // Last-chance bonus: if this is the only fitting bin, prefer it
    // over opening a new bin to avoid proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: give it a baseline disadvantage so it is only
    // chosen when open bins would create heavy dead space.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Late in the stream, opening new bins is slightly cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * progress;
    }

    // Prefer tighter bins overall (small residual before placement).
    score += bin_residual as f64 * 0.3;

    // Slight preference for bins below mean residual (tighter than average).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) when post_residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // next item fits; reward proportionally to how well it uses the leftover
            let fill = (next_item_size as f64) / (post_residual as f64);
            score -= 20.0 * fill;
        } else {
            // next item does NOT fit here; penalize leaving awkward dead space
            let waste = (post_residual as f64) / (next_item_size as f64);
            score += 8.0 * waste;
            if post_residual < 10 {
                score += 5.0; // tiny unusable sliver
            }
        }
    } else {
        // last item: only tightness matters
        score -= 5.0 * tightness;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64) / mean_residual;
        if rel < 1.0 {
            score -= 6.0 * (1.0 - rel); // below-average residual => tighter bin, favor
        } else {
            score += 4.0 * (rel - 1.0); // above-average residual => loose bin, penalize
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive for very large items or poor fits elsewhere.
    if bin_residual == bin_capacity {
        // neutral base; add penalty that shrinks for large items
        let large = (item_size as f64) / (bin_capacity as f64);
        score += 10.0 - 8.0 * large;
        // if lookahead suggests a good chain into a fresh bin, ease the penalty
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity && next_item_size + item_size <= bin_capacity {
            score -= 6.0;
        }
    }

    // Mild stream-progression pressure: later in stream, prefer consolidating into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 4.0 * progress;
    }

    // Slight preference for keeping number of open bins low.
    if bin_residual != bin_capacity {
        score -= 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (post_residual that likely can't host future items).
    let tiny = (post_residual as f64).powf(0.6);
    if post_residual > 0 {
        score += 2.0 * tiny;
    }

    // Reward tight fits (wasting little space).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio;

    // Lookahead: strongly favor bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0; // dead-ends the next item
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: as the stream progresses, be more conservative (favor filling existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with low mean residual -> discourage new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins exist and mean residual is healthy.
        let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let healthy = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 10.0 * open_pressure * (0.5 + healthy);
        // But a new bin is fine early on or when the item is huge and fits nothing well.
        if item_size > 70 {
            score -= 6.0;
        }
    } else {
        // Filling existing bins: slight bonus scaled by how much residual remains vs mean.
        score -= 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Mild preference for bins with moderate residual (avoid fragmenting near-full bins).
    score += 0.05 * ((post_residual as f64) - (bin_capacity as f64 * 0.5)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer small post-residual, scaled non-linearly.
    let mut score = pr * (1.0 + 0.35 * progress * (pr / cap));

    // Polynomial coupling: post_residual vs item size interaction.
    let x = pr / cap;
    let y = it / cap;
    score += 12.0 * (x - 0.5) * (x - 0.5) * (y - 0.5) * (y - 0.5) * 4.0;

    // Dead-space penalty: post-residual that is too small to hold typical items.
    let min_size = 1.0;
    if pr < min_size {
        score -= 50.0; // perfect fit reward
    } else if pr < 10.0 {
        score += 2.0 * (10.0 - pr); // small unusable-ish gap penalty
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 1.0 {
            score -= 30.0;
        } else if nxt <= pr {
            score -= 8.0 * (nxt / pr);
        } else {
            score += 4.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Smooth preference for tighter bins relative to mean residual.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev - 4.0 * dev;

    // New-bin candidate handling: empty bin starts from a neutral-high baseline,
    // but becomes attractive late in the stream or when few bins fit the item.
    if bin_residual == bin_capacity {
        score = cap - it as f64 + 5.0;
        score -= 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Avoid spawning bins when existing bins are mostly empty.
        score += 3.0 * (mean_residual / cap);
    }

    // Mild congestion term: many open bins -> prefer filling existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality classes
    // Class 0: post_residual == 0 (perfect fit) -> strong reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Class 1: tiny dead space (<= 5) -> very good, near-perfect
    if post_residual > 0 && post_residual <= 5 {
        score -= 40.0;
    }

    // Class 2: awkward zone 6..=15 -> dead space likely unusable for min items (1..100)
    // Penalize modulo structure: residuals that are small but nonzero are worst.
    if post_residual >= 6 && post_residual <= 15 {
        score += 25.0;
    }

    // Harmonic fraction of the bin used: integer division thresholds on item_size
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50
    if item_size > half {
        // Large item: filling a bin with a big item is valuable, reward
        score -= 20.0;
    } else if item_size > quarter {
        // Medium item: neutral, slight coupling with residual class
        score += (post_residual as f64) * 0.05;
    } else {
        // Small item: prefer dumping into bins with large residuals to consolidate
        if post_residual >= half {
            score -= 10.0;
        }
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // sizes (10, 20, 25) are "harmonic" and reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        if post_residual % 25 == 0 {
            score -= 6.0;
        }
        if post_residual % 20 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 50.0;
        } else {
            score -= 12.0;
        }
    }
    // If next item does NOT fit here, penalize slightly (this bin becomes dead for next step)
    if next_item_size > post_residual {
        score += 6.0;
    }

    // Last-chance logic: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are bad (large post_residual waste or no real fit).
    if bin_residual == bin_capacity {
        // Base cost of opening a bin: high, so only chosen when needed
        score += 40.0;
        // If stream is early, opening bins is fine (spread items)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If many bins are open and mean residual is high, prefer reusing: raise new-bin cost
        score += (open_bins_count as f64).min(20.0) * 1.5;
        score += mean_residual * 0.3;
        // If next item is huge and current item is small, new bin can host both later
        if next_item_size >= half && item_size <= quarter {
            score -= 15.0;
        }
    }

    // Prefer tighter bins generally: scale by fraction of bin filled by this placement
    let fill_fraction = item_size as f64 / bin_capacity as f64;
    score -= fill_fraction * 15.0;

    // Mild penalty proportional to open bins to encourage consolidation
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward filling a bin deeply relative to capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
