        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would be blocked by tiny dead space, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (10.0 - post_residual as f64).max(0.0);
    }

    // Late in stream: tighten packing, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    // Prefer bins with below-mean residual (consolidate emptier bins' usage).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

