    }

    // Penalize large post_residual (wasted space), nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Early in stream: be more willing to open bins (favor tightness later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // New-bin candidate: only attractive when item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 45.0 - 40.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

