            score -= 8.0;
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when open bins are crowded (low mean residual) or few fit the item.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64; // 0..1, low = crowded
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 40.0
            - 30.0 * (1.0 - crowded)
            - 20.0 * scarcity
            - 10.0 * progress;
        score += new_bin_penalty.max(-5.0);
    } else {
        // Mildly discourage scattering across many open bins when mean residual is high.
        score += 0.05 * mean_residual / (open_bins_count as f64 + 1.0);
    }

    // Slight preference for fuller bins (larger item relative to residual).
    score -= 0.1 * (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    let coupling = norm_pr * norm_pr * (1.0 - t) + norm_pr * t * t;
    score += 8.0 * coupling;

    // Penalize large dead space more than linearly when few bins can fit the item
    let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
    score += 6.0 * norm_pr * scarcity;

    // Reward tight fits (small post residual) especially near end of stream
    score -= 4.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * t);

    // Penalize wasting a nearly-full bin when the next item could use its space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 3.0 * (nxt / cap) * (1.0 - norm_pr);
        } else {
            score += 2.0 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty for leaving residual far from mean residual (imbalance)
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead space bands"
    let mod_class = post_residual % 10;
    if mod_class != 0 && post_residual > 0 {
        // penalize residuals that are awkward (not multiples of 10, likely unusable)
        score += (10 - mod_class) as f64 * 0.8;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small residual band: 1..=10 is nearly dead space; penalize unless it's zero
    if post_residual > 0 && post_residual <= 10 {
        score += 15.0;
    }

    // Next-item lookahead: if next item exactly fits post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = post_residual - next_item_size;
        if next_fit_gap == 0 {
            score -= 35.0;
        } else if next_fit_gap <= 10 {
            score -= 20.0;
        } else {
            // harmonic coupling: reward proportional to how much of next item fits
            score -= (next_item_size as f64) * 0.15;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot fit here; penalize wasting this bin's remaining space
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we prefer
    // reusing open bins unless they fit poorly
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5;
        // early in stream, opening bins is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Integer-division threshold: bins whose residual is in the "half-full" class
    // (residual / capacity >= 0.5) are valuable, keep them flexible
    let half = bin_capacity / 2;
    if bin_residual >= half {
        score += 5.0; // don't burn large-residual bins on small items
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's a good filler
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but dead space in the
    // "unusable gap" band (0 < post_residual < 10) is worse than a clean
    // near-zero residual, so add a quadratic penalty there.
    let pr = post_residual as f64;
    if pr > 0.0 && post_residual < 10 {
        score += (10.0 - pr) * 2.5; // dead-space penalty for tiny unusable gaps
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual < 40 {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    // over opening new bins (new-bin candidate has full residual = capacity).
    score += open_bins_count as f64 * 1.5;

    // If the next item fits in the post-residual, this placement chains well.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leaving a gap that the next item cannot use is wasted space.
        score += (post_residual as f64) * 0.5;
    }

    // Progress-aware scaling: early in the stream keep bins flexible
    // (slightly penalize very low residuals to preserve large gaps),
    // later in the stream allow aggressive compaction.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.5 && post_residual > 0 && post_residual < 20 {
        score += (20.0 - pr) * 0.8 * (1.0 - progress);
    }

    // Relative fit quality: reward item using most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Mean-residual coupling: if this bin's residual is far below average,
    // it is already "compressed" — finishing it off is cheap for the pool.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    }

    // New-bin candidate (full bin) should only win when fits are awful:
    // penalize the empty-bin candidate moderately.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits into the leftover space: strong reward, scaled by tightness
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 / (1.0 + slack * 0.05);
    }
    // Next item does NOT fit: penalize wasted dead space, worse when it's small
    else if next_item_size > 0 {
        let dead = post_residual as f64;
        score += dead * 0.8 + 30.0;
    }

    // Small leftover space that likely becomes unusable: penalize gently
    if post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Compare residual to mean residual: prefer bins with below-average residual
    // (tighter bins get filled first, keeping large residuals available)
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: penalize mildly so open bins are preferred,
    // but relax the penalty late in the stream or when many bins are open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = (open_bins_count as f64 * 0.5).min(50.0);
        score += 120.0 - 40.0 * progress + crowd;
    }

    // Slight preference for filling tighter bins overall
    score += (bin_capacity - bin_residual) as f64 * -0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post residual too small for the smallest plausible item (1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer existing bins unless this is a great fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0;
        // If item fits perfectly in a fresh bin, opening is attractive
        if item_size == bin_capacity {
            score -= 100.0;
        }
        // Late in the stream, opening new bins is less costly than wasting space
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    }

    // Lookahead: if next item could use the post residual, reward leaving useful space
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && next_item_size > bin_residual {
            // next item can't fit here anyway; leftover space is dead weight
            score += 5.0;
        }
        // Exact pairing: post_residual equals next item size is ideal
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // Global residual pressure: many open bins with large mean residual -> consolidate
    if !is_new_bin {
        let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln_1p();
        score -= 4.0 * pressure;
    }

    // Mild penalty for very loose fits when many bins are open
    if post_residual as f64 > mean_residual && open_bins_count > 2 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth polynomial coupling with stream progress: early on, keep bins
    // flexible (penalize very low residuals slightly more), later, pack tight.
    let flexibility = norm_post * (1.0 - norm_post);
    score += 12.0 * flexibility * (0.5 - progress);

    // Reward filling a bin nearly completely, stronger later in the stream.
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (10.0 + 15.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Dead-space penalty: residual too small to be useful for typical items.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 2.0;
    }

    // Lookahead: reward residuals that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - (nxt / cap)) * (1.0 - progress);
        } else if post > 0.0 {
            score += 4.0 * (1.0 - post / nxt);
        }
    }

    // Mild dispersion penalty: avoid bins far from mean residual state.
    score += 0.05 * (post - mean_residual).abs();

    // Slight preference to reuse existing bins over opening new ones.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity-fraction buckets
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;
    let post_class: f64 = if post == 0 {
        -40.0 // perfect fit, strongly reward
    } else if post < eighth {
        60.0 // dead space: unusable sliver
    } else if post % quarter <= eighth {
        -25.0 // post_residual harmonically aligned with quarter classes
    } else if post < quarter {
        35.0
    } else {
        0.0
    };
    score += post_class;

    // Integer-division threshold on post_residual vs next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // does leftover accommodate the lookahead item?
            let slack = post_residual - next_item_size;
            score -= (slack as f64) * 0.6;
            // harmonic bonus if slack lands on a small class
            if slack % eighth == 0 && slack > 0 {
                score -= 10.0;
            }
        } else {
            // leftover too small for next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    } else {
        // last item: just fill as much as possible
        score -= 20.0;
    }

    // Last-chance bin: if only this bin fits, avoid opening a new bin unless fit is terrible
    if fitting_bins_count == 1 && post_residual < eighth {
        score -= 45.0;
    } else if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New empty bin candidate: penalize mildly, but allow it when current bin would leave
    // large misaligned dead space or when many bins are open with high mean residual
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 40.0 * progress;
        if post_class > 20.0 {
            score -= 25.0; // opening fresh bin beats creating dead space
        }
        if mean_residual > cap * 0.5 && open_bins_count > 2 {
            score -= 10.0; // spread load when residuals are high
        }
    }

    // Prefer tighter bins overall
    score += (bin_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item are wasted.
    if post_residual < 10 {
        score -= 60.0; // perfect or near-perfect fill — highly desirable
    } else if post_residual < 20 {
        score += 35.0; // dead gap: nothing (min size 10) may fit reliably
    } else if post_residual < 30 {
        score += 12.0; // marginal gap: only tiny items can use it
    }

    // Reward tight fits proportionally (waste ratio).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Lookahead: if the next item fits exactly in the post-residual, this chain is great.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot follow here; a large leftover is more painful
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are small relative to the item.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / mean_residual.max(1.0);
        // base cost of a fresh bin, discounted when open bins are congested
        score += 70.0 - 45.0 * pressure.min(1.5);
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Mild open-bin pressure: prefer consolidating into fewer bins when many are open.
    score += 0.4 * open_bins_count as f64 * (1.0 - tightness);

    // Late-stream consolidation: as the stream progresses, avoid spreading items.
    let progress = step_index as f64 / total_items as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already favors this).

    // Aggressive 2-step lookahead: reward bins where the next item fits
    // the post residual exactly or nearly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = post_residual as f64 - nxt;
            // Subtract more when next item fits snugly into leftover space.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 40.0; // perfect chaining bonus
            }
        } else {
            // Next item cannot fit in the leftover: penalize dead space
            // proportional to how unusable it is.
            let dead = nxt - post_residual as f64;
            score += 0.5 * dead.min(50.0);
        }
    } else {
        // Last item: just minimize waste.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean residual: prefer bins with residual below mean
    // (compact bins) to preserve large-residual bins for larger future items.
    score += 0.8 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // and no good fit exists (empty bin has post_residual == capacity - item).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 35.0;
        // If item is large, opening a fresh bin is more acceptable.
        score -= 0.2 * item_size as f64;
        // If few bins fit the item, new bin becomes more attractive.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Late in the stream, avoid spawning bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Slight penalty for leaving residuals below the smallest item size
    // (unusable dead space), since items are >= 1 but small residuals waste.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in post_residual).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 30.0 * tight * tight;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize if next item cannot fit in post_residual,
    // reward if next item fits exactly-ish.
    if next_item_size > 0 {
        if (next_item_size as u32) > post_residual {
            score += 8.0;
        } else {
            let gap = post_residual as f64 - next_item_size as f64;
            score -= 6.0 * (1.0 - gap / (bin_capacity as f64));
        }
    }

    // Prefer bins whose residual deviates from the mean (consolidate extremes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Mild preference for fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - tight);

    // Penalize opening new bins when many bins are already open and one fits.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 10.0 + 15.0 * progress + 0.5 * open_bins_count as f64;
        score += new_bin_penalty;
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 4.0; // fresh bin is fine if next item also fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping.
    // Favor tight fits strongly: quadratic and quartic terms in normalized post_residual.
    let mut score = pr
        + 60.0 * norm_pr * norm_pr
        + 90.0 * norm_pr * norm_pr * norm_pr * norm_pr;

    // Smooth stream-progress coupling: later in the stream, dead space matters more.
    let p2 = progress * progress;
    score *= 1.0 + 0.8 * p2 * norm_pr;

    // Penalize large residuals relative to mean residual (wasted space vs. fleet average).
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual smoothly,
    // penalize if post-residual is awkwardly close-but-too-small for next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - (pr - nxt) / cap);
        } else {
            let gap = (nxt - pr) / cap;
            score += 25.0 * gap * gap;
        }
    }

    // New-bin candidate: neutral-ish baseline; only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decreasing slightly with stream progress
        // (early waste is more costly over the remaining stream).
        score = cap * (1.2 - 0.3 * progress) + 0.3 * mean_residual;
        if fitting_bins_count == 0 {
            // No open bin fits: opening a new bin is necessary.
            score -= cap;
        } else if fitting_bins_count == 1 && pr >= 0.0 {
            // A lone fitting bin exists; only open new bin if that fit is terrible.
            // (Handled implicitly: fitting bin gets -40 bonus, so new bin rarely wins.)
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual mod 10 defines
    // "dead-space classes". Residuals that are multiples of 10 are the most
    // reusable (items are multiples of 10 in the classic regime), so reward them.
    let post_mod = post_residual % 10;
    let harm_bonus: f64 = match post_mod {
        0 => 14.0,
        1 | 9 => 2.0,
        2 | 8 => 3.5,
        3 | 7 => 4.5,
        4 | 6 => 5.5,
        _ => 6.5,
    };
    score -= harm_bonus;

    // Integer-division thresholds: how many size-10 slots fit in the post residual.
    let slots10 = post_residual / 10;
    score -= (slots10 as f64) * 3.0;

    // Perfect fit reward (harmonic zero class).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does the next item fit harmonically into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item's own post residual mod-10 class
        let next_post = post_residual - next_item_size;
        let nm = next_post % 10;
        let lookahead_reward = if nm == 0 { 18.0 } else if next_post == 0 { 30.0 } else { 6.0 };
        score -= lookahead_reward;
    } else if next_item_size > 0 {
        // Next item cannot use this bin's remainder: penalize small dead space more.
        if post_residual < 10 {
            score += 12.0;
        } else if post_residual < 20 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fitting bins exist:
    // new-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; offset by how full the fleet is.
        score += 55.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 20.0;
        // If mean residual across open bins can accommodate typical items, discourage new bin.
        if mean_residual >= item_size as f64 {
            score += 15.0;
        }
        // If next item is large and this item is small, a fresh bin preserves
        // flexibility for big items elsewhere: mild discount.
        if next_item_size > 60 && item_size < 30 {
            score -= 10.0;
        }
    } else {
        // Favor bins whose residual is closest to the item (tight packing),
        // scaled by fleet size to avoid over-fragmentation.
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.15;
        // Fleet pressure: with many open bins, prefer filling existing ones.
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    // Harmonic guard: prefer residuals in the "good class" set {0,10,...,100}
    // via a quadratic penalty on deviation from the nearest multiple of 10.
    let dev = post_mod.min(10 - post_mod) as f64;
    score += dev * dev * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let dead_zone = 12.0; // gaps below this are hard to fill (min item ~1..100, but small tails waste space)
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving a gap that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // creates dead space relative to lookahead
        } else if post_residual >= next_item_size && post_residual - next_item_size < 8 {
            score -= 8.0; // leaves a near-perfect slot for next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 5.0 + 2.5 * open_bins_count as f64;
        // But allow opening when existing residuals are all small/dead.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 12.0;
        }
    }

    // Mild preference for tight fits relative to mean residual.
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post-residual weighted heavily).
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead: if next item fits exactly into post_residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well the next item fills leftover space.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable fragments relative to the minimum item size (10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Global pressure: many open bins with high mean residual -> encourage consolidation
    // into existing bins (penalize opening new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64 / (1.0 + mean_residual / 20.0)).ln_1p();
    score += 6.0 * pressure * (0.5 + progress);

    // New-bin candidate handling: an empty bin has zero waste now but defers packing.
    // Make it attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base new-bin cost grows with number of open bins (fragmentation penalty).
        score += 8.0 + 1.5 * open_bins_count as f64;
        // But if existing bins would leave very large dead space, allow new bin:
        // (post_residual here equals capacity - item_size; if item is huge, fresh bin is fine)
        if item_size >= 70 {
            score -= 20.0;
        }
        // Late in the stream, slightly prefer reusing (new bins cost more).
        score += 10.0 * progress;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Mild bonus for bins already below mean residual (balancing residual distribution).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post-residual in [0,1]
    let p = progress;
    // Smooth interaction: tight fits rewarded more as stream progresses
    let tight = (1.0 - prn) * (1.0 - prn); // quadratic tightness
    score -= 30.0 * tight * (0.5 + p);

    // Penalize large dead space with cubic growth, amplified early
    score += 8.0 * prn * prn * prn * (1.2 - p);

    // Last-chance bin bonus (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - p * 0.5);
    }

    // Encourage filling bins when many bins are open
    let open_f = open_bins_count as f64;
    score -= 4.0 * tight * (open_f / (open_f + 5.0));

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            let gapn = gap / cap;
            score -= 10.0 * (1.0 - gapn * gapn);
        } else {
            // post-residual too small for next item: penalize proportionally
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mild mean-residual coupling: prefer bins near the mean (balance)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover is.
    // Residuals that are multiples of common small item sizes (10..20 bands)
    // are more likely to be filled later; penalize awkward leftovers.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division thresholds on post_residual: classify leftover space.
    let class = post_residual / 10; // 0..=10 harmonic band
    match class {
        0 => score += 25.0,               // dead space (<10) is nearly unusable
        1 | 2 => score += 8.0,            // narrow slivers
        3 | 4 | 5 => score -= 6.0,        // mid leftovers pair well with 30-50 items
        6 | 7 => score -= 10.0,           // sweet spot: fits most common items
        _ => score -= 4.0,                // large leftovers are fine but wasteful
    }

    // Exact-fit bonus via modulo arithmetic on capacity fractions.
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    } else if bin_capacity % post_residual == 0 && post_residual <= bin_capacity / 2 {
        score -= 12.0; // leftover divides capacity evenly -> reusable class
    }

    // Lookahead coupling: reward if next item fits the post residual,
    // penalize harmonic mismatch otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // extra reward when next item leaves another well-classed residual
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 8.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when current leftovers
    // are badly fragmented relative to mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - pr).abs();
        score += 18.0 - 15.0 * (1.0 - progress) - fragmentation * 0.3;
        if post_residual as f64 > mean_residual {
            score -= 5.0;
        }
    }

    // Mild pressure to prefer bins with below-average residual (tighter packs).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Penalize tiny item into huge bin (wasteful harmonic mismatch).
    if item_size * 4 < bin_residual {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // breaks the lookahead item's fit
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        score -= 10.0;
        score += mean_residual * 0.15; // if open bins are full-ish, new bin is cheap
        if post_residual + item_size >= 90 {
            score -= 5.0; // fresh bin keeps large flexibility
        }
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // this placement chains perfectly -> heavily reward.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportional to how tightly the next item fits.
            if slack <= 10.0 {
                score -= 150.0 - slack * 5.0;
            } else {
                score -= 50.0 / slack.sqrt();
            }
        } else {
            // Next item won't fit here: penalize leaving residual smaller
            // than the next item (likely dead space unless tiny).
            let gap = (next_item_size - post_residual) as f64;
            score += 30.0 + gap * 0.8;
            if post_residual < 10 {
                score += 40.0; // tiny unusable fragment
            }
        }
    }

    // Compare against mean residual: bins with residual well below mean
    // are "tight" — placing here consolidates space, reward it.
    let res_f = post_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.6;
    } else {
        score += (res_f - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: only open a new bin when the current
    // item is large relative to capacity or fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual > 0
            && (next_item_size as f64) > res_f { 1.0 } else { 0.0 };
        let pressure = open_bins_count as f64 * 0.5;
        score += 80.0 - pressure - poor_fit * 60.0
               + (item_size as f64) * 0.3;
    }

    // Late-stream tightening: as the stream progresses, prefer tighter
    // packing to close out bins cleanly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic decay of score as post_residual -> 0
    score -= (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3) * 30.0;

    // Perfect fit: exact fill is ideal
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space penalty: leftover that likely can't host future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }

    // Last chance bin: strongly favor if this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // chain fit
        } else if next_item_size <= post_residual {
            score -= (post_residual as f64 - next_item_size as f64).max(0.0) * 0.3;
        } else {
            // next item won't fit here; penalize leaving medium gaps
            score += 5.0;
        }
    }

    // New bin candidate handling: penalize opening new bins unless existing
    // bins have poor fit (post_residual large relative to capacity)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        // New bin is attractive only if best existing fit is bad and many items remain
        score = 60.0 + waste_ratio * 20.0 - progress * 30.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // new bin may serve next item too
        }
    }

    // Global dispersion: if mean residual is low, bins are nearly full;
    // prefer spreading into emptier bins (higher bin_residual than mean)
    let spread = bin_residual as f64 - mean_residual;
    score -= spread * 0.2;

    // Late stream: waste matters more as we approach the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear shaping of small residuals
    let mut score = norm_pr * norm_pr * 120.0 + norm_pr * 40.0;

    // Smooth stream-progress coupling: early on tolerate slack, late tighten
    let phase = progress * std::f64::consts::PI;
    score += norm_pr * (1.0 - progress) * 30.0 * (phase.sin() + 1.0);

    // Penalize dead space relative to mean residual (quadratic divergence)
    let dev = norm_pr - mean_residual / cap;
    score += dev * dev * 60.0;

    // Reward near-perfect fits (post_residual small) with cubic discount
    score -= (1.0 - norm_pr).powi(3) * 25.0;

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Lookahead: bonus if next item can use the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= 20.0 * fit_quality * fit_quality;
        } else {
            score += 12.0 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty for bin proliferation
    score += (open_bins_count as f64).ln() * 2.0;

    // New-bin candidate: make it unattractive unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that form "usable" classes
    // for future items (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    // Dead-space classes: small unusable leftovers (1..10) are penalized hard.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Perfect fit gets a large reward.
    if pr == 0 {
        score -= 60.0;
    }

    // Harmonic classes: reward residuals that are multiples of common sizes (10, 20, 25, 50)
    let harmonic = |r: u32| -> f64 {
        if r == 0 { return 0.0; }
        if r % 10 == 0 { -8.0 }
        else if r % 25 == 0 { -6.0 }
        else if r % 20 == 0 { -5.0 }
        else if r >= 30 { -2.0 }
        else { 4.0 } // awkward mid residuals
    };
    score += harmonic(pr);

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            // next item fits: reward proportional to how well it packs the rest
            let r2 = pr - next_item_size;
            score += harmonic(r2);
            score -= 6.0;
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            score += (next_item_size - pr) as f64 * 0.35;
        }
    }

    // Integer-division threshold on post_residual: classify usable space.
    let class = pr / 10; // coarse harmonic class 0..10
    match class {
        0 => { if pr > 0 { score += 12.0; } }      // crumbs
        1 => { score += 3.0; }                      // 10-19: only tiny items
        2 | 3 => { score -= 1.0; }                  // moderate
        4 | 5 => { score -= 4.0; }                  // 40-59: versatile
        _ => { score -= 2.0; }                      // large residual: fine
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it competitive only when current bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score = 100.0 - crowded * 8.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin attractive
        }
    }

    // Slight preference for fuller bins overall.
    score -= (bin_residual - post_residual) as f64 * 0.05;

    // Stream progression: late in stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        // Medium dead space: moderate penalty scaled by gap size.
        score += (20.0 - post_residual as f64) * 0.8;
    } else {
        // Large usable residual: reward keeping flexible space.
        score -= (post_residual as f64 - 20.0) * 0.15;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open bins pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // next item won't fit in leftover: penalize
    }

    // New empty bin candidate: only attractive when no open bin offers a decent fit
    // or current bin would leave tiny dead space.
    if bin_residual == bin_capacity {
        let base = 55.0 + open_bins_count as f64 * 1.2;
        if fitting_bins_count == 0 {
            return 0.0; // must open new bin
        }
        if post_residual < 10 && fitting_bins_count == 1 {
            return base - 20.0; // dead space unavoidable here, new bin comparable
        }
        return base;
    }

    // Progress: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Mean residual coupling: prefer bins close to mean residual (balanced packing).
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Aggressive 2-step lookahead: strongly reward bins where the next item also fits.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            // Perfect chain fit: the residual exactly absorbs the next item.
            score -= nxt * 0.7;
            if post == nxt {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here: penalize proportional dead space for it.
            score += (nxt - post) * 0.35;
        }
    }

    // Penalize bins whose post-residual is far below the fleet mean (fragmentation).
    let post_f = post_residual as f64;
    if post_f + 10.0 < mean_residual {
        score += (mean_residual - post_f) * 0.2;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a fresh bin unless the fit elsewhere is bad;
    // slightly more acceptable early in the stream.
    if bin_residual == bin_capacity {
        score += 18.0 + 12.0 * progress;
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) < item_size as f64 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that can't fit a typical next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size && post_residual < next_item_size * 2 {
            score -= 6.0; // residual can host the lookahead item
        }
    }

    // Last-chance bonus: only one bin fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, mildly discourage fragmenting scarce residuals.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate logic: only open a new bin when existing residuals are poor.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        // If mean residual is large and well above item, opening new bin is wasteful.
        let slack = mean_residual - item_size as f64;
        if slack > 0.0 {
            score += 20.0 + slack;
        } else {
            // Existing bins barely fit; opening fresh bin may be fine.
            score -= 8.0 + (-slack);
        }
        // Late in stream, avoid opening new bins (waste).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // Early stream: consolidating into open bins slightly favored.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Discourage leaving residuals in the awkward 1..10 zone (unusable dead space).
    if post_residual >= 1 && post_residual < 10 {
        score += 10.0;
    }

    // Mild preference for bins below mean residual (balance load across bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Penalize opening many bins when few needed: scale new-bin cost with open count.
    if is_new_bin {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer small post residual, with smooth polynomial shaping.
    let mut score = post + 40.0 * post_norm * post_norm * cap;

    // Tight fits (small post residual) are extra valuable late in the stream.
    let tightness = 1.0 - post_norm;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that is too small to be useful later (smooth coupling).
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = post - next;
        if gap >= 0.0 {
            score -= 15.0 * (1.0 - (gap / cap).min(1.0)) * (1.0 - progress);
        } else {
            score += 10.0 * (-gap / cap) * (0.5 + progress);
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count <= 1 {
        score -= 30.0 * (1.0 - post_norm);
    }

    // Mild pressure against proliferating many open bins with large mean residual.
    score += 0.02 * open_bins_count as f64;
    score += 0.05 * (mean_residual - post).abs();

    // Smooth stream-progress coupling: late stream favors consolidation.
    score += 20.0 * progress * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Residuals divisible by large divisors pair with many item sizes.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit, best outcome
    } else if pr % 10 == 0 {
        -6.0
    } else if pr % 5 == 0 {
        -3.0
    } else if pr % 25 == 0 {
        -5.0
    } else {
        2.0 // awkward remainder
    };
    score += class_bonus;

    // Penalize very small dead space (wasted capacity) more than proportionally.
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // offers a tight fit (post_residual small) — otherwise penalize opening.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0; // base cost of opening a bin
        if fitting_bins_count > 0 {
            score += 20.0; // an open bin exists that fits; discourage new bin
        }
        // If the next item is large and this bin is fresh, fresh bin is fine.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Fractional capacity thresholds: reward filling past half, then 3/4.
    let fill = (bin_capacity - post_residual) as f64 / cap_f;
    if fill >= 0.75 {
        score -= 5.0;
    } else if fill >= 0.5 {
        score -= 2.0;
    }

    // Slight preference to balance residual spread when many bins are open.
    score += ((post_residual as f64) - mean_residual).abs() * 0.05 * (open_bins_count.min(20) as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (post_residual in 1..=10 is nearly worthless)
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    score += open_bins_count as f64 * 0.8;

    // Prefer bins whose residual is close to the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // creates dead space for the known next item
    }

    // New-bin candidate: keep it attractive only when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        if avg_pressure < 0.25 && open_bins_count > 0 {
            score -= 15.0; // open bins mostly empty, fine to open new
        } else {
            score += 25.0 + open_bins_count as f64 * 0.5; // prefer filling existing bins
        }
    }

    // Slight preference for fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fit (low dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0 + (10 - post_residual) as f64 * 20.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the
    // next item size exactly or closely (chain packing).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 500.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let gap = post_residual as f64 - next;
            if gap <= 10.0 {
                score -= 300.0 - gap * 10.0; // near-chain bonus
            } else {
                score -= 50.0 / gap; // mild reward for any viable chain
            }
        } else {
            // Next item cannot follow into this bin: penalize proportionally
            // to how much of the bin's remaining usefulness is wasted.
            let waste = next - post_residual as f64;
            score += waste * 2.0;
        }
    }

    // Compare post_residual against mean residual: leaving residual far above
    // mean wastes capacity; far below mean risks dead space.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - pr) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // Penalize opening a new bin when good fitting bins exist, especially
    // early/mid stream where bin count matters most.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it only wins when open bins fit badly.
        score += 350.0 - 150.0 * progress;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin perfectly chains with the next item.
            if (bin_capacity as f64 - next as f64).abs() < 1.0 {
                score -= 100.0;
            }
        }
    }

    // Slight preference for tighter bins overall (best-fit baseline shaping).
    score += (bin_residual as f64) * 0.1;

    // Mild penalty for accumulating many open bins with large residuals.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that can't fit a typical next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // unusable sliver for the lookahead item
    }

    // Lookahead synergy: bonus if post_residual exactly accommodates next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            score -= 3.0;
        }
    } else {
        // Last item: just minimize leftover, tight fits dominate.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Time horizon: early in stream, be pickier about wastage; late, prefer reuse.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 2.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Global state: many open bins with high mean residual -> discourage new bins implicitly
    // by making existing bins cheaper; few open bins -> new bins more acceptable.
    let openness = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).sqrt();
    score += openness * (post_residual as f64 - mean_residual) * 0.15;

    // Brand-new bin candidate: neutral-ish base; open only when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.3 * open_bins_count as f64;
        // If next item is large and current item is small, a fresh bin may be fine.
        if next_item_size > 70 && item_size < 30 {
            score -= 12.0;
        }
    }

    // Mild penalty for very small post_residual fragments (dead space) unless exact fit.
    if post_residual > 0 && post_residual < 10 && post_residual != next_item_size {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: reward tight fits (small post_residual), with non-linear squashing
    let mut score = (pr * pr) / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer leaving moderately usable space; later, prefer very tight packing
    let phase = progress * std::f64::consts::PI;
    let early_weight = 0.5 * (1.0 + (phase).cos());       // ~1 early, ~0 late
    let late_weight = 1.0 - early_weight;                 // ~0 early, ~1 late

    // Usability curve: post-residuals near multiples of small items are valuable
    let usability = (norm_pr * std::f64::consts::PI).sin().abs();
    score += early_weight * 12.0 * (1.0 - usability) * norm_pr;
    score -= late_weight * 18.0 * usability * (1.0 - norm_pr);

    // Non-linear interaction: post_residual vs mean residual deviation
    let dev = (pr as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 + late_weight);

    // Reward filling a bin nearly full, stronger late in stream
    score -= late_weight * 25.0 * (norm_item * norm_item);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + late_weight);
    } else {
        // mild penalty when many alternatives exist, scaled non-linearly
        score += 2.0 * ((fitting_bins_count as f64).ln().max(0.0)) * early_weight;
    }

    // Lookahead: penalize if post_residual cannot fit next item but is still large
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 6.0 * (1.0 - pr / nxt.max(1.0)) * (1.0 - late_weight * 0.5);
        } else {
            score -= 4.0 * (1.0 - (pr - nxt) / cap) * usability;
        }
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Make it attractive only when item is large or stream is early.
    if bin_residual == bin_capacity {
        let empty_bonus = 15.0 * (1.0 - norm_item) * (1.0 - late_weight) + 5.0;
        score = score - empty_bonus + 10.0 * norm_item * late_weight;
        // penalize opening new bins when good alternatives exist
        if fitting_bins_count > 1 {
            score += 20.0 + 10.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Slight preference for consolidating among many open bins
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on a
    // "reusable" residue class (large, item-compatible space) are rewarded.
    let pr = post_residual;
    let residue_class = pr % 10;
    // Dead-space penalty: leftover below the smallest plausible item (<=10)
    // is nearly useless -> strong penalty.
    if pr < 10 {
        score += 60.0;
    } else if pr < 20 {
        score += 15.0;
    }

    // Reward leftovers that can host a wide range of future items.
    // Harmonic tiering via integer division thresholds.
    let tier = pr / 25; // 0..4 tiers
    score -= tier as f64 * 8.0;

    // Lookahead coupling: if the next item fits exactly in the post-residual
    // (perfect chaining), strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after chaining matters
            let chained = pr - next_item_size;
            if chained < 10 {
                score += 10.0; // would create fresh dead space
            } else {
                score -= 12.0;
            }
        } else {
            // next item cannot use this bin's leftover; leftover value drops
            score += 5.0;
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Perfect fit bonus (harmonic alignment with capacity fractions).
    if pr == 0 {
        score -= 50.0;
    } else if bin_capacity % pr == 0 {
        score -= 6.0; // leftover divides capacity evenly -> reusable class
    }

    // Penalize residue classes known to be awkward (odd small remainders).
    if pr >= 10 && residue_class != 0 && residue_class < 5 {
        score += 4.0;
    }

    // Mild pressure toward consolidation when many bins are open.
    score += open_bins_count as f64 * 0.15;

    // Slight preference to fill bins tightly relative to mean residual state.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (post_residual as f64 / cap) * (1.0 - progress) * 5.0;

    // New-bin candidate: neutral baseline with mild conservatism so it is
    // chosen only when open bins score poorly (large/dead leftovers).
    if bin_residual == bin_capacity {
        score = 35.0 + item_size as f64 * 0.2;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 - item_size.min(bin_capacity as u32) {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (post_residual < 10)
    // are the worst outcome; punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight fit bonus relative to bin capacity.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness * tightness;

    // Pressure from number of open bins: discourage opening new bins
    // when many are already open (unless dead space penalty dominates).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).sqrt() * (8.0 + 6.0 * progress);

    // New-bin candidate handling: only attractive if the item is large
    // relative to the bin and few bins are open.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * (open_bins_count as f64);
        if item_size >= 50 {
            score -= 25.0;
        }
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > post_residual {
            score += 10.0;
        } else {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64);
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is
    // close to the mean to keep bin states homogeneous.
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain fit
        } else if next_item_size < post_residual {
            score -= 100.0 - (post_residual - next_item_size) as f64;
        } else {
            // next item cannot follow here: penalize wasted residual that is too small for typical items
            if post_residual < 10 {
                score += 50.0;
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        score += 150.0 + open_bins_count as f64 * 5.0;
        // but allow new bin if item is large and few bins fit
        if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 200.0;
        }
    }

    // Prefer filling bins that are already mostly full (small residual)
    score += (bin_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Penalize creating dead space smaller than the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward proportional to leftover after next.
            let after_next = post_residual - next_item_size;
            score -= 10.0 + (after_next as f64) * 0.2;
        } else {
            // next item won't fit here: penalize slightly more when residual is close.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Global state: prefer filling bins when many bins are open (consolidation).
    let openness = open_bins_count as f64;
    score -= (openness / (openness + 5.0)) * (bin_residual as f64) * 0.3;

    // Prefer bins whose residual deviates below the mean (fill the emptier bins first? no:
    // actually prefer bins close to mean to keep residuals homogeneous, enabling future fits).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Time horizon: early in stream, be conservative (favor tight fits more);
    // late in stream, prefer using existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 15.0;

    // New-bin candidate: penalize opening a new bin unless the item is large and
    // no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 50 && post_residual < 20 {
            score -= 45.0; // large item with poor fit elsewhere deserves a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Non-linear tight-fit reward: strong bonus when post_residual is small,
    // scaled smoothly by stream progress (tight packing matters more later).
    let tightness = 1.0 - (post / cap);
    let tight_bonus = tightness * tightness * tightness * (12.0 + 24.0 * progress);
    score -= tight_bonus;

    // Penalize large dead space with a quadratic term, modulated by mean residual
    // (avoid creating a bin much worse than the fleet average).
    let dead = post / cap;
    score += 6.0 * dead * dead * (1.0 + (mean_residual / cap));

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // unless the fit is terrible.
    if fitting_bins_count <= 1 {
        score -= 18.0 * (1.0 - dead * dead);
    }

    // Lookahead coupling: reward bins whose post_residual can still host the
    // next item; penalize when post_residual is stranded between 0 and next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - ((post - nxt) / cap).min(1.0));
        } else if post > 0.0 {
            score += 10.0 * (1.0 - (nxt - post) / nxt.max(1.0)) * (1.0 - progress);
        }
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // fits well; add a mild opening penalty that decays with progress.
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress) * (1.0 - progress);
    } else {
        // Slight preference for filling existing bins over opening new ones.
        score -= 3.0 * (1.0 - progress);
    }

    // Smooth polynomial interaction between item size and residual pressure.
    let size_norm = item / cap;
    score += 4.0 * size_norm * size_norm * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by residue mod 10
    let class = post_residual % 10;
    // Residues that are "dead" (too small for most items) get penalized
    let dead_penalty = match class {
        1 | 2 | 3 => 12.0,
        4 | 5 => 6.0,
        9 => 3.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Reward exact harmonic fits (post_residual divisible by common item granularities)
    if post_residual % 10 == 0 {
        score -= 4.0;
    }
    if post_residual % 20 == 0 {
        score -= 2.0;
    }

    // Coupling with lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 15.0;
        } else if gap <= 5 {
            score -= 8.0;
        } else {
            score += gap as f64 * 0.25;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize proportionally to overshoot
        let overshoot = next_item_size - post_residual;
        score += overshoot as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: prefer opening a new bin only when current bin fit is poor
    if bin_residual == bin_capacity {
        // neutral base; good fits into existing bins should beat this
        score = 40.0 + post_residual as f64 * 0.1;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference for bins with low residual relative to mean (tight packing)
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Penalize leaving huge residuals when item is small (wasteful)
    if item_size <= 30 && post_residual >= 60 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals that are small but nonzero are hard to fill.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable tiny gap
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 10.0;
        }
    } else {
        score -= 40.0; // perfect fit
    }

    // Reward tight fits (small post_residual relative to item size)
    score += (item_size as f64) * 0.05;

    // Open bin pressure: discourage proliferating bins
    score += open_bins_count as f64 * 0.3;

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, reward this placement
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        }
    }

    // Mean residual coupling: if this bin's post-residual is far below mean, it's a good consolidation
    score += (mean_residual - post_residual as f64) * 0.1;

    // New empty bin candidate: penalize opening a new bin unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // future large items may justify a fresh bin
        }
    }

    // Progression: as stream advances, be more conservative about new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // next item fits here afterwards: strongly reward closeness of fit
            score -= 300.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
            // chain fit: two items packed tightly
            if post_residual == next_item_size {
                score -= 500.0;
            }
        } else {
            // dead space for the next item: penalize proportionally
            score += 2.5 * (nxt - post_residual as f64);
        }
    }

    // Tight fit reward relative to mean residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness;

    // Penalize bins deviating from mean residual (prefer balanced residual landscape)
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1);
        if poor_fit {
            score -= 150.0;
        } else {
            // discourage opening new bins when open bins can take the item
            score += 350.0 + 10.0 * open_bins_count as f64;
        }
    }

    // Mild stream-progression pressure: consolidate more as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty so near-perfect placements dominate.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64).powi(2) * 40.0;

    // Reward bins that become exactly full.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving residual that next item cannot use (dead space risk).
        score += 8.0;
    }

    // Prefer filling bins with small residuals relative to the fleet mean
    // (consolidate waste into few bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Early in the stream: be more willing to spread across bins (keep flexibility);
    // late in the stream: pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // New-bin candidate: neutral-ish score so it wins only when open bins are bad fits.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.75
            - progress * 20.0
            + if next_item_size > 0 && next_item_size >= item_size { 5.0 } else { 0.0 };
        if fitting_bins_count == 1 {
            score += 30.0; // don't abandon the sole fitting bin
        }
    }

    // Slight penalty for proliferating many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let mut score = x * x * cap;
    // non-linear coupling with stream progress: prefer tight fits early, penalize waste later
    let coupling = 30.0 * (1.0 - progress) * x * (1.0 - x) * 4.0;
    score += coupling;
    // lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = ((pr - nx) / cap).powf(2.0);
            score -= 12.0 * slack * (0.5 + progress);
        } else {
            score += 8.0 * ((nx - pr) / cap) * (0.5 + progress);
        }
    }
    // last-chance bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x);
    }
    // mild penalty when many bins are open and residual is wastefully large
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * x;
    // deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 0.5 * ((pr as f64 - mean_residual) / cap).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary tightness reward: quadratic bonus for small post_residual.
    score -= 0.9 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3) * (bin_capacity as f64);

    // Harmonic class of post_residual: classify dead space quality.
    // Residuals that are multiples of small granularity (e.g. 10) are "usable" classes.
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 12.0,                 // perfectly reusable class
        1..=4 => score += 6.0,              // razor-thin slivers, likely dead
        5..=9 => score -= 2.0,              // moderately usable
        _ => {}
    }

    // Integer-division threshold: post_residual >= 40 is comfortable for mid items.
    if pr / 40 >= 1 {
        score -= 8.0;
    }
    // Very large post_residual (wasteful placement of small item in big bin)
    if pr / 70 >= 1 {
        score += 10.0;
    }

    // Lookahead coupling: if next item can fit into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 15.0 + 0.25 * (pr - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to how close it missed.
        score += 5.0 + 0.10 * (next_item_size - pr) as f64;
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish score tied to mean residual state.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing residuals are fragmented,
        // i.e. mean residual is small relative to item needs.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 30.0 + 0.3 * mean_residual - 25.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // Don't open new bin if a decent fit exists elsewhere.
        if fitting_bins_count >= 2 {
            score += 15.0;
        }
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize gaps too small to fit the lookahead item (dead space for next arrival).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits (small post_residual) beyond the raw linear term.
    let tight_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tight_fit * 8.0;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 2.5 * (0.5 + progress);

    // Prefer bins below mean residual (filling the emptiest bins first keeps spread tight).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: mild penalty so it's chosen only when open bins are truly poor.
    if bin_residual == bin_capacity {
        score += 25.0 + post_residual as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        let exact = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + exact);
        // Perfect two-item fill (zero waste after next item) gets a big bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize dead space
        score += 15.0;
    }

    // Prefer tight fits relative to mean residual
    let mr = if mean_residual > 0.0 { mean_residual } else { 1.0 };
    let tightness = post_residual as f64 / mr;
    score += 5.0 * (tightness - 1.0).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bin is very tight or lookahead pairs well
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 30.0 + 0.5 * waste;
        if next_item_size > 0 && post_residual >= next_item_size {
            let exact = (post_residual as i64 - next_item_size as i64).abs() as f64;
            if exact < 5.0 {
                score -= 45.0;
            }
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on wasted residual, amplified for large dead space.
        let waste = (post_residual as f64 / bin_capacity as f64).powf(2.0);
        score += 60.0 * waste;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // penalize bins that strand a large unusable gap relative to lookahead.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.3 * next_item_size as f64;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit is poor.
    if bin_residual == bin_capacity {
        let crowdedness = (open_bins_count as f64).ln().max(0.0);
        let fit_quality = item_size as f64 / bin_capacity as f64;
        score += 80.0 - 15.0 * crowdedness - 30.0 * fit_quality;
        // Late in stream, prefer consolidating into existing bins.
        score += 30.0 * progress;
    }

    // Prefer bins tighter than the fleet average (good consolidation).
    score += 0.4 * (bin_residual as f64 - mean_residual).max(0.0);

    // Early in the stream, be more willing to spread items (keep flexibility);
    // late in the stream, consolidate aggressively.
    score -= 10.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth coupling of post_residual with stream progress:
    // early on, keep residuals flexible; late, squeeze hard.
    let squeeze = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += squeeze * pr * pr_norm * 6.0;

    // Penalize bins far from mean residual (smooth quadratic deviation)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr_norm);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 * (next_item_size as f64 / cap);
        } else {
            score += 4.0 * (pr_norm - next_item_size as f64 / cap).abs();
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.3 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: make it attractive only when residuals are tight
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.6 * progress) - 10.0 * (1.0 - mean_residual / cap);
        if fitting_bins_count == 1 {
            score += 40.0; // discourage opening new bin when an existing one is last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (small enough to be likely filled by future items)
    // are rewarded; large awkward leftovers are penalized.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // Small residues (0..=3) are near-perfect fits -> strong reward.
        if class <= 3 {
            score -= 12.0 - (class as f64) * 2.0;
        }
        // Mid residues are neutral.
        // Dead-space zone: leftover too big to waste but too small for typical items.
        if pr > 0 && pr < 10 {
            score -= 8.0; // near-perfect closure
        } else if pr >= 10 && pr <= 20 {
            score += 4.0; // awkward mid gap
        }
    } else {
        score -= 15.0; // perfect fill
    }

    // Integer-division thresholds on post_residual: leftover that can host
    // common small items is valuable.
    let small_slots = pr / 10;
    score -= (small_slots as f64) * 3.0;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack % 10 <= 3 {
                score -= 6.0;
            }
            score -= (10 - (slack % 10).min(10 - 1)) as f64 * 0.3;
        } else {
            // next item cannot follow here: penalize proportionally
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or
    // the item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / (mean_residual.max(1.0));
        if fitting_bins_count == 0 || pressure > 1.2 {
            score -= 8.0;
        } else {
            score += 6.0 + (open_bins_count as f64) * 0.2;
        }
    }

    // Late-stream consolidation: fewer bins is better near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.05 * progress;

    // Mild tie-break toward tighter fits.
    score += (bin_residual - item_size) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item (<= 10) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small gaps are likely unusable dead space.
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // fresh space; encourage filling existing bins.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item almost fits, small penalty to keep gaps usable.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large or existing residuals are poor.
    if bin_residual == bin_capacity {
        // Base new-bin score: neutral post_residual (capacity - item).
        // Add a mild bonus early on (bins are cheap), penalty later.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 25.0 * progress;

        // If existing bins are fragmented (high mean residual spread unused),
        // opening fresh is worse.
        score += 0.15 * mean_residual;

        // Large items fit anywhere in a fresh bin; slight preference.
        if item_size >= 50 {
            score -= 8.0;
        }
    } else {
        // Existing bin: reward keeping mean residual low (compactness).
        score -= 0.05 * mean_residual;
    }

    // Mild preference for bins with residual close to item (best-fit core).
    let gap = (bin_residual - item_size) as f64;
    score += 0.3 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 30.0;

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        // Perfect 2-chain: item + next item fills bin nicely.
        let chain_quality = 1.0 - (slack_after_next as f64 / bin_capacity as f64);
        score -= chain_quality * 40.0;
        // Extra bonus if next item leaves another small usable remainder.
        if slack_after_next <= 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: next item cannot use this residual.
        score += 20.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize residuals that are too small to ever fit anything (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Compare against mean residual: prefer filling below-average-residual bins.
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Late in the stream, be more conservative: favor compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // New-bin candidate (empty bin): penalize unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Opening a new bin is attractive when the item is huge and lookahead is small.
        if item_size >= 70 && next_item_size <= item_size {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for scattering across many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (zero waste).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead (k=2): reward bins whose leftover can still host the next item,
    // scaled by how much room remains for it.
    if next_item_size > 0 && next_item_size as u32 <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + 0.15 * next_item_size as f64 + 0.05 * slack;
    }
    // Penalize leaving a residual too small for the upcoming item when the
    // residual is tiny (likely dead space).
    if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        score += 0.1 * post_residual as f64 * (1.0 - progress);
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Global pressure: when many bins are open and their mean residual is low,
    // consolidating into existing space is valuable.
    let mean_pressure = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
    score -= 5.0 * mean_pressure * (open_bins_count as f64).sqrt();

    // New-bin candidate handling (bin_residual == bin_capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Early in the stream, discourage spreading into fresh bins.
        score += 6.0 + 18.0 * (1.0 - progress);
        // If no bins are open at all, opening is necessary: remove the penalty.
        if open_bins_count == 0 {
            score -= 24.0;
        }
        // If existing bins are nearly full (low mean residual), a new bin is
        // more acceptable; soften the penalty.
        score -= 10.0 * mean_pressure;
        // Large items waste less relative space in a fresh bin; slight relief.
        score -= 0.05 * item_size as f64;
    } else {
        // Tight-fit reward for existing bins: the smaller the leftover relative
        // to the item, the better the placement.
        let tightness = 1.0 - (post_residual as f64 / cap).clamp(0.0, 1.0);
        score -= 6.0 * tightness;
    }

    // Late-stream consolidation: as the horizon closes, favor filling existing
    // bins aggressively.
    score -= 8.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fit)
    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // later in the stream, dead space becomes more costly (quadratic/cubic in norm_pr)
    let p2 = norm_pr * norm_pr;
    let p3 = p2 * norm_pr;
    score += (0.6 + 2.4 * progress) * p2 * cap;
    score += (0.2 + 1.5 * progress) * p3 * cap;

    // Reward near-exact fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= (1.0 + 3.0 * progress) * tightness * tightness * item;

    // Penalize leaving residual that fails to fit the next item (smooth gate)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0);
        let gate = 1.0 - (-gap / (item + 1.0)).exp();
        score += (2.0 + 3.0 * progress) * gate * nx;
        // Reward residual that exactly accommodates next item
        let nx_fit = (pr - nx).abs();
        score -= (1.5 + 2.0 * progress) * (1.0 - (nx_fit / cap).min(1.0)) * nx;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 12.0 * progress;
    }

    // Mild pressure toward consolidating into fewer bins
    score -= 0.15 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers that are multiples of 10
    // are "harmonic" (likely reusable by typical item sizes); prime-ish remainders are dead space.
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 6.0;
    } else {
        // Penalize non-harmonic leftovers, worse the smaller (more dead) they are.
        score += (10 - (post_residual % 10)) as f64 * 0.5;
    }

    // Integer-division thresholds: classify post_residual into dead-space bands.
    let band = post_residual / 10;
    score += match band {
        0 => 30.0,          // post_residual < 10: nearly dead space
        1 => 12.0,          // 10..19: hard to reuse
        2 | 3 => -2.0,      // 20..39: decent
        _ => -5.0,          // >= 40: very reusable
    };

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0 - (slack % 10) as f64 * 0.3;
            if slack % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this bin's leftover; penalize tight leftovers more.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // current placement would create bad dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 10.0;
        // If this item would leave a poor leftover in any existing bin, new bin looks better;
        // emulate by checking whether item is large relative to capacity.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 {
            score -= 12.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // Many open bins with low mean residual: discourage another bin.
        if mean_residual < 30.0 && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Mild consolidation pressure: bins tighter than average are preferred targets.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f).min(20.0) * 0.2;
    }

    // Small tie-break toward tighter bins overall.
    score += (bin_capacity as f64 - resid_f) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // realistic future item (items >= 1, but small gaps < ~15 are wasteful)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 * (15.0 - post_residual as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.5 * next_item_size as f64;
        } else {
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Pressure from number of open bins: when many bins are open, prefer
    // filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    // so large gaps stay available for large future items.
    score += 0.4 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: only attractive when no open bin fits well or the
    // item is large relative to the mean residual of open bins.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > mean_residual;
        let no_fitters = fitting_bins_count == 0;
        if poor_fit || no_fitters {
            score -= 25.0 + 0.2 * item_size as f64;
        } else {
            score += 50.0 + 0.5 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else if post_residual > next_item_size {
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to leftover dead space
            score += 10.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // last item: prefer tightest fit
        score += 5.0;
    }

    // Relative to mean residual: prefer bins with residuals below average (compact them)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Penalize creating tiny unusable slivers (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when current bin fits poorly
    if bin_residual == bin_capacity {
        let tight_fit = (bin_capacity - item_size) as f64;
        score = tight_fit + 10.0;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 30.0; // fresh bin can host current + next
        }
    }

    // Mild stream-phase adaptation: later in stream, be greedier about tight fits
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * phase * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (bin_capacity as f64) * 0.8;

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 25.0 + next_item_size as f64 * 0.3;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // penalize blocking the next item
        score += 15.0;
    }

    // Time horizon: later in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    // Many open bins: prefer filling existing ones over opening new
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += open_pressure * 2.0;

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio > 0.5 || (fitting_bins_count <= 1 && post_residual as f64 > mean_residual);
        if poor_fit {
            score -= 45.0;
        } else {
            score += 30.0;
        }
    }

    // Mean residual coupling: prefer bins near mean residual (balanced usage)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = prn * (1.0 + 0.6 * prn * prn);

    // Smooth interaction: dead-space penalty grows with stream progress
    score += 3.0 * t * prn * prn;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 2.5 * t * (1.0 - prn) * (1.0 - prn) * fit;

    // Last-chance bonus: smooth coupling with fitting_bins_count
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 2.0 * last_chance * prn * (1.0 - t * 0.5);

    // Lookahead: penalize if post-residual can't fit next item but is large
    let nxt = next_item_size as f64 / cap;
    if nxt > 0.0 {
        let gap = (prn - nxt).max(0.0);
        let waste = if prn < nxt { prn } else { 0.0 };
        score += 1.5 * waste + 0.8 * gap * gap;
    }

    // Mean residual coupling: avoid bins far from mean residual (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 0.5 * dev * dev;

    // Mild new-bin avoidance: opening new bins costs more late in stream
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into residue classes modulo a base quantum.
    // Small post_residuals in "good" classes (multiples of common item sizes) are more reusable.
    let quantum: u32 = 10;
    let class = post_residual % quantum;

    // Reward post-residuals that are exact multiples of the quantum (clean fill levels).
    if class == 0 && post_residual > 0 {
        score -= 6.0;
    } else {
        // Penalize awkward dead space: tiny unusable slivers.
        if post_residual < 10 {
            score += 12.0 * (1.0 - post_residual as f64 / 10.0);
        } else {
            score += 2.0 * (class as f64 / quantum as f64);
        }
    }

    // Lookahead: does next_item_size fit into the post-residual? Harmonic match via division.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Strong reward if next item divides the post-residual evenly (harmonic fit).
        if post_residual % next_item_size == 0 {
            score -= 8.0;
        } else {
            score -= 4.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to how far off it is.
        score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fill_ratio * fill_ratio;

    // Prefer bins with below-mean residual (denser bins) to keep mean slack spread out.
    score += 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // New-bin candidate: only attractive when no open bin fits or open set is saturated.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 15.0;
        } else if open_bins_count > 0 {
            score += 8.0;
        }
    }

    // Mild stream-phase coupling: early on, keep bins open loosely; later, pack tightly.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * phase * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1) can ever
    // use are pure waste; residuals below the smallest practical item are near-waste.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: ideal
    } else if post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 4.0; // tiny unusable gap
    } else if post_residual < 20 {
        score += 8.0; // poor gap, only very small items fit
    } else if post_residual < 35 {
        score += 2.0; // moderate gap
    } else {
        score -= 6.0; // large residual stays flexible
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current bin would leave
    // a very poor gap or open-bin pressure is high.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // pressure: many open bins -> discourage more bins
        score += open_bins_count as f64 * 2.0;
        // but if this bin would be a perfect home, allow it
        if item_size == bin_capacity {
            score -= 200.0;
        }
        // lookahead: if next item would fit in the fresh residual, soften cost
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
    }

    // Lookahead synergy: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        score -= (next_item_size as f64) * 0.3;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0; // gap kills the lookahead item
    }

    // Mild pressure toward consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 - mean_residual / 10.0).max(0.0) * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: strongly reward bins where the NEXT item also fits the leftover.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual minus next item leaves the smallest waste.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 40.0 + 0.6 * (bin_capacity as f64 - chain_waste) * 0.1;
            // Exact fill of the two-item chain is ideal.
            if chain_waste == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to how close it is
            // (wasted potential) unless post_residual is tiny (dead space anyway).
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Penalize dead space that is too small to ever hold a plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral-ish score so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        // A fresh bin has full residual; make it unattractive unless lookahead chain
        // is perfect there (handled above via next_item_size fit on full residual).
        score += 20.0;
        // Early in the stream, opening bins is cheap; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild tie-break against mean residual: prefer bins with residual below mean
    // (concentrate filling of emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Prefer bins with many fitting alternatives less (keep flexibility)? No:
    // slight penalty for spreading across many bins.
    score += 0.5 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.5 * fill_ratio * (item_size as f64);

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0; // near-perfect fit, minimal dead space
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Lookahead: if the next item can also fit into the post residual, this bin
    // remains useful; reward that. If not, the leftover is likely dead space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Leftover too small for the next item -> penalize proportionally.
            score += 0.3 * (post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a new bin wastes its full capacity unless
    // the current item is large. Penalize the fresh-bin option, more so when
    // many bins are open and mean residual is still healthy.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += waste;
        score += 5.0 * (open_bins_count as f64).sqrt();
        score += 0.2 * mean_residual;
        // Late in the stream, avoid opening bins for small items.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress * (1.0 - item_size as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is already below average (consolidate small leftovers).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Mild preference for reusing bins when many are open.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = 1.0 + 0.6 * progress - 0.4 * progress * progress;
    score *= poly;

    // Penalize dead space that is too small to be useful, scaled by progress
    let dead = (prn - 0.5 * prn * prn) * (prn - 0.2);
    score += 40.0 * dead.abs() * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly early in the stream
    score -= (1.0 - prn) * (1.0 - prn) * 15.0 * (1.2 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: prefer bins whose residual can still fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - pr / (pr + nxt));
        } else {
            score += 6.0 * (1.0 - pr / (pr + nxt));
        }
    }

    // Mild penalty when bin deviates from mean residual (balance pressure)
    score += 0.05 * ((pr - mean_residual) / cap).abs() * cap * (0.3 + 0.7 * progress);

    // Slight bias against opening many new bins late in the stream
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable"
    // residue classes (multiples of small denominators) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Integer division thresholds: post_residual bucketed by quarters of capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if pr <= quarter / 2 {
        score -= 35.0; // tiny dead space, nearly perfect
    } else if pr <= quarter {
        score -= 15.0;
    } else if pr <= half {
        score -= 5.0;
    } else {
        score += 10.0; // large leftover: wasteful placement
    }

    // Modulo arithmetic: leftover divisible by common small sizes (10/20/25/50)
    // is reusable by future items.
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 10.0; }
        // Harmonic fraction: leftover is a clean fraction of capacity
        let frac = (pr as f64) / cap;
        if (frac * 4.0).round() / 4.0 == frac {
            score -= 6.0;
        }
    }

    // Lookahead: reward leaving exactly enough room for the next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 40.0;
        } else if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // leftover too small for next item: penalize proportionally to dead space
            score += 12.0 * (next_item_size - pr) as f64 / cap;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // more competition: mild tie-break toward tighter fit
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when open bins are quite full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let penalty = 120.0 * (1.0 - pressure) * (0.5 + 0.5 * (1.0 - progress));
        score += penalty;
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Mild preference for filling bins that are already well loaded.
    score -= 0.05 * (bin_capacity.saturating_sub(bin_residual)) as f64;

    // Slight noise-free deterministic tie-break via step parity of item class.
    if (item_size % 3) == (pr % 3) && pr > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable" band
    // (small gaps that few future items can fill) is heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space: too small for any item (min size 1..100 unknown, treat <10 as risky)
            score += 40.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual <= 20 {
            // Marginal gap: only tiny items fit
            score += 18.0;
        } else if post_residual < 50 {
            // Moderate gap: partially reusable
            score += 6.0;
        }
        // post_residual >= 50 is healthy; base score already rewards it.
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Exact-fit lookahead: if the next item fits the post residual exactly,
    // reward this bin strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Next item cannot use this gap: penalize proportionally
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open
    // and this bin is a reasonable fit.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins count
        // and stream progression (late in stream, keep consolidating).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 + 0.6 * open_bins_count as f64 + 15.0 * progress;
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 0.3 * open_bins_count.min(20) as f64;
    }

    // Mean-residual coupling: prefer bins with residual below the mean
    // (tighter packing), penalize bins far above mean residual.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight preference for tighter fits beyond post_residual itself.
    score += 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already favored).

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match => strong bonus; near match => partial bonus.
        score -= 60.0 * (1.0 - diff / 100.0).max(0.0);
        // Penalize post_residual that is too small for next item (dead space trap),
        // but only mildly if next item could still be split across other bins.
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: pure tightness, no lookahead concerns.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight";
    // filling them further is good if fit is tight, bad if it leaves crumbs.
    let res = post_residual as f64;
    if res < mean_residual {
        // Below-mean bin: reward using it (consolidation) unless it creates tiny residue.
        if res > 0.0 && res < 10.0 {
            score += 25.0; // crumb penalty: unusable dead space
        } else {
            score -= 8.0;
        }
    } else {
        // Above-mean bin: using it keeps tight bins free; slight reward.
        score -= 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin gives a good fit,
    // i.e. when this empty bin would receive the item with a large residual
    // that still matches the next item well, or when open bins are crowded.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score += 45.0;
        // Offset if stream is early (plenty of future items to fill it) and
        // the new bin's post-residual matches the next item nicely.
        if next_item_size > 0 && post_residual >= next_item_size {
            let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 40.0 * (1.0 - diff / 100.0).max(0.0);
        }
        // Crowding: many open bins with low mean residual => don't open more.
        if mean_residual > 40.0 {
            score -= 10.0;
        }
        // Late in the stream, prefer reusing existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    score
}
